async function createPrediction(channelId, title, windowSeconds, outcomes) {
  const colors = ['BLUE', 'PINK', 'ORANGE', 'GREEN', 'TEAL', 'PURPLE', 'YELLOW', 'LIGHT_BLUE', 'RED', 'BROWN']
  return predictionMutation(
    'CreatePredictionEvent',
    'createPredictionEvent',
    'mutation($input: CreatePredictionEventInput!) { createPredictionEvent(input: $input) { error { code } } }',
    {
      input: {
        channelID: channelId,
        title,
        predictionWindowSeconds: windowSeconds,
        outcomes: outcomes.map((t, i) => ({ title: t, color: colors[i] || colors[0] })),
      },
    },
  )
}

// Route a mutation through Twitch's own Apollo client in the MAIN world.
// searchTerm: string to find the webpack module (e.g. 'AcceptPredictionTerms')
// variables: GQL variables object
// resultField: the mutation's return field name (for error extraction)
// rawQuery: optional fallback raw query string
function apolloMutate({ searchTerm, variables, resultField, rawQuery }) {
  return new Promise((resolve) => {
    const id = Math.random().toString(36).slice(2)
    const ac = new AbortController()
    const signal = mcSignal ? AbortSignal.any([mcSignal, ac.signal]) : ac.signal
    const handler = (e) => {
      if (e.source !== window || e.origin !== location.origin) return
      if (e.data?.type === 'heatsync-apollo-mutate-response' && e.data.id === id) {
        ac.abort()
        clearTimeout(timer)
        resolve(e.data.data || { error: 'no response' })
      }
    }
    window.addEventListener('message', handler, { signal })
    // Only include rawQuery when caller provided one — the MAIN-world security
    // gate rejects any message that has the rawQuery field set, even if empty
    // string. Apollo path loads Document from webpack so rawQuery is optional.
    const msg = {
      type: 'heatsync-apollo-mutate',
      id,
      searchTerm,
      variables,
      resultField,
      nonce: window.HS?.getMainWorldNonce?.() || null,
    }
    if (rawQuery) msg.rawQuery = rawQuery
    window.postMessage(msg, location.origin)
    const timer = setTimeout(() => {
      ac.abort()
      resolve({ error: 'apollo mutation timeout' })
    }, 8000)
  })
}

async function acceptPredictionTerms() {
  const result = await apolloMutate({
    searchTerm: 'AcceptPredictionTerms',
    variables: { input: { hasAcceptedTOS: true } },
    resultField: 'updateUserPredictionSettings',
    rawQuery:
      'mutation($input: UpdateUserPredictionSettingsInput!) { updateUserPredictionSettings(input: $input) { error { code } settings { hasAcceptedTOS } } }',
  })
  return !!result.ok
}

// Known working persisted query hashes (from Twitch's own client). Hashes
// auto-update from live Twitch traffic on twitch.tv pages via early-inject
// gql.hashes capture; this map is the fallback seed for first-call before any
// page traffic, and for code paths that don't have MAIN-world access.
const TWITCH_HASHES = {
  MakePrediction: 'b44682ecc88358817009f20e69d75081b1e58825bb40aa53d5dbadcc17c881d8',
  // Follow / unfollow — needed for cross-platform follow propagation. Twitch
  // killed the public follow REST API in Aug 2023, so this is the only path.
  FollowButton_FollowUser: '800e7346bdf7e5278a3c1d3f21b2b56e2639928f86815677a7126b093b2fdd08',
  FollowButton_UnfollowUser: 'f7dae976ebf41c755ae2d758546bfd176b4eeb856656098bb40e0a672ca0d880',
  // Followers-only chat mode — the web client can't call Helix /chat/settings
  // (404), so chat modes go through this GQL persisted mutation. Captured from
  // twitch.tv. followersOnlyDurationMinutes: -1=off, 0=any follower, N=minutes.
  SetFollowersOnlyModeSetting: '0ee2e448691c84b4be72bcd1ae6c51fcf512414fe372e502fe67d3c7eaf8da31',
}

// Route mutation through MAIN world proxy (has integrity token) with direct fetch fallback
async function gqlMutation(query, variables) {
  try {
    const data = await gqlProxy('twitchGql', variables || {}, { rawQuery: query })
    const d = Array.isArray(data) ? data[0] : data
    return d?.data ? d : { data: d }
  } catch {
    return twitchGql(query, variables)
  }
}

// Use persisted query hash for MakePrediction — raw queries are dead for mutations
async function gqlPersistedMutation(operationName, variables) {
  const hash = TWITCH_HASHES[operationName]
  if (!hash)
    return gqlMutation(
      'mutation ' +
        operationName +
        '($input: ' +
        operationName +
        'Input!) { ' +
        operationName.replace(/^[A-Z]/, (c) => c.toLowerCase()) +
        '(input: $input) { error { code } } }',
      variables,
    )
  const token = getTwitchAuthToken()
  const hdrs = { 'Content-Type': 'application/json', 'Client-Id': 'kimne78kx3ncx6brgo4mv6wki5h1ko' }
  if (token) hdrs['Authorization'] = 'OAuth ' + token
  try {
    const resp = await fetch('https://gql.twitch.tv/gql', {
      method: 'POST',
      headers: hdrs,
      body: JSON.stringify({
        operationName,
        variables,
        extensions: { persistedQuery: { version: 1, sha256Hash: hash } },
      }),
      signal: AbortSignal.timeout(8000),
    })
    if (!resp.ok) throw new Error('GQL ' + resp.status)
    return resp.json()
  } catch (directErr) {
    // Firefox CORS fallback — route through MAIN world proxy with hash
    try {
      const data = await gqlProxy(operationName, variables)
      const d = Array.isArray(data) ? data[0] : data
      return d?.data ? d : { data: d }
    } catch {
      throw directErr
    }
  }
}

async function placePredictionBet(eventId, outcomeId, points, transactionId) {
  const token = getTwitchAuthToken()
  if (!token) return { error: 'not logged in' }
  try {
    const isTosError = (d) => {
      const msg = d?.errors?.[0]?.message || ''
      const code = d?.data?.makePrediction?.error?.code || ''
      return msg.includes('ACCEPT') || msg.includes('TOS') || code.includes('ACCEPT') || code.includes('TOS')
    }
    const tryBet = () => {
      const makeInput = { eventID: eventId, outcomeID: outcomeId, points, transactionID: crypto.randomUUID() }
      return gqlPersistedMutation('MakePrediction', { input: makeInput })
    }

    let data = await tryBet()
    if (isTosError(data)) {
      await acceptPredictionTerms()
      for (let attempt = 0; attempt < 3; attempt++) {
        await new Promise((r) => setTimeout(r, 500 * (attempt + 1)))
        data = await tryBet()
        if (!isTosError(data)) break
      }
    }
    if (data?.errors?.length) return { error: data.errors[0].message }
    const mutError = data?.data?.makePrediction?.error
    if (mutError) return { error: mutError.code || 'bet failed' }
    if (_userBets.size > 50) _userBets.delete(_userBets.keys().next().value)
    _userBets.set(eventId, { outcomeId, points })
    return { ok: true }
  } catch (e) {
    return { error: e.message }
  }
}

async function fetchChannelRewards(channelLogin) {
  const safe = channelLogin.replace(/[^a-z0-9_]/g, '')
  if (!safe) return null
  if (_rewardsCacheChannel === safe && _rewardsCache && Date.now() - _rewardsCache.fetchedAt < 60000) {
    return _rewardsCache
  }
  const token = getTwitchAuthToken()
  if (!token) return null
  try {
    // Try proxy with captured ChannelPointsContext hash first
    const data = await gqlProxy('ChannelPointsContext', { channelLogin: safe }).catch(() => null)
    let user = null
    if (data) {
      const d = Array.isArray(data) ? data[0] : data
      user = d?.data?.community?.channel || d?.data?.user || d?.community?.channel || d?.user
    }
    // Fallback: try raw GQL (may work for some fields)
    if (!user) {
      const resp = await fetch(TWITCH_GQL, {
        method: 'POST',
        headers: {
          'Client-Id': TWITCH_CLIENT_ID,
          'Content-Type': 'application/json',
          Authorization: `OAuth ${token}`,
        },
        signal: AbortSignal.timeout(5000),
        body: JSON.stringify({
          query: `{
            user(login: "${safe}") {
              id
              communityPointsSettings {
                customRewards {
                  id title cost backgroundColor isEnabled isPaused isInStock
                  isUserInputRequired cooldownExpiresAt prompt
                  globalCooldownSetting { globalCooldownSeconds isEnabled }
                  image { url }
                  defaultImage { url }
                }
              }
              self {
                communityPoints {
                  balance
                  availableClaim { id }
                }
              }
            }
          }`,
        }),
      })
      if (resp.ok) {
        const raw = await resp.json()
        user = raw?.data?.user
      }
    }
    if (!user) return null
    const settings = user.communityPointsSettings || user.communityPointsSetting || {}
    const rewards = (settings.customRewards || []).filter((r) => r.isEnabled)
    const self = user.self || {}
    const cp = self.communityPoints || {}
    const balance = cp.balance ?? null
    const availableClaim = cp.availableClaim?.id ?? null
    _rewardsCache = { rewards, balance, availableClaim, channelId: user.id, fetchedAt: Date.now() }
    _rewardsCacheChannel = safe
    return _rewardsCache
  } catch (e) {
    log('Failed to fetch rewards:', e.message)
    return null
  }
}

async function redeemChannelReward(channelId, rewardId, cost, title, textInput) {
  const token = getTwitchAuthToken()
  if (!token) return { error: 'not logged in' }
  try {
    const input = {
      channelID: channelId,
      rewardID: rewardId,
      cost,
      title,
      transactionID: crypto.randomUUID(),
    }
    if (textInput) input.textInput = textInput
    // Try proxy first (uses captured hash + integrity)
    try {
      const data = await gqlProxy('RedeemCommunityPointsCustomReward', { input })
      const d = Array.isArray(data) ? data[0] : data
      if (d?.errors?.length) return { error: d.errors[0].message }
      const err = d?.data?.redeemCommunityPointsCustomReward?.error
      if (err) return { error: err.code || 'redemption failed' }
      return { ok: true }
    } catch (proxyErr) {
      // Fallback to raw GQL mutation
      const resp = await fetch(TWITCH_GQL, {
        method: 'POST',
        headers: {
          'Client-Id': TWITCH_CLIENT_ID,
          'Content-Type': 'application/json',
          Authorization: `OAuth ${token}`,
        },
        body: JSON.stringify({
          query: `mutation($input: RedeemCommunityPointsCustomRewardInput!) {
            redeemCommunityPointsCustomReward(input: $input) {
              redemption { id }
              error { code }
            }
          }`,
          variables: { input },
        }),
      })
      if (!resp.ok) return { error: `HTTP ${resp.status}` }
      const data = await resp.json()
      if (data?.errors?.length) return { error: data.errors[0].message }
      const err = data?.data?.redeemCommunityPointsCustomReward?.error
      if (err) return { error: err.code || 'redemption failed' }
      return { ok: true }
    }
  } catch (e) {
    return { error: e.message }
  }
}

async function claimCommunityPoints(claimId, channelId, channelLogin) {
  const token = getTwitchAuthToken()
  if (!token) return false
  let claimed = false
  try {
    await gqlProxy('ClaimCommunityPoints', {
      input: { claimID: claimId, channelID: channelId },
    }).catch(async () => {
      // Fallback to raw GQL
      const resp = await fetch(TWITCH_GQL, {
        method: 'POST',
        headers: {
          'Client-Id': TWITCH_CLIENT_ID,
          'Content-Type': 'application/json',
          Authorization: `OAuth ${token}`,
        },
        body: JSON.stringify({
          query: `mutation($input: ClaimCommunityPointsInput!) {
            claimCommunityPoints(input: $input) { claim { id } }
          }`,
          variables: { input: { claimID: claimId, channelID: channelId } },
        }),
        signal: AbortSignal.timeout(8000),
      })
      if (!resp.ok) throw new Error('HTTP ' + resp.status)
    })
    claimed = true
  } catch (e) {
    log('Failed to claim bonus points:', e.message)
  }
  // Silent claim — toast was noisy when tracking multiple channels (e.g.
  // nl_kripp claims firing while viewing asmongold247). Points still credit;
  // the toast was the only visible signal and the user explicitly didn't
  // want it. Re-enable behind a setting if needed in future.
  // if (claimed && channelLogin) {
  //   try { window.HsNotifs?.emit?.('toast', { text: '+50 · ' + channelLogin, level: 'success' }) } catch (_) {}
  // }
  return claimed
}

// Persist active poll to storage (survives reloads; Twitch has no public poll query)
function _savePollToStorage(poll, channelId) {
  if (!poll?.id) return
  try {
    chrome.storage.local.set({ hs_active_poll: { poll, channelId, savedAt: Date.now() } })
  } catch {}
}
function _clearPollFromStorage() {
  try {
    chrome.storage.local.remove('hs_active_poll')
  } catch {}
}

// Recompute remainingDurationMilliseconds from startedAt + durationSeconds
function _refreshPollTiming(poll) {
  if (!poll?.startedAt || !poll?.durationSeconds) return poll
  const elapsed = Date.now() - new Date(poll.startedAt).getTime()
  const totalMs = poll.durationSeconds * 1000
  poll.remainingDurationMilliseconds = Math.max(0, totalMs - elapsed)
  // Auto-mark as completed if time expired
  if (poll.remainingDurationMilliseconds <= 0 && poll.status === 'ACTIVE') {
    poll.status = 'COMPLETED'
  }
  return poll
}

async function fetchPoll(channelLogin) {
  const safe = channelLogin.replace(/[^a-z0-9_]/g, '')
  if (!safe) return null
  try {
    // 1. Check GQL interception cache (from Twitch's own traffic)
    for (const key of ['ActivePoll', 'ChannelPollContext']) {
      const c = _gqlDataCache[key]
      if (c && Date.now() - c.ts < 15000) {
        const poll = c.data?.user?.activePoll || c.data?.channel?.activePoll || null
        if (poll) {
          _refreshPollTiming(poll)
          _savePollToStorage(poll, c.data?.user?.id || _twitchChannelId)
          const isMod = c.data?.user?.self?.isModerator || _twitchIsMod
          return { poll, channelId: c.data?.user?.id || _twitchChannelId, isMod }
        }
      }
    }
    // 2. Check persistent storage (survives reloads, no 15s TTL)
    //    activePoll is persisted-query-only — no public GQL query exists
    try {
      const stored = await chrome.storage.local.get('hs_active_poll')
      const entry = stored?.hs_active_poll
      if (entry?.poll && entry.channelId === _twitchChannelId) {
        const poll = _refreshPollTiming(entry.poll)
        // Clear expired/completed polls from storage
        if (poll.status === 'COMPLETED' || poll.status === 'ARCHIVED' || poll.status === 'TERMINATED') {
          _clearPollFromStorage()
        } else {
          return { poll, channelId: entry.channelId, isMod: _twitchIsMod }
        }
      }
    } catch {}
    return { poll: null, channelId: _twitchChannelId, isMod: _twitchIsMod }
  } catch (e) {
    log('Failed to fetch poll:', e.message)
    return null
  }
}

async function votePoll(pollId, choiceId) {
  const token = getTwitchAuthToken()
  if (!token) return { error: 'not logged in' }
  try {
    // Try proxy first
    try {
      const data = await gqlProxy('VotePoll', {
        input: { pollID: pollId, choiceID: choiceId },
      })
      const d = Array.isArray(data) ? data[0] : data
      if (d?.errors?.length) return { error: d.errors[0].message }
      const err = d?.data?.votePoll?.error
      if (err) return { error: err.code || 'vote failed' }
      return { ok: true }
    } catch (proxyErr) {
      // Fallback to raw GQL
      const resp = await fetch(TWITCH_GQL, {
        method: 'POST',
        headers: {
          'Client-Id': TWITCH_CLIENT_ID,
          'Content-Type': 'application/json',
          Authorization: 'OAuth ' + token,
        },
        body: JSON.stringify({
          query: 'mutation($input: VotePollInput!) { votePoll(input: $input) { error { code } } }',
          variables: { input: { pollID: pollId, choiceID: choiceId } },
        }),
        signal: AbortSignal.timeout(8000),
      })
      if (!resp.ok) return { error: 'HTTP ' + resp.status }
      const data = await resp.json()
      if (data?.errors?.length) return { error: data.errors[0].message }
      const err = data?.data?.votePoll?.error
      if (err) return { error: err.code || 'vote failed' }
      return { ok: true }
    }
  } catch (e) {
    return { error: e.message }
  }
}

const POLL_FIELDS =
  'id title status durationSeconds remainingDurationMilliseconds startedAt choices { id title totalVoters } totalVoters'

async function createTwitchPoll(channelId, title, durationSeconds, choices) {
  const rawQuery =
    'mutation($input: CreatePollInput!) { createPoll(input: $input) { poll { ' + POLL_FIELDS + ' } error { code } } }'
  const variables = {
    input: { ownedBy: channelId, title, choices: choices.map((t) => ({ title: t })), durationSeconds },
  }
  try {
    const data = await gqlMutation(rawQuery, variables)
    const result = data?.data?.createPoll
    if (result?.error) return { error: result.error.code || 'create poll failed' }
    if (data?.errors?.length) return { error: data.errors[0].message || 'create poll failed' }
    const poll = result?.poll
    if (poll) {
      _gqlDataCache['ActivePoll'] = { data: { user: { activePoll: poll, id: channelId } }, ts: Date.now() }
      _savePollToStorage(poll, channelId)
    }
    return { ok: true, poll }
  } catch (e) {
    return { error: e.message }
  }
}

async function endTwitchPoll(pollId) {
  const rawQuery =
    'mutation($input: TerminatePollInput!) { terminatePoll(input: $input) { poll { ' + POLL_FIELDS + ' } } }'
  const variables = { input: { pollID: pollId } }
  try {
    const data = await gqlMutation(rawQuery, variables)
    if (data?.errors?.length) return { error: data.errors[0].message || 'end poll failed' }
    const poll = data?.data?.terminatePoll?.poll
    if (poll) {
      _gqlDataCache['ActivePoll'] = { data: { user: { activePoll: poll, id: _twitchChannelId } }, ts: Date.now() }
    }
    _clearPollFromStorage()
    return { ok: true }
  } catch (e) {
    return { error: e.message }
  }
}

const _userPollVotes = new Map() // pollId → choiceId

function renderPoll(poll, channelId, isMod) {
  const section = document.createElement('div')
  section.className = 'hs-mc-poll'
  section.dataset.pollId = poll.id
  if (channelId) section.dataset.channelId = channelId

  const isCompleted = poll.status === 'COMPLETED' || poll.status === 'ARCHIVED'
  const totalVotes = poll.totalVoters || poll.choices.reduce((s, c) => s + (c.totalVoters || 0), 0)
  const userVote = _userPollVotes.get(poll.id)

  // Header
  const header = document.createElement('div')
  header.className = 'hs-mc-poll-header'
  const title = document.createElement('div')
  title.className = 'hs-mc-poll-title'
  title.textContent = poll.title
  header.appendChild(title)

  if (isCompleted) {
    const badge = document.createElement('span')
    badge.className = 'hs-mc-poll-status hs-mc-poll-status-ended'
    badge.textContent = t('mc_poll_ended')
    header.appendChild(badge)
  } else if (poll.remainingDurationMilliseconds != null) {
    const timer = document.createElement('span')
    timer.className = 'hs-mc-poll-timer'
    timer.dataset.ends = Date.now() + poll.remainingDurationMilliseconds
    header.appendChild(timer)
  }
  section.appendChild(header)

  // Total votes
  const meta = document.createElement('div')
  meta.className = 'hs-mc-poll-meta'
  meta.textContent = totalVotes + ' vote' + (totalVotes !== 1 ? 's' : '')
  section.appendChild(meta)

  // Choices
  const choicesWrap = document.createElement('div')
  choicesWrap.className = 'hs-mc-poll-choices'

  // Find top choice for winner highlight
  let topVotes = 0
  for (const c of poll.choices) {
    if ((c.totalVoters || 0) > topVotes) topVotes = c.totalVoters || 0
  }

  for (const choice of poll.choices) {
    const votes = choice.totalVoters || 0
    const pct = totalVotes > 0 ? Math.round((votes / totalVotes) * 100) : 0
    const isTop = isCompleted && votes === topVotes && topVotes > 0
    const isVoted = userVote === choice.id

    const row = document.createElement('div')
    row.className =
      'hs-mc-poll-choice' + (isTop ? ' hs-mc-poll-choice-top' : '') + (isVoted ? ' hs-mc-poll-choice-voted' : '')

    const track = document.createElement('div')
    track.className = 'hs-mc-poll-choice-track'
    const fill = document.createElement('div')
    fill.className = 'hs-mc-poll-choice-fill'
    fill.style.width = pct + '%'
    track.appendChild(fill)

    const label = document.createElement('div')
    label.className = 'hs-mc-poll-choice-label'

    const nameSpan = document.createElement('span')
    nameSpan.className = 'hs-mc-poll-choice-name'
    nameSpan.textContent = choice.title
    if (isVoted) {
      const check = document.createElement('span')
      check.className = 'hs-mc-poll-voted-check'
      check.textContent = ' \u2713'
      nameSpan.appendChild(check)
    }
    label.appendChild(nameSpan)

    const pctSpan = document.createElement('span')
    pctSpan.className = 'hs-mc-poll-choice-pct'
    pctSpan.textContent = pct + '%'
    label.appendChild(pctSpan)

    track.appendChild(label)
    row.appendChild(track)

    if (!isCompleted && !userVote) {
      const voteBtn = document.createElement('button')
      voteBtn.className = 'hs-mc-poll-vote-btn'
      voteBtn.dataset.pollId = poll.id
      voteBtn.dataset.choiceId = choice.id
      voteBtn.textContent = 'vote'
      row.appendChild(voteBtn)
    }

    choicesWrap.appendChild(row)
  }

  section.appendChild(choicesWrap)

  // Mod controls — end poll
  if (!isCompleted && isMod) {
    const modRow = document.createElement('div')
    modRow.className = 'hs-mc-poll-mod-row'
    const endBtn = document.createElement('button')
    endBtn.className = 'hs-mc-poll-mod-btn hs-mc-poll-end-btn'
    endBtn.dataset.pollId = poll.id
    endBtn.textContent = t('mc_poll_end')
    modRow.appendChild(endBtn)
    section.appendChild(modRow)
  }

  return section
}

function renderNoPoll(channelId, isMod) {
  const wrap = document.createElement('div')
  wrap.className = 'hs-mc-poll-empty'
  if (!isMod) return wrap

  const createWrap = document.createElement('div')
  createWrap.className = 'hs-mc-poll-create'
  if (channelId) createWrap.dataset.channelId = channelId

  const toggle = document.createElement('button')
  toggle.className = 'hs-mc-poll-mod-btn hs-mc-poll-create-toggle'
  toggle.textContent = t('mc_poll_new')
  createWrap.appendChild(toggle)

  const form = document.createElement('div')
  form.className = 'hs-mc-poll-create-form'
  form.style.display = 'none'

  const titleInput = document.createElement('input')
  titleInput.className = 'hs-mc-poll-create-input'
  titleInput.placeholder = t('mc_poll_question')
  titleInput.maxLength = 60
  form.appendChild(titleInput)

  for (let i = 0; i < 4; i++) {
    const opt = document.createElement('input')
    opt.className = 'hs-mc-poll-create-input hs-mc-poll-create-choice'
    opt.placeholder = t('mc_poll_choice', [String(i + 1)]) + (i < 2 ? '' : ' (' + t('mc_poll_optional') + ')')
    opt.maxLength = 25
    form.appendChild(opt)
  }

  const durRow = document.createElement('div')
  durRow.className = 'hs-mc-poll-create-dur-row'
  const durLabel = document.createElement('span')
  durLabel.className = 'hs-mc-poll-create-dur-label'
  durLabel.textContent = t('mc_pred_duration')
  durRow.appendChild(durLabel)
  for (const secs of [30, 60, 120, 300, 600, 1800]) {
    const btn = document.createElement('button')
    btn.className = 'hs-mc-poll-create-dur' + (secs === 60 ? ' hs-mc-poll-create-dur-active' : '')
    btn.dataset.secs = secs
    btn.tabIndex = -1
    btn.textContent = secs < 60 ? secs + 's' : secs / 60 + 'm'
    durRow.appendChild(btn)
  }
  form.appendChild(durRow)

  const submitBtn = document.createElement('button')
  submitBtn.className = 'hs-mc-poll-mod-btn hs-mc-poll-create-submit'
  submitBtn.tabIndex = -1
  submitBtn.textContent = t('mc_poll_create')
  form.appendChild(submitBtn)

  createWrap.appendChild(form)
  wrap.appendChild(createWrap)
  return wrap
}

// Optimistic UI update after voting — patch DOM immediately without round-trip
function optimisticPollVoteUpdate(pollSection, choiceId) {
  if (!pollSection) return
  const choices = pollSection.querySelectorAll('.hs-mc-poll-choice')
  const metaEl = pollSection.querySelector('.hs-mc-poll-meta')
  const totalMatch = metaEl?.textContent?.match(/(\d+)/)
  const oldTotal = totalMatch ? parseInt(totalMatch[1]) : 0

  // Reconstruct per-choice vote counts from percentages
  const entries = []
  for (const choice of choices) {
    const pctEl = choice.querySelector('.hs-mc-poll-choice-pct')
    const nameEl = choice.querySelector('.hs-mc-poll-choice-name')
    const voteBtn = choice.querySelector('.hs-mc-poll-vote-btn')
    const isTarget = voteBtn?.dataset?.choiceId === choiceId
    const oldPct = pctEl ? parseInt(pctEl.textContent) : 0
    let votes = oldTotal > 0 ? Math.round((oldPct / 100) * oldTotal) : 0
    if (isTarget) votes += 1
    entries.push({ choice, votes, pctEl, nameEl, voteBtn, isTarget })
  }

  const total = entries.reduce((s, v) => s + v.votes, 0) || 1
  if (metaEl) metaEl.textContent = total + ' vote' + (total !== 1 ? 's' : '')

  for (const { choice, votes, pctEl, nameEl, voteBtn, isTarget } of entries) {
    const pct = Math.round((votes / total) * 100)
    if (pctEl) pctEl.textContent = pct + '%'
    const fill = choice.querySelector('.hs-mc-poll-choice-fill')
    if (fill) fill.style.width = pct + '%'
    if (isTarget) {
      choice.classList.add('hs-mc-poll-choice-voted')
      if (nameEl && !nameEl.querySelector('.hs-mc-poll-voted-check')) {
        const check = document.createElement('span')
        check.className = 'hs-mc-poll-voted-check'
        check.textContent = ' \u2713'
        nameEl.appendChild(check)
      }
    }
    // Remove all vote buttons (user already voted)
    if (voteBtn) voteBtn.remove()
  }
}

function attachPollHandlers() {
  const container = document.getElementById('hs-mc-tab-twitch')
  if (!container) return

  container.querySelectorAll('.hs-mc-poll-vote-btn').forEach((btn) => {
    btn.addEventListener('click', async (e) => {
      e.stopPropagation()
      btn.disabled = true
      btn.textContent = '...'
      const result = await votePoll(btn.dataset.pollId, btn.dataset.choiceId)
      if (result.error) {
        btn.textContent = '!'
        btn.title = result.error
        setTimeout(() => {
          btn.textContent = 'vote'
          btn.disabled = false
          btn.title = ''
        }, 2000)
      } else {
        if (_userPollVotes.size > 50) _userPollVotes.delete(_userPollVotes.keys().next().value)
        _userPollVotes.set(btn.dataset.pollId, btn.dataset.choiceId)
        const pollSection = btn.closest('.hs-mc-poll')
        optimisticPollVoteUpdate(pollSection, btn.dataset.choiceId)
        setTimeout(() => refreshPollSlot(), 3000)
      }
    })
  })

  // End poll (mod)
  container.querySelectorAll('.hs-mc-poll-end-btn').forEach((btn) => {
    btn.addEventListener('click', async (e) => {
      e.stopPropagation()
      btn.disabled = true
      btn.textContent = '...'
      const result = await endTwitchPoll(btn.dataset.pollId)
      if (result.error) {
        btn.textContent = result.error
        btn.title = result.error
        setTimeout(() => {
          btn.textContent = t('mc_poll_end')
          btn.disabled = false
          btn.title = ''
        }, 3000)
      } else {
        btn.textContent = '\u2713'
        refreshPollSlot()
      }
    })
  })

  // Create poll toggle
  container.querySelectorAll('.hs-mc-poll-create-toggle').forEach((btn) => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation()
      const form = btn.parentElement.querySelector('.hs-mc-poll-create-form')
      if (form) {
        const showing = form.style.display !== 'none'
        form.style.display = showing ? 'none' : 'flex'
        btn.textContent = showing ? t('mc_poll_new') : t('mc_pred_cancel_form')
      }
    })
  })

  // Create poll duration picker
  container.querySelectorAll('.hs-mc-poll-create-dur').forEach((btn) => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation()
      container
        .querySelectorAll('.hs-mc-poll-create-dur')
        .forEach((b) => b.classList.remove('hs-mc-poll-create-dur-active'))
      btn.classList.add('hs-mc-poll-create-dur-active')
    })
  })

  // Create poll submit
  container.querySelectorAll('.hs-mc-poll-create-submit').forEach((btn) => {
    btn.addEventListener('click', async (e) => {
      e.stopPropagation()
      const createWrap = btn.closest('.hs-mc-poll-create')
      const channelId = createWrap?.dataset.channelId
      if (!channelId) {
        btn.textContent = 'no channel'
        return
      }
      const form = btn.closest('.hs-mc-poll-create-form')
      const inputs = form.querySelectorAll('.hs-mc-poll-create-input')
      const title = inputs[0]?.value?.trim()
      const choices = [...form.querySelectorAll('.hs-mc-poll-create-choice')].map((i) => i.value.trim()).filter(Boolean)
      if (!title) {
        inputs[0].focus()
        return
      }
      if (choices.length < 2) {
        form.querySelectorAll('.hs-mc-poll-create-choice')[choices.length]?.focus()
        return
      }
      const durBtn = form.querySelector('.hs-mc-poll-create-dur-active')
      const secs = parseInt(durBtn?.dataset.secs || '60')
      btn.disabled = true
      btn.textContent = '...'
      const result = await createTwitchPoll(channelId, title, secs, choices)
      if (result.error) {
        const errMap = {
          POLL_ALREADY_ACTIVE: t('mc_error_poll_active'),
          FORBIDDEN: t('mc_error_no_permission'),
          UNAUTHORIZED: t('mc_error_not_logged_in'),
        }
        const msg = errMap[result.error] || result.error
        btn.textContent = msg
        btn.title = result.error
        setTimeout(() => {
          btn.textContent = t('mc_poll_create')
          btn.disabled = false
          btn.title = ''
        }, 3000)
      } else {
        // Close create form so refreshPollSlot's guard doesn't skip
        form.style.display = 'none'
        refreshPollSlot()
      }
    })
  })

  // Create poll keyboard nav
  container.querySelectorAll('.hs-mc-poll-create-input').forEach((input) => {
    input.addEventListener('keydown', (e) => {
      if (e.key === 'Tab') {
        e.preventDefault()
        const inputs = [...container.querySelectorAll('.hs-mc-poll-create-input')]
        const idx = inputs.indexOf(input)
        const next = inputs[(idx + 1) % inputs.length]
        next?.focus()
      } else if (e.key === 'Enter') {
        e.preventDefault()
        container.querySelector('.hs-mc-poll-create-submit')?.click()
      } else if (e.key === 'Escape') {
        e.preventDefault()
        container.querySelector('.hs-mc-poll-create-toggle')?.click()
      }
    })
  })

  // Poll timers
  container.querySelectorAll('.hs-mc-poll-timer').forEach((el) => {
    const endsAt = parseInt(el.dataset.ends)
    const update = () => {
      const remaining = Math.max(0, Math.ceil((endsAt - Date.now()) / 1000))
      if (remaining <= 0) {
        el.textContent = t('mc_poll_ended')
        el.classList.add('hs-mc-poll-status-ended')
        return
      }
      const m = Math.floor(remaining / 60)
      const s = remaining % 60
      el.textContent = m > 0 ? m + ':' + String(s).padStart(2, '0') : s + 's'
    }
    update()
    const iv = cleanup.setIntervalIfVisible(() => {
      if (!el.isConnected) {
        cleanup.clearInterval(iv)
        return
      }
      update()
    }, 1000)
  })
}

const badgesInFlight = new Set()
const badgesFailedAt = new Map() // channelLogin -> ms (last failure) — LRU-capped at 100
const BADGE_FAILURE_BACKOFF_MS = 60000
const BADGES_FAILED_MAX = 100

async function fetchChannelBadges(channelLogin) {
  if (!channelLogin) return
  if (badgesFetchedChannels.has(channelLogin)) return
  if (badgesInFlight.has(channelLogin)) return
  // Backoff window after a failed fetch — without this, an early fetch that
  // failed (transient 5xx, network blip, empty data) used to permanently
  // poison the guard so badges fell back to the global star forever.
  const lastFail = badgesFailedAt.get(channelLogin)
  if (lastFail && Date.now() - lastFail < BADGE_FAILURE_BACKOFF_MS) return
  // Sanitize: Twitch logins are alphanumeric + underscore only
  const safe = channelLogin.replace(/[^a-z0-9_]/g, '')
  if (!safe) return
  badgesInFlight.add(channelLogin)
  let populated = false
  try {
    // Fetch channel badges (GQL broadcastBadges) + FFZ in parallel
    const [gqlResp, ffzResp] = await Promise.allSettled([
      twitchGql(`{ user(login:"${safe}") { broadcastBadges { imageURL(size: NORMAL) setID version } } }`),
      fetch(`https://api.frankerfacez.com/v1/room/${safe}`, { credentials: 'omit', signal: AbortSignal.timeout(5000) }),
    ])

    // Channel badges via GQL broadcastBadges (no Client-Integrity needed)
    if (gqlResp.status === 'fulfilled') {
      const badges = gqlResp.value?.data?.user?.broadcastBadges
      if (badges?.length) {
        const versionsBySet = new Map()
        for (const b of badges) {
          if (b.imageURL) {
            twitchBadgeUrls.set(`${channelLogin}:${b.setID}/${b.version}`, b.imageURL)
            populated = true
          }
          const v = parseInt(b.version, 10)
          if (Number.isFinite(v)) {
            let arr = versionsBySet.get(b.setID)
            if (!arr) {
              arr = []
              versionsBySet.set(b.setID, arr)
            }
            arr.push(v)
          }
        }
        for (const [setID, arr] of versionsBySet) {
          arr.sort((a, b) => a - b)
          channelBadgeVersions.set(`${channelLogin}:${setID}`, arr)
        }
      }
    }

    // FFZ custom mod/VIP badges — override Twitch versions
    if (ffzResp.status === 'fulfilled' && ffzResp.value.ok) {
      const ffz = await ffzResp.value.json()
      const room = ffz?.room
      if (room) {
        const modUrl = room.mod_urls?.['2'] || room.mod_urls?.['1'] || room.moderator_badge
        if (modUrl) {
          const src = modUrl.startsWith('//') ? 'https:' + modUrl : modUrl
          twitchBadgeUrls.set(`${channelLogin}:moderator/1`, src)
          ffzBadgeKeys.add(`${channelLogin}:moderator`)
          populated = true
        }
        const vipUrl = room.vip_badge?.['2'] || room.vip_badge?.['1']
        if (vipUrl) {
          const src = vipUrl.startsWith('//') ? 'https:' + vipUrl : vipUrl
          twitchBadgeUrls.set(`${channelLogin}:vip/1`, src)
          ffzBadgeKeys.add(`${channelLogin}:vip`)
          populated = true
        }
      }
    }

    if (populated) {
      badgesFetchedChannels.add(channelLogin)
      badgesFailedAt.delete(channelLogin)
      // Evict oldest channel if cache exceeds 20
      if (badgesFetchedChannels.size > 20) {
        const oldest = badgesFetchedChannels.values().next().value
        badgesFetchedChannels.delete(oldest)
        for (const key of twitchBadgeUrls.keys()) {
          if (key.startsWith(`${oldest}:`)) twitchBadgeUrls.delete(key)
        }
        for (const key of ffzBadgeKeys) {
          if (key.startsWith(`${oldest}:`)) ffzBadgeKeys.delete(key)
        }
        for (const key of channelBadgeVersions.keys()) {
          if (key.startsWith(`${oldest}:`)) channelBadgeVersions.delete(key)
        }
      }
      log('Loaded channel badges for', channelLogin)
      // Patch rows for this channel in-place: no epoch bump, no full rebuild,
      // no image-reload flash. Other tabs are invalidated via _dropAllTabCaches
      // inside updateNativeBadgesInPlace so they rebuild fresh on next switch.
      if (typeof updateNativeBadgesInPlace === 'function') updateNativeBadgesInPlace(channelLogin)
    } else {
      // No data populated — schedule retry after backoff
      if (badgesFailedAt.size >= BADGES_FAILED_MAX) {
        badgesFailedAt.delete(badgesFailedAt.keys().next().value)
      }
      badgesFailedAt.set(channelLogin, Date.now())
      log('No channel badges returned for', channelLogin, '— will retry after backoff')
    }
  } catch (e) {
    log('Failed to fetch channel badges:', e.message)
    if (badgesFailedAt.size >= BADGES_FAILED_MAX) {
      badgesFailedAt.delete(badgesFailedAt.keys().next().value)
    }
    badgesFailedAt.set(channelLogin, Date.now())
  } finally {
    badgesInFlight.delete(channelLogin)
  }
}

// Kick subscriber badges. Routes through BG (kick_channel_badges) so the
// cross-origin fetch isn't gated by the panel's CORS rules — panel may be on
// twitch.tv viewing a linked Kick channel. Populates twitchBadgeUrls under
// (slug):subscriber/(months) so renderBadges' channel-prefixed lookup picks
// them up without any caller change. No render-side effects — natural
// re-render on next msg picks up the new entries; calling renderMessages
// from here risked init-timing crashes.
// Kick badges live in their own Map so dual-link channels don't collide with
// Twitch's tier-encoded sub badge versions (1000/2000/3000 for tiers vs Kick's
// linear month numbers 1/2/3/6/12). renderBadges checks platform to pick which
// Map to use.
const kickBadgeUrls = new Map()
const kickChannelBadgeVersions = new Map()
const kickBadgesFetchedChannels = new Set()
const kickBadgesInFlight = new Set()
const kickBadgesFailedAt = new Map()

function findNearestKickBadgeVersion(channel, name, version) {
  const versions = kickChannelBadgeVersions.get(`${channel}:${name}`)
  if (!versions || versions.length === 0) return null
  const v = parseInt(version, 10)
  if (!Number.isFinite(v)) return null
  let best = -1
  for (const vv of versions) {
    if (vv > v) break
    if (vv > best) best = vv
  }
  return best >= 0 ? String(best) : null
}

async function fetchKickChannelBadges(slug) {
  if (!slug) return
  slug = String(slug).toLowerCase()
  if (kickBadgesFetchedChannels.has(slug)) return
  if (kickBadgesInFlight.has(slug)) return
  const lastFail = kickBadgesFailedAt.get(slug)
  if (lastFail && Date.now() - lastFail < BADGE_FAILURE_BACKOFF_MS) return
  kickBadgesInFlight.add(slug)
  try {
    const resp = await safeSendMessage({ type: 'kick_channel_badges', slug })
    if (!resp?.ok || !Array.isArray(resp.badges) || resp.badges.length === 0) {
      if (kickBadgesFailedAt.size >= BADGES_FAILED_MAX) {
        kickBadgesFailedAt.delete(kickBadgesFailedAt.keys().next().value)
      }
      kickBadgesFailedAt.set(slug, Date.now())
      return
    }
    const monthsList = []
    for (const b of resp.badges) {
      if (Number.isFinite(b.months) && typeof b.src === 'string') {
        kickBadgeUrls.set(slug + ':subscriber/' + b.months, b.src)
        monthsList.push(b.months)
      }
    }
    if (monthsList.length) {
      monthsList.sort((a, b) => a - b)
      kickChannelBadgeVersions.set(slug + ':subscriber', monthsList)
      kickBadgesFetchedChannels.add(slug)
      kickBadgesFailedAt.delete(slug)
      if (kickBadgesFetchedChannels.size > 20) {
        const oldest = kickBadgesFetchedChannels.values().next().value
        kickBadgesFetchedChannels.delete(oldest)
        const prefix = oldest + ':subscriber/'
        for (const key of [...kickBadgeUrls.keys()]) {
          if (key.startsWith(prefix)) kickBadgeUrls.delete(key)
        }
        kickChannelBadgeVersions.delete(oldest + ':subscriber')
      }
    }
  } catch (e) {
    if (kickBadgesFailedAt.size >= BADGES_FAILED_MAX) {
      kickBadgesFailedAt.delete(kickBadgesFailedAt.keys().next().value)
    }
    kickBadgesFailedAt.set(slug, Date.now())
  } finally {
    kickBadgesInFlight.delete(slug)
  }
}

function renderBadges(badgesStr, channel, platform) {
  if (!badgesStr) return ''
  const isKick = platform === 'kick'
  return badgesStr
    .split(',')
    .map((badge) => {
      const [name, version] = badge.split('/')
      let url = null
      if (isKick && channel) {
        // Kick-only lookup. Never fall through to Twitch URLs — Twitch sub badges
        // are keyed by tier-encoded versions (1000/2000/3000) which mismatch
        // Kick's linear month numbers (1/2/3/6/12); the Twitch findNearest would
        // return e.g. "subscriber/0" for Kick's "subscriber/1" producing a wrong
        // tier badge. Better to show the text-style chip when no Kick URL exists.
        url = kickBadgeUrls.get(`${channel}:${name}/${version}`)
        if (!url) {
          const nearest = findNearestKickBadgeVersion(channel, name, version)
          if (nearest != null) url = kickBadgeUrls.get(`${channel}:${name}/${nearest}`)
        }
      } else {
        // Channel-specific exact match → channel-specific nearest-tier (e.g. 5mo
        // sub on a channel that only defines 0/3/6 → use 3) → global exact →
        // global "/1" generic-star fallback.
        url = channel && twitchBadgeUrls.get(`${channel}:${name}/${version}`)
        if (!url && channel) {
          const nearest = findNearestChannelBadgeVersion(channel, name, version)
          if (nearest != null) url = twitchBadgeUrls.get(`${channel}:${name}/${nearest}`)
        }
        url = url || twitchBadgeUrls.get(`${name}/${version}`) || twitchBadgeUrls.get(`${name}/1`)
      }
      if (url) {
        // FFZ custom badges are white icons on transparent bg — add badge-type background
        const ffzKey = channel && `${channel}:${name}/`
        const isFFZ = ffzKey && ffzBadgeKeys.has(`${channel}:${name}`)
        const bgStyle =
          isFFZ && BADGE_STYLES[name] ? `background:${BADGE_STYLES[name].bg};padding:1px;border-radius:2px;` : ''
        const label = BADGE_STYLES[name]?.label || name
        return `<img class="hs-mc-badge-img" data-badge="${escapeHtml(name)}/${escapeHtml(version)}" src="${escapeHtml(safeUrl(url) || '')}" alt="${escapeHtml(name)}" title="${escapeHtml(label)}" loading="lazy" decoding="async" width="18" height="18" style="width:18px;height:18px;${bgStyle}">`
      }
      // Text fallback
      const style = BADGE_STYLES[name]
      if (!style) return ''
      return `<span class="hs-mc-badge" data-badge="${escapeHtml(name)}/${escapeHtml(version)}" style="background:${style.bg};color:${style.fg}" title="${escapeHtml(style.label)}">${style.label}</span>`
    })
    .join('')
}

function renderThirdPartyBadges(userId) {
  if (!userId) return ''
  let html = ''
  // Per-provider classes (hs-mc-{bttv,ffz,chatterino}-badge) let
  // updateThirdPartyBadgesInPlace dedup against rows already carrying the badge,
  // so a late bulk-map arrival patches cold rows in place instead of forcing a
  // full rebuild (the "loads then shifts" flash on channel switch).
  const bttv = getSetting('bttvBadges') ? mcBttvBadgeMap.get(userId) : null
  if (bttv) {
    html += `<img class="hs-mc-badge-img hs-mc-bttv-badge" src="${escapeHtml(safeUrl(bttv.url) || '')}" alt="${escapeHtml(bttv.description)}" title="${escapeHtml(bttv.description)}" loading="lazy" decoding="async" width="18" height="18" style="width:18px;height:18px;">`
  }
  const ffzList = getSetting('ffzBadges') ? mcFfzBadgeMap.get(userId) : null
  if (ffzList) {
    for (const b of ffzList) {
      const safeColor = /^#[0-9a-fA-F]{3,8}$/.test(b.color) ? b.color : ''
      html += `<img class="hs-mc-badge-img hs-mc-ffz-badge" src="${escapeHtml(safeUrl(b.url) || '')}" alt="${escapeHtml(b.title)}" title="${escapeHtml(b.title)}" loading="lazy" decoding="async" width="18" height="18" style="width:18px;height:18px;${safeColor ? 'background:' + safeColor + ';border-radius:2px;' : ''}">`
    }
  }
  const chat = getSetting('chatterinoBadges') ? mcChatterinoBadgeMap.get(userId) : null
  if (chat) {
    html += `<img class="hs-mc-badge-img hs-mc-chatterino-badge" src="${escapeHtml(safeUrl(chat.url) || '')}" alt="Chatterino" title="${escapeHtml(chat.tooltip || 'Chatterino')}" loading="lazy" decoding="async" width="18" height="18" style="width:18px;height:18px;">`
  }
  const cosmetic = getSetting('sevenTvPaints') ? mcUserCosmetics.get(userId) : null
  if (cosmetic?.badge) {
    const files = cosmetic.badge.host?.files || []
    const file =
      files.find((f) => f.name?.endsWith('.webp')) || files.find((f) => f.name?.endsWith('.avif')) || files[0]
    if (file) {
      const base = cosmetic.badge.host?.url || ''
      // 7TV returns protocol-relative URLs (//cdn.7tv.app/...) — promote to https
      // before validation so safeUrl doesn't drop them.
      const absBase = base.startsWith('//') ? 'https:' + base : base
      const rawUrl = (absBase.endsWith('/') ? absBase : absBase + '/') + file.name
      const url = safeUrl(rawUrl)
      if (url) {
        // Class includes hs-mc-7tv-badge so updateCosmeticsInPlace's dedup
        // selector finds it and doesn't insert a duplicate when the async
        // cosmetic fetch resolves after the inline render.
        html += `<img class="hs-mc-badge-img hs-mc-7tv-badge" src="${escapeHtml(safeUrl(url) || '')}" alt="7TV" title="${escapeHtml(cosmetic.badge.tooltip || '7TV')}" loading="lazy" decoding="async" width="18" height="18" style="width:18px;height:18px;">`
      }
    }
  }
  return html
}

// ═══ Followage Lookup ═══

const _followageCache = new Map() // "user:channel" → { result, ts }
const FOLLOWAGE_CACHE_TTL = 300000 // 5min

async function lookupFollowage(username, channelLogin) {
  if (!username || !channelLogin) return null
  if (username.toLowerCase() === channelLogin.toLowerCase()) return null
  const key = `${username.toLowerCase()}:${channelLogin.toLowerCase()}`
  const cached = _followageCache.get(key)
  if (cached && Date.now() - cached.ts < FOLLOWAGE_CACHE_TTL) return cached.result

  try {
    // Try server-side API first (works everywhere, including multichat on heatsync.org)
    const resp =
      typeof apiFetch === 'function'
        ? await apiFetch(
            `/api/twitch/followage?user=${encodeURIComponent(username)}&channel=${encodeURIComponent(channelLogin)}`,
          )
        : null
    if (resp?.ok && resp.data) {
      const d = resp.data
      const result = {
        followedAt: d.followedAt || null,
        followerCount: d.followerCount ?? null,
        channelFollowedAt: d.channelFollowedAt || null,
      }
      _followageCache.set(key, { result, ts: Date.now() })
      if (_followageCache.size > 500) {
        _followageCache.delete(_followageCache.keys().next().value)
      }
      return result
    }

    // Fallback: direct GQL proxy (works on Twitch tabs with MAIN world script)
    const safeUser = username.replace(/[^a-z0-9_]/gi, '')
    const safeChan = channelLogin.replace(/[^a-z0-9_]/gi, '')
    const data = await gqlProxy(null, null, {
      rawQuery: `{ user(login: "${safeUser}") { follow(targetLogin: "${safeChan}") { followedAt } followers { totalCount } } channel: user(login: "${safeChan}") { follow(targetLogin: "${safeUser}") { followedAt } } }`,
    })
    const user = data?.data?.user
    const result = {
      followedAt: user?.follow?.followedAt || null,
      followerCount: user?.followers?.totalCount ?? null,
      channelFollowedAt: data?.data?.channel?.follow?.followedAt || null,
    }
    _followageCache.set(key, { result, ts: Date.now() })
    if (_followageCache.size > 500) {
      _followageCache.delete(_followageCache.keys().next().value)
    }
    return result
  } catch {
    return null
  }
}

// ═══ Mod actions (ban/unban/timeout/delete) ═══
// Twitch deprecated /ban /unban /timeout /clear /delete and most mod chat commands
// via IRC PRIVMSG in Feb 2023; sending them as text now silently no-ops. We route
// via the existing apolloMutate → gqlMutation fallback chain (same pattern as
// predictionMutation), so the user's normal Twitch session integrity covers it.
// Mutation names (Chat_BanUserFromChatRoom etc.) are the long-standing ones used
// by Twitch's own web client and reflected in FFZ/Chatterino integrations.

const _twChannelIdCache = new Map() // login(lc) → { id, ts }

async function resolveTwitchChannelId(channelLogin) {
  const lc = (channelLogin || '')
    .toLowerCase()
    .replace(/^@/, '')
    .replace(/[^a-z0-9_]/g, '')
  if (!lc) return null
  const cached = _twChannelIdCache.get(lc)
  if (cached && Date.now() - cached.ts < 3600000) return cached.id
  // Bound the cache — every distinct channel modded in a session adds an entry;
  // without a cap it grows unbounded over a long-lived tab. Evict oldest-inserted.
  const _cacheChannelId = (id) => {
    if (_twChannelIdCache.size >= 200) {
      const oldest = _twChannelIdCache.keys().next().value
      if (oldest !== undefined) _twChannelIdCache.delete(oldest)
    }
    _twChannelIdCache.set(lc, { id, ts: Date.now() })
  }
  try {
    // 4s ceiling: decapi is a third-party in the mod-action hot path; a hang here
    // would stall every ban/timeout/unban behind the browser's default TCP
    // timeout (60s+). Time out fast and fall through to the first-party GQL path.
    const r = await fetch(`https://decapi.me/twitch/id/${encodeURIComponent(lc)}`, { credentials: 'omit', signal: AbortSignal.timeout(4000) })
    const body = (await r.text()).trim()
    if (r.ok && /^\d+$/.test(body)) {
      _cacheChannelId(body)
      return body
    }
  } catch (_) {}
  try {
    const data = await gqlProxy(null, null, { rawQuery: `{ user(login: "${lc}") { id } }` })
    const id = data?.data?.user?.id || (Array.isArray(data) ? data[0]?.data?.user?.id : null)
    if (id) {
      _cacheChannelId(id)
      return id
    }
  } catch (_) {}
  return null
}

// Server kill-switch — refuses every mod mutation when the 'mutations' feature
// is flagged. Used when a regression in our ban/timeout pipeline is shipping
// false-positive actions; flip the server flag, no extension update needed.
function _isMutationsKilled() {
  try {
    const h = (typeof window !== 'undefined' && window.__hsHealth) || null
    return !!(h && (h.kill || (Array.isArray(h.disabled) && h.disabled.includes('mutations'))))
  } catch {
    return false
  }
}

async function _modActionMutation(searchTerm, resultField, rawQuery, variables) {
  if (_isMutationsKilled()) return { error: 'mod actions disabled by server' }
  // Off-Twitch (Kick/YouTube pages): relay through a twitch.tv tab — Apollo +
  // Client-Integrity only exist in Twitch's page context. The relay runs this
  // same function inside the Twitch tab and returns the result.
  if (!_isOnTwitchPage()) {
    const resp = await safeSendMessage({
      type: 'twitch_relay',
      op: 'mod_action',
      args: { searchTerm, resultField, rawQuery, variables },
    })
    if (resp?.ok && resp.result) return resp.result
    if (resp?.error === 'no_twitch_tab') return { error: 'open a twitch.tv tab to use mod actions' }
    if (resp?.error === 'stale_twitch_tab') return { error: 'refresh your twitch.tv tab (extension was updated)' }
    return { error: resp?.error || 'relay failed' }
  }
  const apolloResult = await apolloMutate({ searchTerm, variables, resultField, rawQuery })
  if (apolloResult.ok) return { ok: true }
  try {
    const data = await gqlMutation(rawQuery, variables)
    if (data?.errors?.length) return { error: data.errors[0].message || `${resultField} failed` }
    const err = data?.data?.[resultField]?.error
    if (err) return { error: err.code || `${resultField} failed` }
    return { ok: true }
  } catch (e) {
    return { error: apolloResult.error || e.message }
  }
}

// Twitch-tab-only: respond to relay requests from off-Twitch pages.
// Runs ban/timeout/delete/follow locally (has integrity), returns the result.
if (_isOnTwitchPage() && typeof chrome !== 'undefined' && chrome.runtime?.onMessage) {
  chrome.runtime.onMessage.addListener((msg, _sender, sendResponse) => {
    if (msg?.type !== 'twitch_relay_exec') return false
    ;(async () => {
      try {
        if (msg.op === 'mod_action') {
          const { searchTerm, resultField, rawQuery, variables } = msg.args || {}
          const result = await _modActionMutation(searchTerm, resultField, rawQuery, variables)
          sendResponse({ ok: true, result })
        } else if (msg.op === 'follow_action') {
          const { targetID, follow, disableNotifications } = msg.args || {}
          const result = await _followMutation(targetID, follow, disableNotifications)
          sendResponse({ ok: true, result })
        } else {
          sendResponse({ ok: false, error: 'unknown op' })
        }
      } catch (e) {
        sendResponse({ ok: false, error: e.message })
      }
    })()
    return true
  })
}

// Twitch follow / unfollow mutation. On a twitch.tv page, fires the persisted
// query through the MAIN-world GQL proxy (handles auth + integrity + hash
// rotation). Off-twitch, relays through a twitch.tv tab — the MAIN world
// only exists on twitch.tv so a relay is mandatory. No-tab → queueable.
//
// IMPORTANT: must call gqlProxy with operationName + variables ONLY (no
// rawQuery). The MAIN-world handler explicitly rejects rawQuery messages for
// security; it serves persisted queries via gql.hashes lookup. The
// FollowButton_FollowUser / FollowButton_UnfollowUser hashes are seeded in
// early-inject-main.js and auto-updated from page traffic.
//
// Idempotency: TARGET_ALREADY_FOLLOWED / TARGET_NOT_FOLLOWED treated as
// success so heatsync→twitch state stays consistent across retries.
async function _followMutation(targetID, follow, disableNotifications) {
  if (!targetID) return { error: 'no target id' }
  const operationName = follow ? 'FollowButton_FollowUser' : 'FollowButton_UnfollowUser'
  const resultField = follow ? 'followUser' : 'unfollowUser'
  const variables = follow
    ? { input: { targetID: String(targetID), disableNotifications: !!disableNotifications } }
    : { input: { targetID: String(targetID) } }

  if (!_isOnTwitchPage()) {
    const resp = await safeSendMessage({
      type: 'twitch_relay',
      op: 'follow_action',
      args: { targetID, follow, disableNotifications },
    })
    if (resp?.ok && resp.result) return resp.result
    if (resp?.error === 'no_twitch_tab') return { error: 'no_twitch_tab', queueable: true }
    if (resp?.error === 'stale_twitch_tab')
      return { error: 'stale_twitch_tab', queueable: true, reloaded: !!resp.reloaded }
    return { error: resp?.error || 'relay failed', queueable: true }
  }

  // On Twitch: use Twitch's OWN Apollo client (MAIN-world apolloMutate path).
  // Direct gql.twitch.tv POSTs — even with freshly-minted integrity JWT —
  // get rejected as "failed integrity check" because the token only validates
  // when attached via Apollo's link chain (which handles fingerprinting,
  // session-id correlation, etc.). apolloMutate finds the GQL Document from
  // Twitch's webpack modules and calls apolloClient.mutate, identical to
  // what Twitch's own follow button does. No rawQuery — MAIN-world security
  // gate rejects rawQuery messages, and the Document is loaded from webpack
  // instead. searchTerm matches the FollowUser/UnfollowUser allowlist entry.
  const apolloResult = await apolloMutate({ searchTerm: operationName, variables, resultField })
  if (apolloResult?.ok) return { ok: true }
  if (apolloResult?.error) {
    const eMsg = String(apolloResult.error).toLowerCase()
    if (
      eMsg.includes('already') ||
      eMsg.includes('not following') ||
      eMsg.includes('not_followed') ||
      eMsg.includes('already_followed')
    ) {
      return { ok: true, idempotent: true }
    }
    if (eMsg.includes('two_factor') || eMsg === '2fa_required') return { error: '2fa_required' }
    // Fall through to gqlProxy as last-ditch on apollo failure
  }

  // Last-resort fallback: direct gqlProxy persisted query. Rarely works when
  // Apollo path didn't (integrity tokens generally don't validate raw), but
  // try before queueing in case of transient Apollo lookup issues.
  try {
    const data = await gqlProxy(operationName, variables)
    const d = Array.isArray(data) ? data[0] : data
    if (d?.errors?.length) {
      const msg = String(d.errors[0].message || '').toLowerCase()
      if (msg.includes('already') || msg.includes('not followed') || msg.includes('not following')) {
        return { ok: true, idempotent: true }
      }
      return { error: d.errors[0].message || resultField + ' failed' }
    }
    const err = d?.data?.[resultField]?.error
    if (err) {
      const code = String(err.code || '')
      if (code === 'TARGET_ALREADY_FOLLOWED' || code === 'TARGET_NOT_FOLLOWED') return { ok: true, idempotent: true }
      if (code === 'TARGET_TWO_FACTOR_REQUIRED') return { error: '2fa_required' }
      return { error: code || resultField + ' failed' }
    }
    return { ok: true }
  } catch (e) {
    const msg = String(e?.message || '').toLowerCase()
    if (msg.includes('no hash') || msg.includes('hash not available')) {
      return { error: 'twitch_hash_stale', queueable: true }
    }
    if (msg.includes('timeout')) return { error: 'twitch_gql_timeout', queueable: true }
    return { error: e?.message || 'twitch follow failed', queueable: true }
  }
}

async function followTwitchUserById(targetID, follow = true, disableNotifications = false) {
  return _followMutation(targetID, follow, disableNotifications)
}

async function banTwitchUser(channelLogin, targetLogin, reason) {
  const channelID = await resolveTwitchChannelId(channelLogin)
  if (!channelID) return { error: 'channel not found' }
  const bannedUserLogin = (targetLogin || '').toLowerCase().replace(/^@/, '')
  if (!bannedUserLogin) return { error: 'no target user' }
  return _modActionMutation(
    'Chat_BanUserFromChatRoom',
    'banUserFromChatRoom',
    'mutation($input: BanUserFromChatRoomInput!) { banUserFromChatRoom(input: $input) { error { code } } }',
    { input: { channelID, bannedUserLogin, expiresIn: null, reason: reason || '' } },
  )
}

async function timeoutTwitchUser(channelLogin, targetLogin, durationSec, reason) {
  const channelID = await resolveTwitchChannelId(channelLogin)
  if (!channelID) return { error: 'channel not found' }
  const bannedUserLogin = (targetLogin || '').toLowerCase().replace(/^@/, '')
  if (!bannedUserLogin) return { error: 'no target user' }
  return _modActionMutation(
    'Chat_BanUserFromChatRoom',
    'banUserFromChatRoom',
    'mutation($input: BanUserFromChatRoomInput!) { banUserFromChatRoom(input: $input) { error { code } } }',
    { input: { channelID, bannedUserLogin, expiresIn: Math.max(1, durationSec | 0), reason: reason || '' } },
  )
}

async function unbanTwitchUser(channelLogin, targetLogin) {
  const channelID = await resolveTwitchChannelId(channelLogin)
  if (!channelID) return { error: 'channel not found' }
  const bannedUserLogin = (targetLogin || '').toLowerCase().replace(/^@/, '')
  if (!bannedUserLogin) return { error: 'no target user' }
  return _modActionMutation(
    'Chat_UnbanUserFromChatRoom',
    'unbanUserFromChatRoom',
    'mutation($input: UnbanUserFromChatRoomInput!) { unbanUserFromChatRoom(input: $input) { error { code } } }',
    { input: { channelID, bannedUserLogin } },
  )
}

async function deleteTwitchMessage(channelLogin, messageID) {
  const channelID = await resolveTwitchChannelId(channelLogin)
  if (!channelID) return { error: 'channel not found' }
  if (!messageID) return { error: 'no message id' }
  return _modActionMutation(
    'Chat_DeleteChatMessage',
    'deleteChatMessage',
    'mutation($input: DeleteChatMessageInput!) { deleteChatMessage(input: $input) { error { code } } }',
    { input: { channelID, messageID } },
  )
}


// --- multichat/feed-embed.js ---
// Feed media + embed rendering for the extension home tab.
// Mirrors heatsync client/embed/embed-parser.js + renderers/media-renderer.js
// All embeds always-enabled (extension has no per-platform toggles yet).
// Uses plain iframes (no facade) — feed virtual-scrolls so visible iframe count stays low.

// Defence-in-depth sandbox for third-party iframes. allow-scripts/same-origin
// are required by every embed provider (player JS + auth cookies); the rest
// preserves user-clickable share/popup flows. What this BLOCKS: top-level
// nav, modals, pointer-lock, downloads — i.e. defang most providers if they
// ship malicious payload.
const EMBED_SANDBOX =
  'allow-scripts allow-same-origin allow-presentation allow-popups allow-popups-to-escape-sandbox allow-forms'

function sanitizeEmbedId(id) {
  if (!id || typeof id !== 'string') return ''
  return id.replace(/[^a-zA-Z0-9_-]/g, '')
}

function attr(s) {
  return escapeHtml(s)
}

function ytEmbed(videoId) {
  const id = sanitizeEmbedId(videoId)
  if (!id) return ''
  // YT refuses to embed when parent is youtube.com (Error 153 "Video player
  // configuration error" — self-embed guard). Fall back to a thumbnail card
  // that opens the video in a new tab.
  if (/(^|\.)youtube\.com$/i.test(location.hostname)) {
    return `<a href="https://www.youtube.com/watch?v=${id}" target="_blank" rel="noopener" class="hs-feed-embed-yt-thumb">
      <img src="https://i.ytimg.com/vi/${id}/hqdefault.jpg" alt="" loading="lazy" data-fb="hide">
      <span class="hs-feed-embed-yt-play">▶</span>
    </a>`
  }
  return `<div class="hs-feed-embed-container hs-feed-embed-youtube">
    <iframe src="https://www.youtube-nocookie.com/embed/${id}?modestbranding=1&playsinline=1&rel=0&enablejsapi=1"
      sandbox="${EMBED_SANDBOX}"
      allow="autoplay; accelerometer; clipboard-write; encrypted-media; gyroscope; picture-in-picture; fullscreen"
      loading="lazy"
      referrerpolicy="strict-origin-when-cross-origin"></iframe>
  </div>`
}

function twitchClipEmbed(clipId) {
  const id = sanitizeEmbedId(clipId)
  if (!id) return ''
  const parent = location.hostname || 'localhost'
  return `<div class="hs-feed-embed-container hs-feed-embed-twitch">
    <iframe src="https://clips.twitch.tv/embed?clip=${id}&parent=${encodeURIComponent(parent)}"
      sandbox="${EMBED_SANDBOX}"
      allow="fullscreen" loading="lazy"></iframe>
  </div>`
}

function kickClipEmbed(clipId, fullUrl) {
  const id = sanitizeEmbedId(clipId)
  if (!id) return ''
  // player.kick.com sends X-Frame-Options: SAMEORIGIN — iframe always blank.
  // Route through server-resolve to get thumbnail+title from kick.com/api/v2.
  const safe = safeUrl(fullUrl) || `https://kick.com/clips/${id}`
  return `<div class="hs-feed-embed-pending hs-feed-embed-kick"
    data-resolve-url="${attr(safe)}" data-resolve-platform="kick">
    <span class="hs-feed-embed-pending-label">loading kick clip…</span>
  </div>`
}

function streamableEmbed(videoId) {
  const id = sanitizeEmbedId(videoId)
  if (!id) return ''
  return `<div class="hs-feed-embed-container hs-feed-embed-streamable">
    <iframe src="https://streamable.com/e/${id}" sandbox="${EMBED_SANDBOX}" allow="fullscreen" loading="lazy"></iframe>
  </div>`
}

function vimeoEmbed(videoId) {
  const id = sanitizeEmbedId(videoId)
  if (!id) return ''
  return `<div class="hs-feed-embed-container hs-feed-embed-vimeo">
    <iframe src="https://player.vimeo.com/video/${id}"
      sandbox="${EMBED_SANDBOX}"
      allow="autoplay; fullscreen; picture-in-picture" loading="lazy"></iframe>
  </div>`
}

function spotifyEmbed(kind, id) {
  const safeKind = (kind || '').replace(/[^a-z]/g, '')
  const safeId = sanitizeEmbedId(id)
  if (!safeKind || !safeId) return ''
  return `<div class="hs-feed-embed-container hs-feed-embed-spotify">
    <iframe src="https://open.spotify.com/embed/${safeKind}/${safeId}"
      sandbox="${EMBED_SANDBOX}"
      width="100%" height="152" allow="encrypted-media" loading="lazy"></iframe>
  </div>`
}

function soundcloudEmbed(url) {
  const safe = safeUrl(url)
  if (!safe || !/^https?:\/\/(www\.|m\.)?soundcloud\.com\//i.test(safe)) return ''
  return `<div class="hs-feed-embed-container hs-feed-embed-soundcloud">
    <iframe scrolling="no"
      sandbox="${EMBED_SANDBOX}"
      src="https://w.soundcloud.com/player/?url=${encodeURIComponent(safe)}&color=%23ff5500&auto_play=false&hide_related=true&show_comments=false&show_user=true&show_reposts=false&show_teaser=false&visual=true"
      loading="lazy"></iframe>
  </div>`
}

function giphyEmbed(gifId) {
  const id = sanitizeEmbedId(gifId)
  if (!id) return ''
  return `<div class="hs-feed-embed-container hs-feed-embed-giphy">
    <iframe src="https://giphy.com/embed/${id}" sandbox="${EMBED_SANDBOX}" allow="fullscreen" loading="lazy"></iframe>
  </div>`
}

function tenorEmbed(gifId) {
  const id = sanitizeEmbedId(gifId)
  if (!id) return ''
  return `<div class="hs-feed-embed-container hs-feed-embed-tenor">
    <iframe src="https://tenor.com/embed/${id}" sandbox="${EMBED_SANDBOX}" allow="fullscreen" loading="lazy"></iframe>
  </div>`
}

function twitterEmbed(tweetId, url) {
  const id = sanitizeEmbedId(tweetId)
  if (!id) return ''
  // platform.twitter.com/embed/Tweet.html renders the tweet in an iframe with no
  // widgets.js needed (script tags injected via innerHTML never execute, so the
  // blockquote+script approach the website uses is broken in extension context).
  return `<div class="hs-feed-embed-container hs-feed-embed-twitter">
    <iframe src="https://platform.twitter.com/embed/Tweet.html?id=${id}&theme=dark&dnt=true"
      sandbox="${EMBED_SANDBOX}"
      allow="autoplay; clipboard-write; fullscreen" loading="lazy"></iframe>
  </div>`
}

function imgurEmbed(imgurId) {
  const id = sanitizeEmbedId(imgurId)
  if (!id) return ''
  // Imgur embed needs script — fall back to direct image link approach.
  // data-fb="hide" is the host-CSP-safe replacement for inline onerror;
  // attachFeedFallbacks() wires the listener post-render.
  return `<div class="hs-feed-embed-container hs-feed-embed-imgur" style="aspect-ratio:auto;max-width:480px">
    <a href="https://imgur.com/${id}" target="_blank" rel="noopener">
      <img src="https://i.imgur.com/${id}.jpg" alt="imgur"
        style="max-width:100%;height:auto;display:block"
        data-fb="hide">
    </a>
  </div>`
}

function tiktokEmbed(videoId, url) {
  const id = sanitizeEmbedId(videoId)
  if (!id) return ''
  return `<div class="hs-feed-embed-container hs-feed-embed-tiktok">
    <iframe src="https://www.tiktok.com/embed/v2/${id}"
      sandbox="${EMBED_SANDBOX}"
      allow="fullscreen" scrolling="no" loading="lazy"></iframe>
  </div>`
}

function redditEmbed(url) {
  const safe = safeUrl(url)
  if (!safe) return ''
  // Permalink → server-resolved rich card with image/icon when reachable.
  // Reddit blocks the VPS IP ~half the time so we also bake in slug-derived
  // fallback metadata; the resolver uses it when the server returns nothing.
  const m = safe.match(/reddit\.com\/r\/([\w-]+)\/comments\/[a-z0-9]+(?:\/([\w-]+))?/i)
  if (m) {
    const sub = m[1]
    const slug = m[2] || ''
    const title = slug ? slug.replace(/[_-]+/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase()) : `r/${sub}`
    return `<div class="hs-feed-embed-pending hs-feed-embed-reddit"
      data-resolve-url="${attr(safe)}" data-resolve-platform="reddit"
      data-fb-title="${attr(title)}" data-fb-author="r/${attr(sub)}">
      <span class="hs-feed-embed-pending-label">loading reddit…</span>
    </div>`
  }
  // Non-permalink (subreddit, user) → link card.
  return `<div class="hs-feed-link-card">
    <a href="${attr(safe)}" target="_blank" rel="noopener" class="hs-feed-link-card-link">
      <span class="hs-feed-link-card-icon">[reddit]</span>
      <span class="hs-feed-link-card-url">${attr(safe.length > 60 ? safe.slice(0, 60) + '...' : safe)}</span>
    </a>
  </div>`
}

function instagramEmbed(url) {
  const safe = safeUrl(url)
  if (!safe) return ''
  return `<div class="hs-feed-link-card">
    <a href="${attr(safe)}" target="_blank" rel="noopener" class="hs-feed-link-card-link">
      <span class="hs-feed-link-card-icon">[ig]</span>
      <span class="hs-feed-link-card-url">${attr(safe.length > 60 ? safe.slice(0, 60) + '...' : safe)}</span>
    </a>
  </div>`
}

// Convert a single URL → embed HTML, or '' if not embeddable
function parseFeedEmbed(url) {
  if (!url || typeof url !== 'string') return ''
  const cleanUrl = url.replace(/[.,;!?]+$/, '')

  // YouTube
  if (cleanUrl.includes('youtube.com/watch?v=') || cleanUrl.includes('youtu.be/')) {
    let videoId
    if (cleanUrl.includes('youtube.com/watch?v=')) {
      videoId = cleanUrl.split('v=')[1].split('&')[0]
    } else {
      videoId = cleanUrl.split('youtu.be/')[1].split('?')[0]
    }
    return ytEmbed(videoId)
  }

  // Twitch clips (clips.twitch.tv/...)
  if (cleanUrl.includes('clips.twitch.tv/')) {
    const clipId = cleanUrl.split('clips.twitch.tv/')[1].split(/[?#]/)[0]
    return twitchClipEmbed(clipId)
  }

  // Twitch clips alt format (twitch.tv/user/clip/id)
  if (cleanUrl.includes('twitch.tv/') && cleanUrl.includes('/clip/')) {
    const clipId = cleanUrl.split('/clip/')[1].split(/[?#]/)[0]
    return twitchClipEmbed(clipId)
  }

  // Kick clips
  if (cleanUrl.includes('kick.com/') && cleanUrl.includes('/clips/')) {
    const m = cleanUrl.match(/clips\/([a-zA-Z0-9_-]+)/)
    if (m) return kickClipEmbed(m[1], cleanUrl)
  }

  // Streamable
  if (cleanUrl.includes('streamable.com/')) {
    const videoId = cleanUrl.split('streamable.com/')[1].split(/[?#]/)[0]
    if (videoId && !videoId.startsWith('test')) return streamableEmbed(videoId)
  }

  // Vimeo
  if (cleanUrl.includes('vimeo.com/')) {
    const m = cleanUrl.match(/vimeo\.com\/(\d+)/)
    if (m) return vimeoEmbed(m[1])
  }

  // Spotify
  if (cleanUrl.includes('open.spotify.com/')) {
    const parts = cleanUrl.split('spotify.com/')[1].split('/')
    const kind = parts[0]
    const id = parts[1]?.split('?')[0]
    if (kind && id) return spotifyEmbed(kind, id)
  }

  // SoundCloud
  if (cleanUrl.includes('soundcloud.com/')) {
    return soundcloudEmbed(cleanUrl)
  }

  // Twitter/X
  if (cleanUrl.includes('twitter.com/') || cleanUrl.includes('x.com/')) {
    const m = cleanUrl.match(/status\/(\d+)/)
    if (m) return twitterEmbed(m[1], cleanUrl)
  }

  // Giphy (gif page)
  if (cleanUrl.includes('giphy.com/gifs/')) {
    const m = cleanUrl.match(/gifs\/(?:.*-)?([a-zA-Z0-9]+)$/)
    if (m) return giphyEmbed(m[1])
  }

  // Tenor
  if (cleanUrl.includes('tenor.com/view/')) {
    const m = cleanUrl.match(/view\/.*-(\d+)$/)
    if (m) return tenorEmbed(m[1])
  }

  // TikTok
  if (cleanUrl.includes('tiktok.com/') && cleanUrl.includes('/video/')) {
    const m = cleanUrl.match(/video\/(\d+)/)
    if (m) return tiktokEmbed(m[1], cleanUrl)
  }

  // Imgur
  if (cleanUrl.includes('imgur.com/')) {
    const m = cleanUrl.match(/imgur\.com\/(?:a\/|gallery\/)?([a-zA-Z0-9]+)/)
    if (m) return imgurEmbed(m[1])
  }

  // Reddit
  if (cleanUrl.includes('reddit.com/r/')) {
    return redditEmbed(cleanUrl)
  }

  // Instagram
  if (cleanUrl.includes('instagram.com/p/') || cleanUrl.includes('instagram.com/reel/')) {
    return instagramEmbed(cleanUrl)
  }

  // Direct media files
  if (/\.(jpg|jpeg|png|gif|webp)(\?.*)?$/i.test(cleanUrl)) {
    const safe = safeUrl(cleanUrl)
    if (!safe) return ''
    return `<div class="hs-feed-media-direct">
      <img src="${attr(safe)}" alt="" data-fb="deleted">
    </div>`
  }
  if (/\.(mp4|webm|mov)(\?.*)?$/i.test(cleanUrl)) {
    const safe = safeUrl(cleanUrl)
    if (!safe) return ''
    return `<div class="hs-feed-media-direct">
      <video controls muted preload="metadata" src="${attr(safe)}"></video>
    </div>`
  }

  return ''
}

// Extract first embeddable URL from message content (OP only, mirrors website)
function extractFeedEmbed(content) {
  if (!content || typeof content !== 'string') return ''
  // Same priority order as website _extractEmbed
  const priorityPatterns = [
    /https?:\/\/(?:www\.)?streamable\.com\/\w+/,
    /https?:\/\/(?:www\.)?youtu(?:\.be\/|be\.com\/watch\?v=)[\w-]+/,
    /https?:\/\/clips\.twitch\.tv\/[\w-]+/,
    /https?:\/\/(?:www\.)?twitch\.tv\/[\w_]+\/clip\/[\w-]+/,
    /https?:\/\/kick\.com\/[\w_-]+\/clips\/[\w-]+/,
    /https?:\/\/open\.spotify\.com\/(?:track|album|playlist)\/\w+/,
    /https?:\/\/(?:www\.)?vimeo\.com\/\d+/,
    /https?:\/\/(?:www\.)?giphy\.com\/gifs\/[\w-]+/,
    /https?:\/\/(?:www\.)?tenor\.com\/view\/[\w-]+-\d+/,
    /https?:\/\/(?:www\.)?tiktok\.com\/[@\w.]+\/video\/\d+/,
    /https?:\/\/(?:www\.)?imgur\.com\/(?:a\/|gallery\/)?[a-zA-Z0-9]+/,
    /https?:\/\/(?:twitter|x)\.com\/[\w_]+\/status\/\d+/,
    /https?:\/\/(?:[\w-]+\.)?reddit\.com\/r\/\w+\/[\w/]+/,
    /https?:\/\/(?:www\.|m\.)?soundcloud\.com\/[\w-]+\/[\w-]+/,
    /https?:\/\/(?:www\.)?instagram\.com\/(?:p|reel)\/[\w-]+/,
    /https?:\/\/[^\s]+\.(?:jpg|jpeg|png|gif|webp|mp4|webm|mov)(?:\?[^\s]*)?/i,
  ]

  for (const p of priorityPatterns) {
    const m = content.match(p)
    if (m) {
      const html = parseFeedEmbed(m[0])
      if (html) return html
    }
  }
  return ''
}

// ── CHAT INLINE EMBEDS ──────────────────────────────────────────────────────
// Chat is high-volume and lives on low-RAM / passive-cooled hardware, so chat
// NEVER renders live iframes the way the feed does (the feed virtual-scrolls, so
// its visible iframe count stays tiny — chat has no such bound). Chat media is
// therefore always lightweight: an inline direct image/video, a YouTube
// thumbnail card, or a server-resolved rich card. One embed per message. Every
// branch emits ONLY safeUrl()-validated + attr()-escaped strings — never raw
// message text — so the holder's insertAdjacentHTML in main.js stays XSS-safe.
const _CHAT_URL_RE = /https?:\/\/[^\s<>"']+/i

function extractChatEmbed(text) {
  if (!text || typeof text !== 'string') return ''
  const m = text.match(_CHAT_URL_RE)
  if (!m) return ''
  return chatEmbedForUrl(m[0])
}

function chatEmbedForUrl(rawUrl) {
  // Strip trailing sentence punctuation, but only strip a trailing ) or ] when
  // it's UNBALANCED — otherwise wikipedia/github URLs like .../Foo_(bar) lose
  // their closing paren and the embed/link breaks.
  let cleanUrl = rawUrl.replace(/[.,;!?]+$/, '')
  while (/[)\]]$/.test(cleanUrl)) {
    const opens = (cleanUrl.match(/[([]/g) || []).length
    const closes = (cleanUrl.match(/[)\]]/g) || []).length
    if (closes <= opens) break
    cleanUrl = cleanUrl.slice(0, -1).replace(/[.,;!?]+$/, '')
  }
  const safe = safeUrl(cleanUrl)
  if (!safe) return ''
  // Direct image / gif → inline, lazy, error-guarded (data-fb hides on 404/blocked).
  if (/\.(jpg|jpeg|png|gif|webp|avif)(\?.*)?$/i.test(cleanUrl)) {
    return `<div class="hs-mc-media"><img src="${attr(safe)}" alt="" loading="lazy" decoding="async" data-fb="hide"></div>`
  }
  // Direct video → inline, preload=none (no bytes until play — critical at chat volume).
  if (/\.(mp4|webm|mov)(\?.*)?$/i.test(cleanUrl)) {
    return `<div class="hs-mc-media"><video controls muted preload="none" playsinline src="${attr(safe)}" data-fb="hide"></video></div>`
  }
  // YouTube → thumbnail card that opens the video. Never an iframe in chat.
  let ytId = ''
  let ym
  if ((ym = cleanUrl.match(/youtu\.be\/([\w-]{11})/))) ytId = ym[1]
  else if ((ym = cleanUrl.match(/youtube\.com\/watch\?v=([\w-]{11})/))) ytId = ym[1]
  else if ((ym = cleanUrl.match(/youtube\.com\/shorts\/([\w-]{11})/))) ytId = ym[1]
  if (ytId) {
    const id = sanitizeEmbedId(ytId)
    if (id) return `<a href="https://www.youtube.com/watch?v=${id}" target="_blank" rel="noopener" class="hs-mc-media hs-feed-embed-yt-thumb">
      <img src="https://i.ytimg.com/vi/${id}/mqdefault.jpg" alt="" loading="lazy" decoding="async" data-fb="hide">
      <span class="hs-feed-embed-yt-play">▶</span>
    </a>`
  }
  // Providers the server resolver handles (oEmbed) → lightweight pending card.
  // Server returns image/video/audio/rich; unsupported → graceful link card.
  // No iframes. data-resolve-url drives resolvePendingFeedEmbeds().
  if (/(?:reddit\.com\/r\/|(?:twitter|x)\.com\/[\w_]+\/status\/|open\.spotify\.com\/(?:track|album|playlist|episode|show)\/|(?:www\.)?vimeo\.com\/\d|tiktok\.com\/@[\w.]+\/video\/|instagram\.com\/(?:p|reel)\/|soundcloud\.com\/[\w-]+\/[\w-]+|kick\.com\/[\w_-]+\/clips\/|clips\.twitch\.tv\/|streamable\.com\/\w)/i.test(cleanUrl)) {
    return `<div class="hs-mc-media hs-feed-embed-pending" data-resolve-url="${attr(safe)}" data-resolve-platform="link"><span class="hs-feed-embed-pending-label">loading preview…</span></div>`
  }
  return ''
}

// Main entry: build full media HTML for a feed message.
// Handles direct uploads (image/video), multi-image (media[]), and content-extracted embeds.
function buildFeedMediaHtml(m) {
  if (!m) return ''
  const isReply = !!m.reply_to
  const mediaUrl = m.media_url
  const mediaType = m.media_type
  const mediaArr = Array.isArray(m.media) ? m.media : []

  // Multi-item media (uploads)
  if (mediaArr.length > 1) {
    const items = mediaArr
      .map((med) => {
        const url = safeUrl(med.url)
        if (!url) return ''
        if (med.type === 'video') {
          return `<video controls muted preload="metadata" src="${attr(url)}" class="hs-feed-media-item"></video>`
        }
        return `<img src="${attr(url)}" alt="" class="hs-feed-media-item">`
      })
      .filter(Boolean)
      .join('')
    if (items) return `<div class="hs-feed-media hs-feed-media-multi">${items}</div>`
  }

  // Single direct upload
  if (mediaUrl) {
    const safe = safeUrl(mediaUrl)
    if (!safe) return ''

    const isVideo = mediaType === 'video' || (mediaType || '').startsWith('video/')
    const isEmbedType =
      mediaType === 'embed' ||
      /^https?:\/\/(?:(?:www\.)?(?:youtube\.com|youtu\.be|twitch\.tv|clips\.twitch\.tv|streamable\.com|vimeo\.com|twitter\.com|x\.com|kick\.com|tiktok\.com|open\.spotify\.com|soundcloud\.com|giphy\.com|tenor\.com|imgur\.com|instagram\.com)|(?:[\w-]+\.)?reddit\.com)/i.test(
        safe,
      )
    const isImage = mediaType === 'image' || /\.(jpg|jpeg|png|gif|webp)(\?.*)?$/i.test(safe)

    if (isEmbedType) {
      const embedHtml = parseFeedEmbed(safe)
      if (embedHtml) return `<div class="hs-feed-media">${embedHtml}</div>`
    }

    if (isVideo) {
      return `<div class="hs-feed-media"><video controls muted preload="metadata" src="${attr(safe)}"></video></div>`
    }

    if (isImage) {
      return `<div class="hs-feed-media"><img src="${attr(safe)}" alt="" class="hs-feed-media-img"></div>`
    }

    return ''
  }

  // No direct media — for OPs, scan content for embeddable URL
  if (!isReply && m.content) {
    const embedHtml = extractFeedEmbed(m.content)
    if (embedHtml) return `<div class="hs-feed-media">${embedHtml}</div>`
  }

  return ''
}

// Resolve `.hs-feed-embed-pending[data-resolve-url]` placeholders via
// heatsync.org/api/embed/resolve. All HTML built from server fields is escaped
// via attr() (escapeHtml). Idempotent — safe to call repeatedly.
const _feedResolveInflight = new Map()
const FEED_RESOLVE_INFLIGHT_MAX = 200

function _fetchFeedResolve(url) {
  if (_feedResolveInflight.has(url)) return _feedResolveInflight.get(url)
  // Route via background SW — content script fetches in MV3 still go through
  // page-origin CORS, but the SW has full host_permissions and bypasses it.
  const promise = (async () => {
    try {
      const data = await safeSendMessage({ type: 'fetch_embed_resolve', url })
      if (!data || data.error || data.ok === false) return null
      return data
    } catch (_) {
      return null
    }
  })()
  if (_feedResolveInflight.size >= FEED_RESOLVE_INFLIGHT_MAX) {
    _feedResolveInflight.delete(_feedResolveInflight.keys().next().value)
  }
  _feedResolveInflight.set(url, promise)
  promise.finally(() => cleanup.setTimeout(() => _feedResolveInflight.delete(url), 30000))
  return promise
}

function _buildFeedResolvedHtml(ph, data) {
  const url = ph.dataset.resolveUrl || ''
  const platform = ph.dataset.resolvePlatform || ''
  const safeUrlStr = attr(url)
  const safeTitle = attr(data.title || '')
  const safeAuthor = attr(data.author || '')
  const safeThumb = attr(data.thumbnail || '')
  const safeMedia = attr(data.mediaUrl || '')
  const safePlat = attr(platform)

  if (data.type === 'image' && data.mediaUrl) {
    return `<a href="${safeUrlStr}" target="_blank" rel="noopener" class="hs-feed-embed-rich-imglink">
      <img src="${safeMedia}" alt="${safeTitle}" class="hs-feed-embed-rich-image" data-fb="deleted-span">
    </a>`
  }
  if (data.type === 'video' && data.mediaUrl) {
    // m3u8 (kick clip) needs hls.js which we don't bundle — render as a
    // thumbnail card that opens the clip page on click. mp4 plays natively.
    if (data.mediaUrl.includes('.m3u8')) {
      const thumbHtml = safeThumb
        ? `<img src="${safeThumb}" alt="${safeTitle || safePlat}" class="hs-feed-embed-rich-thumb">`
        : `<div class="hs-feed-embed-rich-thumb-placeholder">[${safePlat}]</div>`
      return `<a href="${safeUrlStr}" target="_blank" rel="noopener" class="hs-feed-embed-rich-card">
        ${thumbHtml}
        <div class="hs-feed-embed-rich-meta">
          <div class="hs-feed-embed-rich-platform">${safePlat}</div>
          <div class="hs-feed-embed-rich-title">${safeTitle}</div>
          ${safeAuthor ? `<div class="hs-feed-embed-rich-author">${safeAuthor}</div>` : ''}
        </div>
      </a>`
    }
    const poster = safeThumb ? `poster="${safeThumb}"` : ''
    return `<video controls preload="metadata" ${poster} src="${safeMedia}" class="hs-feed-embed-rich-video"></video>`
  }
  if (data.type === 'rich') {
    const thumbHtml = safeThumb
      ? `<img src="${safeThumb}" alt="${safeTitle || safePlat}" class="hs-feed-embed-rich-thumb">`
      : `<div class="hs-feed-embed-rich-thumb-placeholder">[${safePlat}]</div>`
    return `<a href="${safeUrlStr}" target="_blank" rel="noopener" class="hs-feed-embed-rich-card">
      ${thumbHtml}
      <div class="hs-feed-embed-rich-meta">
        <div class="hs-feed-embed-rich-platform">${safePlat}</div>
        <div class="hs-feed-embed-rich-title">${safeTitle}</div>
        ${safeAuthor ? `<div class="hs-feed-embed-rich-author">${safeAuthor}</div>` : ''}
      </div>
    </a>`
  }
  return ''
}

function _buildFeedResolveFailedHtml(ph) {
  const url = ph.dataset.resolveUrl || ''
  const platform = ph.dataset.resolvePlatform || ''
  // Placeholder may carry baked-in fallback metadata (data-fb-title/-author)
  // so we can still render a rich card when the server can't reach the source.
  const fbTitle = ph.dataset.fbTitle || ''
  const fbAuthor = ph.dataset.fbAuthor || ''
  if (fbTitle || fbAuthor) {
    return `<a href="${attr(url)}" target="_blank" rel="noopener" class="hs-feed-embed-rich-card">
      <div class="hs-feed-embed-rich-thumb-placeholder">[${attr(platform)}]</div>
      <div class="hs-feed-embed-rich-meta">
        <div class="hs-feed-embed-rich-platform">${attr(platform)}</div>
        <div class="hs-feed-embed-rich-title">${attr(fbTitle)}</div>
        ${fbAuthor ? `<div class="hs-feed-embed-rich-author">${attr(fbAuthor)}</div>` : ''}
      </div>
    </a>`
  }
  const truncated = url.length > 60 ? url.slice(0, 60) + '…' : url
  return `<div class="hs-feed-link-card">
    <a href="${attr(url)}" target="_blank" rel="noopener" class="hs-feed-link-card-link">
      <span class="hs-feed-link-card-icon">[${attr(platform)}]</span>
      <span class="hs-feed-link-card-url">${attr(truncated)}</span>
    </a>
  </div>`
}

function _swapPlaceholder(ph, html, resolvedClass) {
  // Replace placeholder children via fragment to satisfy the security hook
  // (avoids ph.innerHTML = …); html is built from escaped server fields only.
  const tmp = document.createElement('div')
  tmp.insertAdjacentHTML('afterbegin', html)
  while (ph.firstChild) ph.removeChild(ph.firstChild)
  while (tmp.firstChild) ph.appendChild(tmp.firstChild)
  ph.classList.remove('hs-feed-embed-pending')
  ph.classList.add(resolvedClass)
}

function resolvePendingFeedEmbeds(root) {
  if (!root || !root.querySelectorAll) return
  const placeholders = root.querySelectorAll('.hs-feed-embed-pending[data-resolve-url]')
  if (!placeholders.length) return
  for (const ph of placeholders) {
    if (ph.dataset.resolving === '1') continue
    ph.dataset.resolving = '1'
    const url = ph.dataset.resolveUrl
    if (!url) continue
    _fetchFeedResolve(url).then((data) => {
      // The row may have been culled (chat trimMessagesEl, or a feed re-render)
      // during the async resolve — don't mutate a detached node or wire dead
      // listeners. Matches the isConnected guard pattern used elsewhere.
      if (!ph.isConnected) return
      if (data && !data.error) {
        const html = _buildFeedResolvedHtml(ph, data)
        if (html) _swapPlaceholder(ph, html, 'hs-feed-embed-resolved')
        else _swapPlaceholder(ph, _buildFeedResolveFailedHtml(ph), 'hs-feed-embed-resolve-failed')
      } else {
        _swapPlaceholder(ph, _buildFeedResolveFailedHtml(ph), 'hs-feed-embed-resolve-failed')
      }
      attachFeedFallbacks(ph)
    })
  }
}

// Wire load-fail fallbacks for images/avatars in the feed. Replaces the inline
// onerror= patterns that host-page CSP (twitch) silently strips. Idempotent.
//   data-fb="hide"          → display:none
//   data-fb="deleted"       → swap node for <div class="hs-feed-media-deleted">image unavailable</div>
//   data-fb="deleted-span"  → swap node for <span class="hs-feed-media-deleted">image unavailable</span>
//   data-fallback-anon      → swap src to /anon.webp (avatars)
function attachFeedFallbacks(root) {
  if (!root || !root.querySelectorAll) return
  root.querySelectorAll('img[data-fallback-anon]').forEach((img) => {
    img.addEventListener(
      'error',
      () => {
        img.removeAttribute('data-fallback-anon')
        img.src = 'https://heatsync.org/anon.webp'
      },
      { once: true },
    )
  })
  root.querySelectorAll('img[data-fb]').forEach((img) => {
    const mode = img.dataset.fb
    img.removeAttribute('data-fb')
    img.addEventListener(
      'error',
      () => {
        if (mode === 'hide') {
          img.style.display = 'none'
        } else if (mode === 'deleted' || mode === 'deleted-span') {
          const tag = mode === 'deleted-span' ? 'span' : 'div'
          const replacement = document.createElement(tag)
          replacement.className = 'hs-feed-media-deleted'
          replacement.textContent = 'image unavailable'
          img.replaceWith(replacement)
        }
      },
      { once: true },
    )
  })
  // Inline <video> (direct chat media) — a dead source must hide, not leave a
  // broken player. <video> 'error' doesn't bubble, so wire it directly here.
  root.querySelectorAll('video[data-fb="hide"]').forEach((video) => {
    video.removeAttribute('data-fb')
    video.addEventListener('error', () => { video.style.display = 'none' }, { once: true })
  })
}


// --- multichat/social.js ---
// Social - feed, notifications, activity, heatsync API
let _autoYtVideoId = null // videoId for this tab's __live_yt_auto__ subscription (cross-tab filter)

// YT POLL SMOOTHING: server polls YouTube every ~5s and dispatches the whole
// batch back-to-back over WS. Without smoothing, 10 msgs land in one rAF
// frame and the chat flashes them all at once. We drip them per-channel using
// the REAL inter-message timestamp deltas (msg.time from YouTube), so two
// msgs posted 1.8s apart show up 1.8s apart visually — natural human pacing.
// Floor and cap keep things perceptible without dragging.
const YT_PACE_MIN_MS = 60 // floor — never emit faster than this
const YT_PACE_MAX_MS = 400 // cap — never delay a single msg longer than this
const YT_PACE_BURST_MAX = 1500 // total projected backlog cap; overflow flushes synchronously
const _ytPaceQueue = new Map() // channelId → ytMsg[] (in real-time order)
const _ytPaceTimer = new Map() // channelId → timer handle
const _ytPaceLastEmit = new Map() // channelId → { time: ms, msgTime: real msg.time }

// Heat tier display — big scaling numbers + color glow + row effects, no emoji
// Matches website colors.js: #444 → #888 → #cc6600 → #ff8700 → #ffaa33 → #fff
function formatHeat(heat) {
  if (heat >= 1000) {
    const k = heat / 1000
    const f = k.toFixed(1)
    return f.endsWith('.0') ? f.slice(0, -2) + 'k' : f + 'k'
  }
  return String(heat)
}

function getHeatNumberStyle(heat, isReply) {
  let fontSize, color, textShadow, animation
  if (isReply) {
    if (heat > 500) fontSize = 20
    else if (heat > 100) fontSize = 18
    else if (heat > 50) fontSize = 16
    else if (heat > 10) fontSize = 14
    else fontSize = 12
  } else {
    if (heat > 500) fontSize = 32
    else if (heat > 100) fontSize = 26
    else if (heat > 50) fontSize = 22
    else if (heat > 10) fontSize = 18
    else fontSize = 14
  }
  if (heat > 500) {
    color = '#fff'
    textShadow =
      '0 0 6px rgba(255,255,255,1),0 0 15px rgba(255,200,100,1),0 0 30px rgba(255,135,0,0.9),0 0 50px rgba(255,80,0,0.6)'
    animation = 'hs-heat-breathe 2s ease-in-out infinite'
  } else if (heat > 100) {
    color = '#ffaa33'
    textShadow = '0 0 6px rgba(255,170,50,0.9),0 0 16px rgba(255,135,0,0.6),0 0 30px rgba(255,80,0,0.3)'
  } else if (heat > 50) {
    color = '#ff8700'
    textShadow = '0 0 6px rgba(255,135,0,0.7),0 0 14px rgba(255,135,0,0.3)'
  } else if (heat > 10) {
    color = heat > 30 ? '#cc6600' : '#888'
    textShadow = heat > 30 ? '0 0 4px rgba(204,102,0,0.3)' : undefined
  } else {
    color = '#444'
    textShadow = undefined
  }
  let style = `font-size:${fontSize}px;color:${color};font-weight:900;line-height:1;`
  if (textShadow) style += `text-shadow:${textShadow};`
  if (animation) style += `animation:${animation};`
  return style
}

function getHeatDisplay(heat) {
  if (!heat || heat <= 0) return null
  let border = '#444',
    borderWidth = 2,
    bg = ''
  if (heat >= 500) {
    border = '#fff'
    borderWidth = 4
    bg = 'rgba(60,20,0,0.15)'
  } else if (heat >= 100) {
    border = '#ffaa33'
    borderWidth = 3
    bg = 'rgba(50,15,0,0.10)'
  } else if (heat >= 25) {
    border = '#ff8700'
    borderWidth = 3
    bg = 'rgba(40,12,0,0.07)'
  } else if (heat >= 10) {
    border = '#ff8700'
    borderWidth = 2
  } else {
    border = '#444'
    borderWidth = 2
  }
  const suffix = heat >= 10 ? '°' : ''
  const breathe = heat >= 500
  return { suffix, border, borderWidth, bg, breathe }
}

// Feed & notifications state
let feedMessages = []
let feedLoaded = false
let feedLoading = false
let feedPage = 1
let feedHasMore = true
let feedLastFetch = 0 // Timestamp of last feed fetch
let feedFromHotFallback = false // true when /following was empty + we showed /hot instead
const FEED_STALE_MS = 120000 // 2 minutes


// Feed scroll state — handler ref for teardown only, infinite-scroll trigger
let _feedVirtualScrollHandler = null

// Stream events injected inline into per-channel buffers (no dedicated tab)
const activityEvents = []
const ACTIVITY_EVENTS_MAX = 500
function pushActivityEvent(evt) {
  if (activityEvents.some((m) => m.text === evt.text)) return
  activityEvents.push(evt)
  if (activityEvents.length > ACTIVITY_EVENTS_MAX) activityEvents.splice(0, activityEvents.length - ACTIVITY_EVENTS_MAX)
}
let activeThread = null // { id, op, replies[] } — when set, feed shows thread view
let replyState = null // { msgId, user, channel } when replying to a message
let hsAuthToken = null // Heatsync auth state (loaded from storage)
let hsCurrentUsername = null // Heatsync username (loaded from storage user_info)
let hsCurrentUserId = null // Heatsync numeric user id (for reaction matching)

// Load + watch heatsync username for own-post detection (edit/delete UI)
async function loadHsUsername() {
  try {
    const data = await api.storage.local.get('user_info')
    const ui = data?.user_info
    hsCurrentUsername = ui?.username?.toLowerCase() || null
    hsCurrentUserId = ui?.id ? String(ui.id) : null
    // Cross-platform mention aliases: any name across Twitch/Kick/YT counts as
    // a mention of the user, even if the chat is on a different platform.
    // ui.username (heatsync core name) is always included so bare-name mentions
    // resolve even when getCurrentUsername() returns null (e.g. logged-out Kick
    // tab) and no platform aliases are configured.
    mentionAliases = new Set()
    if (ui?.username) mentionAliases.add(ui.username.toLowerCase())
    if (ui?.kick_username) mentionAliases.add(ui.kick_username.toLowerCase())
    if (ui?.youtube_username) mentionAliases.add(ui.youtube_username.toLowerCase())
    if (ui?.twitch_username) mentionAliases.add(ui.twitch_username.toLowerCase())
  } catch (e) {
    hsCurrentUsername = null
    hsCurrentUserId = null
  }
}
function isOwnFeedPost(m) {
  return !!(hsCurrentUsername && m?.username && m.username.toLowerCase() === hsCurrentUsername)
}

const EDIT_WINDOW_MS = 10 * 60 * 1000 // 10 min — server enforces

// Inline edit UI for own feed posts
function showFeedEditUI(div, msg) {
  if (div.querySelector('.hs-feed-edit-form')) return
  const body = div.querySelector('.hs-feed-body')
  if (!body) return
  const original = msg.content || ''
  const form = document.createElement('div')
  form.className = 'hs-feed-edit-form'
  form.style.cssText = 'display:flex;gap:4px;align-items:flex-start;margin-top:4px;'
  const ta = document.createElement('textarea')
  ta.value = original
  ta.maxLength = 500
  ta.rows = 2
  ta.style.cssText =
    'flex:1;background:#000;color:#fff;border:1px solid #808080;padding:4px;font-family:inherit;font-size:13px;resize:vertical;'
  const saveBtn = document.createElement('button')
  saveBtn.textContent = 'save'
  saveBtn.style.cssText =
    'background:#ff8700;color:#000;border:none;padding:4px 8px;font-family:inherit;font-size:13px;cursor:pointer;'
  const cancelBtn = document.createElement('button')
  cancelBtn.textContent = 'cancel'
  cancelBtn.style.cssText =
    'background:#000;color:#fff;border:1px solid #808080;padding:4px 8px;font-family:inherit;font-size:13px;cursor:pointer;'
  const errEl = document.createElement('div')
  errEl.style.cssText = 'font-size:13px;color:#ff4444;margin-top:2px;'
  form.append(ta, saveBtn, cancelBtn)
  body.style.display = 'none'
  body.parentNode.insertBefore(form, body.nextSibling)
  body.parentNode.insertBefore(errEl, form.nextSibling)
  ta.focus()
  ta.select()

  const close = () => {
    body.style.display = ''
    form.remove()
    errEl.remove()
  }
  cancelBtn.addEventListener('click', close)
  ta.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      e.preventDefault()
      close()
    }
    if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
      e.preventDefault()
      saveBtn.click()
    }
  })
  saveBtn.addEventListener('click', async () => {
    const newContent = ta.value.trim()
    if (!newContent) {
      errEl.textContent = 'content cannot be empty'
      return
    }
    if (newContent === original) {
      close()
      return
    }
    saveBtn.disabled = true
    saveBtn.textContent = 'saving...'
    errEl.textContent = ''
    const resp = await apiFetch(`/api/messages/${encodeURIComponent(msg.base36_id)}`, {
      method: 'PATCH',
      body: { content: newContent },
    })
    if (resp?.ok && resp.data?.success) {
      msg.content = resp.data.message?.content || newContent
      msg.edited_at = resp.data.message?.edited_at
      msg.edit_count = resp.data.message?.edit_count
      close()
      // Re-render entire feed to pick up sanitized content + emote refs
      if (typeof renderFeed === 'function') renderFeed()
    } else {
      errEl.textContent = resp?.data?.error || resp?.error || 'edit failed'
      saveBtn.disabled = false
      saveBtn.textContent = 'save'
    }
  })
}

async function deleteFeedPost(msg) {
  if (!confirm('delete this post?')) return
  const resp = await apiFetch(`/api/messages/${encodeURIComponent(msg.base36_id)}`, {
    method: 'DELETE',
  })
  if (resp?.ok) {
    const div = document.querySelector(`.hs-feed-msg[data-msg-id="${CSS.escape(msg.base36_id)}"]`)
    if (div) div.remove()
    const idx = feedMessages.findIndex((m) => m.base36_id === msg.base36_id)
    if (idx >= 0) feedMessages.splice(idx, 1)
  }
}

// ============================================
// SOCIAL TABS (FEED & NOTIFICATIONS)
// ============================================

// API proxy — routes through background.js to bypass CORS + attach auth
async function apiFetch(path, opts = {}) {
  try {
    const resp = await api.runtime.sendMessage({
      type: 'api_fetch',
      path,
      method: opts.method || 'GET',
      auth: opts.auth !== false,
      body: opts.body,
    })
    return resp || { ok: false, error: 'no response' }
  } catch (e) {
    return { ok: false, error: 'context invalidated' }
  }
}

// Load heatsync auth state from storage
async function loadHsAuth() {
  try {
    const data = await api.storage.local.get(['auth_token_encrypted', 'auth_token'])
    hsAuthToken = !!(data.auth_token_encrypted || data.auth_token)
    log('Heatsync auth:', hsAuthToken ? 'logged in' : 'anonymous')
  } catch (e) {
    hsAuthToken = false
  }
  loadHsUsername()

  // Watch for auth changes (login/logout on heatsync.org)
  if (!window._hsMcAuthWatcher) {
    window._hsMcAuthWatcher = true
    api.storage.onChanged.addListener((changes, area) => {
      if (area !== 'local') return
      if (changes.user_info) {
        const ui = changes.user_info.newValue
        hsCurrentUsername = ui?.username?.toLowerCase() || null
        hsCurrentUserId = ui?.id ? String(ui.id) : null
        mentionAliases = new Set()
        if (ui?.username) mentionAliases.add(ui.username.toLowerCase())
        if (ui?.kick_username) mentionAliases.add(ui.kick_username.toLowerCase())
        if (ui?.youtube_username) mentionAliases.add(ui.youtube_username.toLowerCase())
        if (ui?.twitch_username) mentionAliases.add(ui.twitch_username.toLowerCase())
      }
      if (changes.auth_token_encrypted || changes.auth_token) {
        const wasAuthed = hsAuthToken
        hsAuthToken = !!(changes.auth_token_encrypted?.newValue || changes.auth_token?.newValue)
        if (wasAuthed !== hsAuthToken) {
          log('Auth state changed:', hsAuthToken ? 'logged in' : 'logged out')
          // On login, replay any whispers that failed with auth errors so the
          // user doesn't have to manually retry each one.
          if (!wasAuthed && hsAuthToken && typeof retryAuthFailedWhispers === 'function') {
            retryAuthFailedWhispers()
          }
          // Reset feed/discover/pinned data on auth change so the next
          // tab open re-fetches with new auth.
          feedLoaded = false
          feedMessages = []
          discoverLoaded = false
          discoverLoading = false
          discoverTags = []
          discoverProfiles = []
          pinnedLoaded = false
          pinnedLoading = false
          pinnedMessages = []
          if (currentTab === 'feed') {
            renderMessages(currentTab)
          }
          // Auth-bound: re-seed seen-state from the server for the new
          // identity (or fall back to local-only on logout).
          loadSeenState()
        }
      }
    })
  }
}

// Replay (backfill) handler — push to buffer, coalesce render across the
// burst with a microtask debounce. fairMerge sorts by msg.time so each
// replay msg lands at its real chronological position; we just need ONE
// final render after the burst settles. Tab indicator only updates if user
// isn't viewing this tab.
const _replayRenderPending = new Set() // tabIds awaiting coalesced render
// Sidecar dedup index. O(1) lookup vs the previous O(n) buf.some() scan over
// up to 1550 entries per replay msg — replay bursts at reconnect can be huge.
const _replayDedupKeys = new Map() // channelId -> Set<dupKey>
function _ytDupKey(m) {
  return `${m.user}|${(m.text || '').slice(0, 50)}|${Math.floor((m.time || 0) / 1000)}`
}
function ingestReplayYtMsg(targetChannelId, ytMsg) {
  if (!channelYtMessages.has(targetChannelId)) channelYtMessages.set(targetChannelId, [])
  const buf = channelYtMessages.get(targetChannelId)
  let dedup = _replayDedupKeys.get(targetChannelId)
  if (!dedup) {
    dedup = new Set()
    for (const m of buf) dedup.add(_ytDupKey(m))
    _replayDedupKeys.set(targetChannelId, dedup)
  }
  const dupKey = _ytDupKey(ytMsg)
  if (dedup.has(dupKey)) return
  dedup.add(dupKey)
  buf.push(ytMsg)
  if (ytMsg.user) {
    try {
      addUsername(ytMsg.user)
    } catch {}
  }
  if (buf.length > MAX_BUFFER + 50) {
    // Sort by time before truncating so we keep the most recent across
    // backfill + live, not just newest-arrived.
    buf.sort((a, b) => (a.time || 0) - (b.time || 0))
    buf.splice(0, buf.length - MAX_BUFFER)
    // Rebuild dedup set from surviving entries (splice dropped some).
    dedup.clear()
    for (const m of buf) dedup.add(_ytDupKey(m))
  }
  persistYt(targetChannelId)
  const tabId = targetChannelId === '__live_yt_auto__' ? 'live' : targetChannelId
  if (currentTab !== tabId) {
    updateTabIndicator(tabId)
    return
  }
  // Coalesce many replay msgs into a single renderMessages call per tab.
  if (_replayRenderPending.has(tabId)) return
  _replayRenderPending.add(tabId)
  queueMicrotask(() => {
    _replayRenderPending.delete(tabId)
    if (currentTab === tabId) renderMessages(tabId)
  })
}

// Buffer-push + visible render for ONE paced (live) YT message. Critical:
// overwrite ytMsg.time = Date.now() AT THE MOMENT OF EMIT (not at WS arrival).
// Without this, every msg in a 5-sec poll batch shares the same arrival ms
// and the full chronological sort lumps them adjacent, then the next twitch
// msg slots in below — visible as a YT clump in the bottom of chat.
// With per-emit Date.now(), each YT msg's time naturally interleaves with
// the live twitch ms-arrivals that happen between pacer drains.
function commitPacedYtMsg(targetChannelId, ytMsg) {
  // Monotonic per-channel commit clock — two msgs draining in the same ms
  // would otherwise share (user, time, text-prefix) and produce identical
  // stableMsgIds, which the render-diff treats as one key and the dup-set
  // dedup throws away the second display. +1 each collision keeps the key
  // unique while still slotting close to real-time in the chrono sort.
  const lastEmit = _ytPaceLastEmit.get(targetChannelId)
  const now = Date.now()
  ytMsg.time = lastEmit?.time && now <= lastEmit.time ? lastEmit.time + 1 : now
  if (!channelYtMessages.has(targetChannelId)) channelYtMessages.set(targetChannelId, [])
  const buf = channelYtMessages.get(targetChannelId)
  buf.push(ytMsg)
  if (ytMsg.user) {
    try {
      addUsername(ytMsg.user)
    } catch {}
  }
  // Keep the replay-dedup index aligned with the buffer so a later replay msg
  // doesn't get re-inserted as if the live one were missing.
  const dedup = _replayDedupKeys.get(targetChannelId)
  if (dedup) dedup.add(_ytDupKey(ytMsg))
  if (buf.length > MAX_BUFFER + 50) {
    buf.splice(0, buf.length - MAX_BUFFER)
    if (dedup) {
      dedup.clear()
      for (const m of buf) dedup.add(_ytDupKey(m))
    }
  }
  persistYt(targetChannelId)
  const tabId = targetChannelId === '__live_yt_auto__' ? 'live' : targetChannelId
  if (currentTab === tabId) {
    if (!appendMessage(ytMsg, tabId)) renderMessages(tabId)
  } else {
    updateTabIndicator(tabId)
  }
}

// Compute the visual delay until the next paced msg should emit. Uses the
// real-time delta between THIS msg and the PREVIOUS emitted msg, so two
// msgs posted 1.8s apart on YouTube show up 1.8s apart in the panel.
// Clamped to [MIN, MAX] so a 30s gap doesn't stall the panel and a same-
// millisecond burst still drips perceptibly.
function paceDelayFor(channelId, nextMsg) {
  const last = _ytPaceLastEmit.get(channelId)
  if (!last || !last.msgTime || !nextMsg?.time) return YT_PACE_MIN_MS
  const realDelta = nextMsg.time - last.msgTime
  if (realDelta <= 0) return YT_PACE_MIN_MS
  return Math.max(YT_PACE_MIN_MS, Math.min(YT_PACE_MAX_MS, realDelta))
}

// Drain ONE message from the pace queue, schedule next based on the real
// timestamp delta to the message after that.
function drainYtPaceQueue(targetChannelId) {
  _ytPaceTimer.delete(targetChannelId)
  const q = _ytPaceQueue.get(targetChannelId)
  if (!q || !q.length) return
  const ytMsg = q.shift()
  // Snapshot original YT timestamp BEFORE commit overwrites it. Used as
  // the msgTime delta basis for the next drain so paceDelayFor sees the
  // real chat cadence between consecutive msgs, not the rewritten
  // commit-time Date.now()s.
  const realPostMs = ytMsg.time
  commitPacedYtMsg(targetChannelId, ytMsg)
  _ytPaceLastEmit.set(targetChannelId, { time: Date.now(), msgTime: realPostMs })
  if (q.length > 0) {
    const due = paceDelayFor(targetChannelId, q[0])
    const handle = cleanup.setTimeout(() => drainYtPaceQueue(targetChannelId), due)
    _ytPaceTimer.set(targetChannelId, handle)
  } else {
    _ytPaceQueue.delete(targetChannelId)
  }
}

// Queue a YT message for paced delivery. Idle channel (queue empty AND
// >MAX_MS since last emit) → commit immediately, no artificial delay on the
// first msg of a quiet stream. Bursts get the real-delta pacing.
// Catastrophic backlogs (>YT_PACE_BURST_MAX projected at MIN cadence) flush
// overflow synchronously so msgs never feel stale.
function enqueueYtForPacing(targetChannelId, ytMsg) {
  const now = Date.now()
  const last = _ytPaceLastEmit.get(targetChannelId)
  const idleSince = last ? now - last.time : Infinity
  const queued = _ytPaceQueue.get(targetChannelId)
  // Idle channel + cooldown elapsed → emit immediately.
  if ((!queued || queued.length === 0) && idleSince >= YT_PACE_MAX_MS) {
    const realPostMs = ytMsg.time
    commitPacedYtMsg(targetChannelId, ytMsg)
    _ytPaceLastEmit.set(targetChannelId, { time: now, msgTime: realPostMs })
    return
  }
  // Queue the msg.
  if (!queued) _ytPaceQueue.set(targetChannelId, [])
  const q = _ytPaceQueue.get(targetChannelId)
  q.push(ytMsg)
  // Synchronously flush overflow if min-cadence projection exceeds burst-max.
  const minProjected = q.length * YT_PACE_MIN_MS
  if (minProjected > YT_PACE_BURST_MAX) {
    const keep = Math.ceil(YT_PACE_BURST_MAX / YT_PACE_MIN_MS)
    while (q.length > keep) commitPacedYtMsg(targetChannelId, q.shift())
  }
  // Schedule drainer if not already scheduled.
  if (!_ytPaceTimer.has(targetChannelId)) {
    const due = Math.max(paceDelayFor(targetChannelId, q[0]) - idleSince, 0)
    const handle = cleanup.setTimeout(() => drainYtPaceQueue(targetChannelId), due)
    _ytPaceTimer.set(targetChannelId, handle)
  }
}

// Listen for social events from background (new messages, notifications)
function listenForSocialEvents() {
  // Guard: only register once (survives SPA reinit via chrome listener persistence)
  if (window._hsMcSocialListener) return
  window._hsMcSocialListener = true

  cleanup.addListener(chrome.runtime?.onMessage, (msg) => {
    if (msg.type === 'chat_origin_broadcast' && msg.text) {
      // Heatsync.org chat-tile sent a chat — record the origin so the
      // upcoming platform echo gets tagged [H] via peekSentHost. Same
      // 10s dedup window as locally-tracked sends; chrome.storage sync
      // fans this out to other extension tabs automatically.
      try {
        trackSentMessage(msg.text, 'heatsync')
      } catch (_) {}
      return
    }
    if (msg.type === 'seen_update') {
      // Another client (web, other browser, ext on another tab) bumped a
      // tab's seen-at. Apply locally so the red dot clears here too.
      applySeenUpdate(msg.surface, msg.at)
      return
    }
    if (msg.type === 'new-message' && msg.data) {
      // Track home/feed unread regardless of feedLoaded — the user may
      // not have opened the feed tab yet, but we still want a red dot.
      const ts = msg.data.created_at ? new Date(msg.data.created_at).getTime() : Date.now()
      if (!isNaN(ts) && msg.data.username !== 'Anonymous') {
        noteSeenEvent('live', ts)
      }
      if (!feedLoaded) return
      // Dedup: skip if already in feed
      const id = msg.data.base36_id
      if (id && feedMessages.some((m) => m.base36_id === id)) return

      if (msg.data.username === 'Anonymous') return
      // Following tab is OPs only — replies still update their thread + the
      // parent's reply_count below, but never get unshifted as a top-level row.
      if (isOpMsg(msg.data)) {
        feedMessages.unshift(msg.data)
        if (feedMessages.length > 150) feedMessages.pop()
      }

      // Real-time thread update: if reply to the active thread, append it
      const replyTo = msg.data.reply_to
      if (replyTo && activeThread && activeThread.id === replyTo) {
        if (!activeThread.replies.some((r) => r.base36_id === id)) {
          activeThread.replies.push(msg.data)
          if (activeThread.op) activeThread.op.reply_count = (activeThread.op.reply_count || 0) + 1
        }
      }
      // Update OP reply count in feed data
      if (replyTo) {
        const parent = feedMessages.find((m) => m.base36_id === replyTo)
        if (parent) parent.reply_count = (parent.reply_count || 0) + 1
      }

      if (currentTab === 'feed') {
        renderFeed()
      } else {
        updateTabIndicator('feed')
        // Inline notification in chat (routed through toggle system)
        const f = msg.data
        const t = new Date(f.created_at).getTime()
        if (!isNaN(t)) {
          const notifType = f.is_thread_op ? 'mop' : (f.is_op != null ? !!f.is_op : !f.reply_to) ? 'op' : 're'
          injectInlineNotif(notifType, {
            type: 'feed-post',
            base36_id: f.base36_id,
            feedUser: f.username || f.display_name || 'anon',
            text: f.content || '',
            color: f.user_color || '#fff',
            time: t,
            heat: f.heat || 0,
            reply_to: f.reply_to,
            emote_refs: f.emote_refs,
            is_op: f.is_op,
            is_thread_op: f.is_thread_op,
          })
        }
      }
    }
    if (msg.type === 'dm_new' && msg.data) {
      // Server-pushed Twitch whispers must route through handleIncomingWhisper
      // so the dedup key (whisper_id) matches the EventSub path. Using
      // handleIncomingDm here would produce a second timeline entry because
      // its dedup checks data.id (hs db row) != eventsub entry's id (whisper_id).
      if (msg.data.platform === 'twitch') {
        handleIncomingWhisper({
          user: msg.data.from_display_name || msg.data.from_twitch_login || 'unknown',
          userId: msg.data.from_twitch_id,
          text: msg.data.content,
          color: msg.data.from_color || '#fff',
          time: msg.data.created_at ? new Date(msg.data.created_at).getTime() : Date.now(),
          id: msg.data.external_message_id || msg.data.id || '',
        })
      } else {
        handleIncomingDm(msg.data)
      }
    }
    if (msg.type === 'message-edited' && msg.data) {
      const d = msg.data.message_id ? msg.data : msg.data.data
      const id = d?.message_id
      if (!id) return
      // Update feedMessages buffer
      const found = feedMessages.find((m) => m.base36_id === id)
      if (found) {
        found.content = d.content
        found.subject = d.subject
        found.edited_at = d.edited_at
        found.edit_count = d.edit_count
      }
      // Update active thread if applicable
      if (activeThread) {
        if (activeThread.op?.base36_id === id) {
          activeThread.op.content = d.content
          activeThread.op.subject = d.subject
          activeThread.op.edited_at = d.edited_at
        }
        const reply = activeThread.replies?.find((r) => r.base36_id === id)
        if (reply) {
          reply.content = d.content
          reply.edited_at = d.edited_at
        }
      }
      if (currentTab === 'feed') renderFeed()
    }
    if (msg.type === 'message-deleted' && msg.data) {
      const d = msg.data.message_id ? msg.data : msg.data.data
      const id = d?.message_id
      if (!id) return
      const idx = feedMessages.findIndex((m) => m.base36_id === id)
      if (idx >= 0) feedMessages.splice(idx, 1)
      if (activeThread) {
        if (activeThread.op?.base36_id === id) {
          activeThread = null
        } else if (activeThread.replies) {
          const ri = activeThread.replies.findIndex((r) => r.base36_id === id)
          if (ri >= 0) activeThread.replies.splice(ri, 1)
        }
      }
      if (currentTab === 'feed') renderFeed()
    }
    if (msg.type === 'youtube_chat_message') {
      const targetChannelId = msg.channelId
      // Touch the YT watchdog clock on every chat message regardless of
      // dedup/filter outcome — even rejected msgs prove the BG-server pipe
      // is alive for this channel, which is the only thing the watchdog
      // cares about.
      try {
        touchYtChannel(targetChannelId)
      } catch {}
      // Filter __live_yt_auto__ messages: only accept if videoId matches this tab's subscription
      // (prevents cross-tab leaking — e.g., lofigirl YouTube showing on a Twitch tab)
      if (targetChannelId === '__live_yt_auto__') {
        if (!_autoYtVideoId) return // no confirmed subscription yet — reject
        if (msg.videoId && msg.videoId !== _autoYtVideoId) return // wrong video
      }
      // Dedup against message buffer (survives WS reconnects unlike 5s hash)
      if (targetChannelId && isYtDuplicate(msg.user, msg.text, targetChannelId)) return

      // Resolve a Twitch-channel name for emote lookup. YT-relayed messages
      // belong to a streamer who likely also has Twitch/Kick channel emotes
      // (BTTV/FFZ/7TV) configured under their Twitch handle. Without this
      // hint, processEmotes only sees globals + the user's heatsync inventory,
      // missing per-channel emotes for the linked streamer.
      let ytChannelHint = null
      if (targetChannelId && targetChannelId !== '__live_yt_auto__') {
        const linkedCh = config.channels.find((c) => c.id === targetChannelId)
        if (linkedCh) ytChannelHint = linkedCh.twitch || linkedCh.kick || null
      }

      const ytMsg = {
        user: msg.user,
        text: msg.text,
        color: msg.color || '#ff0000',
        channel: ytChannelHint || 'youtube',
        time: msg.time,
        platform: 'youtube',
        emotes: msg.emotes || [],
        msgType: msg.msgType || 'text',
        amount: msg.amount || '',
        scColor: msg.scColor || '',
        sticker: msg.sticker || null,
        avatar: msg.avatar || undefined,
        badges: msg.badges || undefined,
        systemMsg: msg.systemMsg || undefined,
      }

      // Echo dedup + host-platform badge attribution (matches IRC/kick
      // handlers). Without this, a triple-target send would render TWO
      // copies of the user's own message — the dedup'd twitch/kick echo
      // PLUS the unfiltered YT echo. peekSentHost ensures the badge
      // reflects where the user actually typed FROM.
      if (isSentEcho(ytMsg.text, 'youtube')) return
      if (ytMsg.user?.toLowerCase() === currentUsername?.toLowerCase()) {
        const sentHost = peekSentHost(ytMsg.text)
        if (sentHost) ytMsg.platform = sentHost === 'yt' ? 'youtube' : sentHost
      }

      // Same pipeline as Twitch/Kick handlers: automod + filter rules → mention → stats
      if (ytMsg.user?.toLowerCase() !== currentUsername?.toLowerCase() && (
        shouldAutomod(ytMsg.text) ||
        evaluateFilterRules(ytMsg, targetChannelId !== '__live_yt_auto__' ? targetChannelId : null).hide
      )) return
      const isMent = isMention(ytMsg)
      bumpStreamStats(ytMsg.channel, ytMsg, isMent)
      if (isMent) {
        mentionsBuffer.push(ytMsg)
        if (mentionsBuffer.length > MAX_BUFFER + 50) mentionsBuffer.splice(0, mentionsBuffer.length - MAX_BUFFER)
        persistMentions()
        notifyMention(ytMsg)
        noteSeenEvent('mentions', ytMsg.time || Date.now())
        if (currentTab === 'mentions') {
          bumpSeen('mentions')
          if (!appendMessage(ytMsg, 'mentions')) renderMessages('mentions')
        } else {
          updateTabIndicator('mentions')
        }
      }

      if (targetChannelId && targetChannelId !== 'global') {
        // Instant-live signal for YT-only tabs (no Twitch handle = no helix
        // truth available, so first chat msg is our best signal). Tabs with
        // a Twitch or Kick handle defer to the live-status poll — otherwise
        // a YT replay/buffered msg would override the offline-Twitch truth.
        if (targetChannelId !== '__live_yt_auto__') {
          try {
            const ch = config.channels.find((c) => c.id === targetChannelId)
            const isYtOnly = ch && !ch.twitch && !ch.kick && ch.youtube
            if (isYtOnly) {
              const tabEl = document.querySelector(
                `#hs-mc-tabbar .hs-mc-tab[data-tab="${CSS.escape(targetChannelId)}"]`,
              )
              if (tabEl && tabEl.dataset.live !== 'true') tabEl.dataset.live = 'true'
            }
          } catch {}
        }
        // Backfill replay: bypass per-channel pacing entirely. Each msg has
        // its real YT timestamp, so fairMerge places it at the correct
        // chronological position scattered through the existing twitch/kick
        // history — no "all at once" flash because they're not appearing
        // at the bottom; they slot in at their real-time positions. Pacing
        // here would just delay the correct render.
        if (msg.replay) {
          ingestReplayYtMsg(targetChannelId, ytMsg)
        } else {
          enqueueYtForPacing(targetChannelId, ytMsg)
        }
      } else if (targetChannelId === 'global') {
        // Surface unresolved-routing drops so future regressions don't go silent.
        // Real cause is on background side: videoId→channelId map missed an entry.
        console.warn('[heatsync-ext] yt msg dropped — channelId=global, videoId=', msg.videoId, 'user=', msg.user)
      }
    }
    if (msg.type === 'youtube_msg_deleted') {
      // Mark all rendered messages from this user (for the matching channel)
      // as cleared so they get the dim+strikethrough treatment that Twitch/Kick
      // moderator deletions already get.
      const u = (msg.user || '').toLowerCase()
      if (!u) return
      const msgsEl = document.getElementById('hs-mc-messages')
      if (msgsEl) {
        api.storage.local
          .get(['hs_dim_timeouts'])
          .then((stored) => {
            const dim = stored.hs_dim_timeouts !== undefined ? stored.hs_dim_timeouts : true
            if (!dim) return
            // data-platform lives on the inner .hs-mc-user anchor, not the outer
            // .hs-mc-msg div (YouTube is excluded from data-msg-platform), so
            // query the anchor and walk up — mirrors main.js's YT user lookup.
            msgsEl
              .querySelectorAll('.hs-mc-msg .hs-mc-user[data-platform="yt"], .hs-mc-msg .hs-mc-user[data-platform="youtube"]')
              .forEach((a) => {
                if (a.dataset.username === u) a.closest('.hs-mc-msg')?.classList.add('hs-mc-msg-cleared')
              })
          })
          .catch(() => {})
      }
      // Also flag in buffers so re-renders preserve the dim state
      const flagBuf = (buf) => {
        if (!Array.isArray(buf)) return
        for (let i = buf.length - 1; i >= 0; i--) {
          const m = buf[i]
          if (m.platform === 'youtube' && m.user?.toLowerCase() === u) {
            m.cleared = true
            m._renderedHtml = null // force re-render with cleared class next time
          }
        }
      }
      channelYtMessages.forEach((buf) => flagBuf(buf))
      flagBuf(mentionsBuffer)
    }
    if (msg.type === 'youtube_status') {
      const targetChannelId = msg.channelId
      // Connected status touches the watchdog — server confirmed our sub,
      // so the channel is healthy even if no chat messages arrive yet.
      if (msg.status === 'connected') {
        try {
          touchYtChannel(targetChannelId)
        } catch {}
      }
      // Stream genuinely ended → disarm the YT watchdog for this channel.
      // The watchdog never gives up on its own (after a force-reconnect it
      // resets attempts and loops forever), so without this an ended stream
      // re-subscribes every ~3min and periodically force-reconnects the shared
      // BG WS that every channel rides — the "everything dropped, refresh fixed
      // it" symptom (Bug #2). A transient 'error' may still recover, so only a
      // terminal 'ended' disarms; the next 'connected' re-arms via touchYtChannel.
      // Mirrors the removeChannel watchdog cleanup.
      if (msg.status === 'ended' && targetChannelId && targetChannelId !== 'global') {
        try {
          ytChanLastSeen.delete(targetChannelId)
          ytChanRejoinAttempts.delete(targetChannelId)
          ytSubscribedUrls.delete(targetChannelId)
        } catch {}
      }
      // Track auto-YouTube videoId for cross-tab filtering
      if (targetChannelId === '__live_yt_auto__' && msg.status === 'connected' && msg.videoId) {
        _autoYtVideoId = msg.videoId
        log('Auto YouTube videoId:', msg.videoId)
      }
      if (targetChannelId && targetChannelId !== 'global') {
        // Per-channel YouTube status
        const link = youtubeLinks.get(targetChannelId) || { url: '', videoId: '', channelName: '' }
        if (msg.status === 'connected') {
          link.videoId = msg.videoId || ''
          link.channelName = msg.channelName || ''
          youtubeLinks.set(targetChannelId, link)
          log('YouTube connected for channel', targetChannelId, ':', link.channelName)
        }
        // Reflect status onto the channel tab button so YT-only channels get a
        // live dot and a human-readable label (otherwise YT-only tabs sit dark
        // forever and show the auto-generated yt-<timestamp> id). Twitch/Kick-
        // having tabs defer to the live-status poll for the dot — letting YT
        // override would falsely show a Twitch streamer as live just because
        // their YT mirror is live (or replaying buffered chat).
        if (targetChannelId !== '__live_yt_auto__') {
          const tabEl = document.querySelector(`#hs-mc-tabbar .hs-mc-tab[data-tab="${CSS.escape(targetChannelId)}"]`)
          if (tabEl) {
            const ch = config.channels.find((c) => c.id === targetChannelId)
            const isYtOnly = ch && !ch.twitch && !ch.kick && ch.youtube
            if (msg.status === 'connected') {
              if (isYtOnly) {
                tabEl.dataset.live = 'true'
                if (link.channelName && tabEl.textContent !== link.channelName) {
                  tabEl.textContent = link.channelName
                }
              }
            } else if (msg.status === 'ended' || msg.status === 'error') {
              if (isYtOnly) tabEl.dataset.live = 'false'
            }
          }
        }
        // Show status in channel tab if viewing it. Dedup on a stable marker so
        // repeated youtube_status events (every WS reconnect, every retry) don't
        // append a fresh notice each time — that's what made the panel flicker:
        // notice appears, real messages push it out via trimChildren cap, next
        // event re-appends, cycle repeats.
        // Show the connect/end notice on the right tab — both per-channel
        // tabs AND the live tab (when this is the auto subscription).
        const isAutoForLive = targetChannelId === '__live_yt_auto__' && currentTab === 'live'
        if (currentTab === targetChannelId || isAutoForLive) {
          const msgsEl = document.getElementById('hs-mc-messages')
          const upsertNotice = (text, color) => {
            if (!msgsEl) return
            // Remove any existing yt-status notice — there should be at most one,
            // showing the latest state.
            for (const el of msgsEl.querySelectorAll('.hs-mc-empty[data-hs-yt-status]')) el.remove()
            const el = document.createElement('div')
            el.className = 'hs-mc-empty'
            el.dataset.hsYtStatus = '1'
            // Tag with the tab id this notice belongs to so renderMessages can
            // drop it on tab switch (otherwise the YT-offline notice from one
            // channel follows the user to other tabs and looks like a bug:
            // "stream is live, why does it say not live?").
            el.dataset.hsYtStatusTab = String(targetChannelId)
            el.textContent = text
            if (color) el.style.color = color
            msgsEl.appendChild(el)
            trimChildren(msgsEl, 150)
          }
          if (msg.status === 'connected' || msg.status === 'ended') {
            // Live or ended → drop any stale yt-status notice. No "stream
            // ended" pin: it's not actionable (the stream's just over) and it
            // never auto-cleared (the clearing 'connected' event never arrives
            // for an ended stream), so it lingered until trimmed by volume or a
            // tab switch — read as a bug. The live-dot going dark already
            // signals the stream ended; error notices below stay (actionable).
            if (msgsEl) {
              for (const el of msgsEl.querySelectorAll('.hs-mc-empty[data-hs-yt-status]')) el.remove()
            }
          } else if (msg.status === 'error') {
            // Drop noise: rate-limit, "not currently live / chat disabled",
            // AND "could not resolve youtube url" (the expected outcome when
            // a tab's YT URL is auto-guessed from the twitch handle but the
            // streamer doesn't have a matching YT — actionable to nobody).
            const errText = msg.error || ''
            const isNoise =
              /too many requests/i.test(errText) ||
              /not currently live/i.test(errText) ||
              /chat is disabled/i.test(errText) ||
              /could not resolve youtube url/i.test(errText) ||
              /invalid url/i.test(errText)
            if (!isNoise) {
              // Always prefix with "youtube:" — without it, error text looks
              // like it's about whatever stream the user is watching, not
              // the YouTube subscription that actually failed.
              upsertNotice(`youtube: ${errText || 'connection error'}`, '#ff4444')
            }
          }
        }
      }
    }
    if (msg.type === 'message-updated' && msg.data) {
      const uid = msg.data.base36_id
      const idx = feedMessages.findIndex((m) => m.base36_id === uid)
      if (idx >= 0) Object.assign(feedMessages[idx], msg.data)
      if (activeThread && activeThread.op && activeThread.op.base36_id === uid) {
        Object.assign(activeThread.op, msg.data)
      }
    }
  })
}

// ---- FEED ----

// A feed row is an OP (original post / "tweet") when it isn't a reply. The
// following tab shows OPs only — replies live inside their thread, opened via
// >>id, never as top-level rows. Mirrors buildFeedMessageDiv's isOp test.
function isOpMsg(m) {
  return m.is_op != null ? !!m.is_op : (!m.reply_to || m.reply_to === '')
}

async function fetchFeed(append = false) {
  if (feedLoading) return
  feedLoading = true
  const page = append ? feedPage + 1 : 1
  // Snapshot ids before the await so we can keep posts that arrive via the WS
  // new-message handler (which unshifts onto feedMessages) while this fetch is
  // in flight — otherwise the full replace below silently drops them. Only on a
  // refresh (feedLoaded already true); first load can't race (handler bails
  // when !feedLoaded), and append doesn't replace.
  const preIds = feedLoaded && !append ? new Set(feedMessages.map((m) => m.base36_id)) : null
  const resp = await apiFetch(`/api/messages?sort=time&limit=30&page=${page}&following=true`, { auth: true })
  feedLoading = false
  if (!resp.ok) {
    // 429 means the user has multichat open in many tabs hitting /api/messages
    // simultaneously — expected, not a bug, don't spam the error log. log via
    // debug instead. true server errors (5xx, 401) still console.error.
    if (resp.status === 429) {
      log('feed fetch 429 — rate-limited, will retry on next stale check')
    } else {
      console.error('[heatsync-mc] Feed fetch failed — full resp:', JSON.stringify(resp))
    }
    if (currentTab === 'feed') {
      const msgsEl = document.getElementById('hs-mc-messages')
      if (msgsEl && feedMessages.length === 0) {
        msgsEl.innerHTML = `<div class="hs-mc-empty">${resp.status === 401 ? t('mc_social_failed_feed_auth') : t('mc_social_failed_feed')}</div>`
      }
    }
    return
  }
  let msgs = (resp.data?.messages || []).filter((m) => m.username !== 'Anonymous' && isOpMsg(m))
  let usedHotFallback = false

  // Following empty → fallback to /api/messages/hot (heat-sorted, last 30d) so
  // the tab shows SOMETHING discoverable instead of an empty wall. Only on the
  // initial page (append=false) — paginating shouldn't trigger fallback. Auth
  // gate stays the same since the empty-card has the login CTA.
  if (!append && msgs.length === 0 && hsAuthToken) {
    try {
      const hotResp = await apiFetch('/api/messages/hot?limit=30&hours=720', { auth: true })
      if (hotResp.ok) {
        const hotMsgs = (hotResp.data?.messages || []).filter((m) => m.username !== 'Anonymous' && isOpMsg(m))
        if (hotMsgs.length > 0) {
          msgs = hotMsgs.map((m) => Object.assign({}, m, { _fromHotFallback: true }))
          usedHotFallback = true
        }
      }
    } catch (_) {}
  }

  if (append) {
    feedMessages.push(...msgs)
    feedPage = page
  } else {
    if (preIds) {
      // Posts unshifted during the await that aren't in the server snapshot —
      // keep them newest-first on top so a live post isn't lost to the replace.
      const seen = new Set(msgs.map((m) => m.base36_id))
      const liveDelta = feedMessages.filter((m) => !preIds.has(m.base36_id) && !seen.has(m.base36_id))
      feedMessages = liveDelta.length ? [...liveDelta, ...msgs] : msgs
    } else {
      feedMessages = msgs
    }
    feedPage = 1
    feedFromHotFallback = usedHotFallback
  }
  // Clamp after bulk load — push-path uses .pop() cap but server can return >150 in one fetch.
  if (feedMessages.length > 150) feedMessages.length = 150
  // Hot fallback returns sorted-by-heat from past 30d — never paginate that;
  // would conflict with the heat ranking on subsequent pages.
  feedHasMore = usedHotFallback ? false : (resp.data?.pagination?.hasMore ?? msgs.length >= 30)
  feedLoaded = true
  feedLastFetch = Date.now()
  // Seed latestAt.live from the newest post we just got. Without this, the
  // unread dot is event-driven only (WS new-message), so a user opening the
  // ext after sleep sees 12 unread feed posts but no red dot until the 13th
  // event arrives. Bumping latestAt here makes hasUnseen('live') agree with
  // the actual server backlog.
  if (!append && msgs.length > 0 && typeof noteSeenEvent === 'function') {
    const newestTs = msgs.reduce((mx, m) => {
      const ts = m.created_at ? new Date(m.created_at).getTime() : 0
      return ts > mx ? ts : mx
    }, 0)
    if (newestTs > 0) noteSeenEvent('live', newestTs)
  }
  if (currentTab === 'feed') renderFeed()
}

// Onboarding card shown when feed has no posts. Replaces the bare
// "no posts yet" sentinel that produced an immediate uninstall cliff.
// Variants: anonymous (login CTA) vs authed (import-twitch + discover + post).
function _renderFeedEmptyCard() {
  const card = document.createElement('div')
  card.className = 'hs-mc-empty-card'

  const title = document.createElement('div')
  title.className = 'hs-mc-empty-title'
  const sub = document.createElement('div')
  sub.className = 'hs-mc-empty-sub'
  const actions = document.createElement('div')
  actions.className = 'hs-mc-empty-actions'

  if (!hsAuthToken) {
    title.textContent = 'log in to see your home'
    sub.textContent = 'follow people, post, share — alongside multichat'

    const loginBtn = document.createElement('a')
    loginBtn.className = 'hs-mc-empty-btn primary'
    loginBtn.textContent = 'log in at heatsync.org'
    loginBtn.href = 'https://heatsync.org/login'
    loginBtn.target = '_blank'
    loginBtn.rel = 'noopener noreferrer'
    actions.appendChild(loginBtn)

    const note = document.createElement('div')
    note.className = 'hs-mc-empty-note'
    note.textContent = 'no account needed for multichat — pick a channel tab above'

    card.appendChild(title)
    card.appendChild(sub)
    card.appendChild(actions)
    card.appendChild(note)
    return card
  }

  title.textContent = 'no posts'
  sub.textContent = 'follow people or post something to populate this tab'

  const importBtn = document.createElement('button')
  importBtn.className = 'hs-mc-empty-btn primary'
  importBtn.textContent = 'import follows from twitch'
  importBtn.addEventListener('click', async () => {
    if (importBtn.disabled) return
    importBtn.disabled = true
    importBtn.textContent = 'syncing…'
    try {
      const r = await apiFetch('/api/sync-twitch-follows', { method: 'POST', auth: true })
      if (r?.ok && r?.data?.success) {
        importBtn.textContent = `synced ${r.data.synced || 0} ✓`
        try {
          chrome.runtime.sendMessage({ type: 'refresh_followed_users' })
        } catch {}
        cleanup.setTimeout(() => {
          feedLoaded = false
          if (currentTab === 'feed') renderFeed()
        }, 1200)
      } else {
        importBtn.disabled = false
        importBtn.textContent = (r?.error || r?.data?.error || 'try again').slice(0, 40)
      }
    } catch (e) {
      importBtn.disabled = false
      importBtn.textContent = 'try again'
    }
  })
  actions.appendChild(importBtn)

  const discoverBtn = document.createElement('button')
  discoverBtn.className = 'hs-mc-empty-btn'
  discoverBtn.textContent = 'discover people →'
  discoverBtn.addEventListener('click', () => {
    if (typeof switchTab === 'function') switchTab('discover')
  })
  actions.appendChild(discoverBtn)

  const postBtn = document.createElement('button')
  postBtn.className = 'hs-mc-empty-btn'
  postBtn.textContent = 'post something'
  postBtn.addEventListener('click', () => {
    if (typeof showInputBar === 'function') showInputBar()
    const inp = document.getElementById('hs-mc-input')
    if (inp) inp.focus()
  })
  actions.appendChild(postBtn)

  card.appendChild(title)
  card.appendChild(sub)
  card.appendChild(actions)
  return card
}

// Tear down virtual scroll state (called before re-setup or when leaving feed)
function _feedVirtualTeardown(msgsEl) {
  if (_feedVirtualScrollHandler && msgsEl) {
    msgsEl.removeEventListener('scroll', _feedVirtualScrollHandler)
  }
  _feedVirtualScrollHandler = null
}

function renderFeed() {
  if (typeof activeProfileCard !== 'undefined' && activeProfileCard) return
  const msgsEl = document.getElementById('hs-mc-messages')
  if (!msgsEl) return

  // Wire post-link hover preview once (event delegation — survives re-renders).
  // Must run before the thread-view early-return below: >>id links live IN the
  // thread view, so wiring only on the feed-list path missed them entirely.
  if (typeof setupFeedPostLinkHover === 'function') setupFeedPostLinkHover()

  // Update feed tab button text
  const feedTabBtn = tabBarElement?.querySelector('[data-tab="feed"]')
  if (feedTabBtn) feedTabBtn.textContent = activeThread ? t('mc_social_back') : t('mc_tab_feed')

  // Thread view — show OP + replies, tear down virtual scroll
  if (activeThread) {
    _feedVirtualTeardown(msgsEl)
    renderThreadView(msgsEl)
    return
  }

  // Feed list view
  const isStale = feedLoaded && Date.now() - feedLastFetch > FEED_STALE_MS
  if ((!feedLoaded || isStale) && !feedLoading) {
    _feedVirtualTeardown(msgsEl)
    msgsEl.textContent = ''
    const loading = document.createElement('div')
    loading.className = 'hs-mc-empty'
    loading.textContent = t('mc_social_loading_feed')
    msgsEl.appendChild(loading)
    fetchFeed()
    return
  }

  if (feedMessages.length === 0) {
    _feedVirtualTeardown(msgsEl)
    msgsEl.textContent = ''
    msgsEl.appendChild(_renderFeedEmptyCard())
    return
  }

  // Render all feed posts in natural document flow. Virtualization removed —
  // posts have wildly mixed heights (32px text vs 327px media embeds) and a
  // uniform-height virtual scroller produced massive overlap. If post counts
  // grow large enough to hurt scroll perf, re-add virtualization with proper
  // per-item height measurement (cumulative offsets, not i*h).
  _feedVirtualTeardown(msgsEl)

  const items = feedMessages
  isProgrammaticScroll = true
  msgsEl.textContent = ''
  msgsEl.style.position = ''

  const frag = document.createDocumentFragment()
  // Hot-fallback banner — set when following=true returned 0 and we filled the
  // tab with /api/messages/hot. Says "no follows yet" + invites action. Pure
  // DOM construction (no innerHTML) — both strings are static, the hook flags
  // any innerHTML anyway.
  if (feedFromHotFallback) {
    const banner = document.createElement('div')
    banner.className = 'hs-mc-feed-fallback-banner'
    banner.style.cssText =
      'padding:8px 10px;background:#1a1408;border-left:2px solid #ff8700;color:#e6e6e6;font-size:12px;margin-bottom:4px;line-height:1.5'
    const head = document.createElement('div')
    head.style.cssText = 'color:#ff8700;font-weight:600;margin-bottom:2px'
    head.textContent = 'no posts from your follows'
    const sub = document.createElement('div')
    sub.style.cssText = 'color:#bbb'
    sub.textContent = 'showing what is hot from the past 30 days — follow people to fill this with their posts'
    banner.appendChild(head)
    banner.appendChild(sub)
    frag.appendChild(banner)
  }
  let zebraCount = 0
  for (let i = 0; i < items.length; i++) {
    const div = buildFeedMessageDiv(items[i])
    if (zebraEnabled && ++zebraCount % 2 === 0) div.classList.add('hs-mc-zebra')
    frag.appendChild(div)
  }
  msgsEl.appendChild(frag)

  if (feedHasMore) {
    const loader = document.createElement('div')
    loader.className = 'hs-mc-empty hs-feed-loader'
    loader.textContent = t('mc_social_scroll_more')
    msgsEl.appendChild(loader)
  }

  msgsEl.scrollTop = 0
  requestAnimationFrame(() => {
    isProgrammaticScroll = false
  })

  // Reddit (and any future server-resolved embeds): replace pending placeholders
  // with rich cards via heatsync.org/api/embed/resolve. Mirrors website.
  if (typeof resolvePendingFeedEmbeds === 'function') resolvePendingFeedEmbeds(msgsEl)

  // Infinite scroll: trigger fetch near bottom
  let _feedInfiniteTimer = null
  _feedVirtualScrollHandler = () => {
    if (mcSignal?.aborted) return
    if (currentTab !== 'feed' || feedLoading || !feedHasMore) return
    if (_feedInfiniteTimer) return
    _feedInfiniteTimer = cleanup.setTimeout(() => {
      _feedInfiniteTimer = null
      const { scrollTop, scrollHeight, clientHeight } = msgsEl
      if (scrollHeight - scrollTop - clientHeight < 100) fetchFeed(true)
    }, 200)
  }
  msgsEl.addEventListener('scroll', _feedVirtualScrollHandler, { signal: mcSignal, passive: true })
}

function buildFeedMessageDiv(m, opUsername) {
  const div = document.createElement('div')
  div.className = 'hs-feed-msg'
  div.dataset.msgId = m.base36_id

  const time = formatRelativeTime(m.created_at)
  const rawAvatar = m.profile_image_url || m.twitch_profile_pic || m.kick_profile_pic || ''
  const avatarUrl = safeUrl(rawAvatar)
  // Number() coercion is the guard: a non-numeric server value (e.g. a string)
  // would slip past getHeatDisplay's NaN comparisons and reach innerHTML
  // verbatim via formatHeat. Mirrors heatSpanHtml/heatSpanEl.
  const heat = Number(m.heat) || 0
  const replies = m.reply_count || 0
  // renderFeedContent sanitizes via escapeHtml + emote ref escaping
  const content = renderFeedContent(m.content, m.emote_refs)

  // Thread link: >>id — always expands thread inline (never navigates away)
  const shortId = (m.base36_id || '').replace(/^0+/, '') || '0'
  const inThread = !!opUsername
  const linkId = escapeHtml(m.base36_id || '')
  const threadLink = inThread
    ? `<span class="hs-feed-thread-link hs-quote-insert" data-quote-id="${escapeHtml(shortId)}" data-id="${linkId}" style="color:#ffff00;cursor:pointer">${escapeHtml(shortId)}</span>`
    : `<span class="hs-feed-thread-link hs-thread-toggle" data-id="${linkId}" style="cursor:pointer">&gt;&gt;${escapeHtml(shortId)}</span>`

  // Post type tag: [OP] red = original post, [OP] magenta = OP replying in own thread, [RE] = reply
  const isOp = m.is_op != null ? !!m.is_op : !m.reply_to || m.reply_to === ''
  const isThreadOp =
    m.is_thread_op != null
      ? !!m.is_thread_op
      : opUsername && m.reply_to && m.username?.toLowerCase() === opUsername.toLowerCase()
  const typeTag = isThreadOp
    ? '<span class="hs-feed-tag hs-feed-tag-mop">[OP]</span>'
    : isOp
      ? '<span class="hs-feed-tag hs-feed-tag-op">[OP]</span>'
      : '<span class="hs-feed-tag hs-feed-tag-re">[RE]</span>'

  // Anonymity is "no user", not "no platform" — native heatsync posts have a
  // user_id but no platform (only twitch/kick/youtube-origin posts carry one).
  // Gating on platform wrongly anonymized native posts. Mirrors heatsync.org's
  // message-element renderer (`!user_id || display_name === 'Anonymous'`).
  const isAnon = !m.user_id || m.username === 'Anonymous'

  // Platform badge: [T]/[K]/[Y] (hidden for anonymous)
  const platLabel =
    m.platform === 'kick' ? '[K]' : m.platform === 'youtube' ? '[Y]' : m.platform === 'twitch' ? '[T]' : ''
  const platColors = { twitch: '#9146ff', kick: '#53fc18', youtube: '#ff0000' }
  const platBadge = platLabel
    ? `<span class="hs-feed-tag" style="color:${platColors[m.platform]}">${platLabel}</span>`
    : ''

  const timeHtml = window._hsTimestampsEnabled !== false ? `<span class="hs-feed-time">${escapeHtml(time)}</span>` : ''

  // All dynamic values sanitized: avatarUrl via encodeURIComponent,
  // username/time via escapeHtml, color via sanitizeColor, content via renderFeedContent
  const hd = getHeatDisplay(heat)
  if (hd) {
    let rowStyle = `border-left:${hd.borderWidth}px solid ${hd.border};`
    if (hd.bg) rowStyle += `background:${hd.bg};`
    if (hd.breathe) div.className += ' hs-feed-heat-breathe'
    div.setAttribute('style', rowStyle)
  }
  const isReply = !!m.reply_to
  const heatStyle = hd ? getHeatNumberStyle(heat, isReply) : ''
  const heatDeg = hd && hd.suffix ? '<span class="hs-heat-deg">°</span>' : ''
  const heatSpan = hd
    ? `<span class="hs-feed-stat hs-feed-heat" style="${heatStyle}"><span class="hs-heat-n">${formatHeat(heat)}</span>${heatDeg}</span>`
    : ''
  const repliesSpan =
    replies > 0 ? `<span class="hs-feed-stat hs-feed-replies" title="replies">💬${replies}</span>` : ''
  const stats = [heatSpan, repliesSpan].filter(Boolean).join(' ')
  const statsHtml = stats ? ` ${stats}` : ''

  const anonAvatar = avatarsEnabled
    ? `<img class="hs-feed-avatar" src="https://heatsync.org/anon.webp" alt="" loading="lazy">`
    : ''
  const userAvatar = avatarsEnabled
    ? avatarUrl
      ? `<img class="hs-feed-avatar" src="${escapeHtml(avatarUrl)}" alt="" loading="lazy" data-fallback-anon="1">`
      : anonAvatar
    : ''
  const tripcodeHtml = m.tripcode ? `<span class="hs-tripcode">${escapeHtml(m.tripcode)}</span>` : ''
  const userHtml = isAnon
    ? `${anonAvatar}<span class="hs-feed-user" style="color:#808080">Anonymous</span>${tripcodeHtml}`
    : `${userAvatar}<a href="https://heatsync.org/user/${encodeURIComponent(m.username)}" target="_blank" rel="noopener noreferrer" class="hs-feed-user hs-mc-user" data-username="${escapeHtml((m.username || 'anon').toLowerCase())}" style="color:${sanitizeColor(m.user_color || '#fff')}">${escapeHtml(m.username || 'anon')}</a>${tripcodeHtml}`

  // Media/embeds (img, video, iframe) — values inside are pre-sanitized via escapeHtml/safeUrl/sanitizeEmbedId
  const mediaHtml = buildFeedMediaHtml(m)
  // All interpolated parts are pre-sanitized: the meta fields via escapeHtml/safeUrl/
  // sanitizeColor/sanitizeEmbedId, and `content` via renderFeedContent (which neutralizes
  // literal '<' in the server payload, closing the server-HTML-trust vector).
  div.innerHTML = `${timeHtml}${threadLink}${typeTag}${platBadge}${userHtml}${statsHtml}: <span class="hs-feed-body">${content}</span>${mediaHtml}`

  // Wire host-CSP-safe fallbacks for avatar/media error handlers (no inline onerror=).
  attachFeedFallbacks(div)

  // Click >>id to expand/collapse thread inline — never leaves the stream
  // If this post is a reply, open the parent thread and highlight this post
  const threadLinkEl = div.querySelector('.hs-thread-toggle')
  if (threadLinkEl) {
    threadLinkEl.addEventListener('click', (e) => {
      e.preventDefault()
      e.stopPropagation()
      const threadId = m.reply_to || m.base36_id
      const highlightId = m.reply_to ? m.base36_id : null
      toggleThread(threadId, highlightId)
    })
  }
  const repliesEl = div.querySelector('.hs-feed-replies')
  if (repliesEl && replies > 0) {
    repliesEl.style.cursor = 'pointer'
    repliesEl.addEventListener('click', (e) => {
      e.stopPropagation()
      toggleThread(m.reply_to || m.base36_id)
    })
  }

  // Click >>id post-links in message content
  div.querySelectorAll('.hs-post-link').forEach((link) => {
    link.addEventListener('click', (e) => {
      e.preventDefault()
      e.stopPropagation()
      const targetId = link.dataset.id
      if (!targetId) return
      // Find the target in feedMessages to determine its thread
      const target = feedMessages.find((f) => f.base36_id === targetId)
      const threadId = target ? target.reply_to || target.base36_id : targetId
      openThread(threadId, targetId)
    })
  })

  // Stash the message object so the universal right-click handler (input.js)
  // can build the follow/block/edit/delete menu for this post.
  div._hsFeedMsg = m
  // Show edited badge if message was edited
  if (m.edited_at && !div.querySelector('.hs-feed-edited')) {
    const body = div.querySelector('.hs-feed-body')
    if (body) {
      const badge = document.createElement('span')
      badge.className = 'hs-feed-edited'
      badge.textContent = ' (edited)'
      badge.style.cssText = 'color:#888;font-size:13px;font-style:italic;margin-left:4px;'
      body.appendChild(badge)
    }
  }

  // Click post ID in thread view → insert >>id into input
  const quoteEl = div.querySelector('.hs-quote-insert')
  if (quoteEl) {
    quoteEl.addEventListener('click', (e) => {
      e.preventDefault()
      e.stopPropagation()
      const qid = quoteEl.dataset.quoteId
      if (!qid) return
      const input = document.getElementById('hs-mc-input')
      if (!input) return
      const quote = `>>${qid} `
      if (wysiwygEnabled) {
        input.focus()
        document.execCommand('insertText', false, quote)
      } else {
        const pos = input.selectionStart || input.value.length
        input.value = input.value.slice(0, pos) + quote + input.value.slice(pos)
        input.focus()
        input.selectionStart = input.selectionEnd = pos + quote.length
      }
    })
  }

  return div
}

// Format text with markdown-style syntax (matches heatsync.org rendering)
// Must be called AFTER escapeHtml — operates on escaped HTML strings
function formatText(html) {
  // Greentext: >text< (escaped as &gt;text&lt;)
  html = html.replace(/(&gt;)([^<>&]+)(&lt;)/g, '<span class="hs-greentext">&gt;$2&lt;</span>')
  // Inline code: `text`
  html = html.replace(/`([^`]+)`/g, '<code class="hs-inline-code">$1</code>')
  // Bold: **text** or __text__
  html = html.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  html = html.replace(/__(.+?)__/g, '<strong>$1</strong>')
  // Italic: *text* or _text_ (not if part of bold)
  html = html.replace(/(?<!\*)\*(?!\*)(.+?)(?<!\*)\*(?!\*)/g, '<em>$1</em>')
  html = html.replace(/(?<!_)_(?!_)(.+?)(?<!_)_(?!_)/g, '<em>$1</em>')
  // Strikethrough: ~~text~~
  html = html.replace(/~~(.+?)~~/g, '<del>$1</del>')
  // Spoilers: ||text||
  html = html.replace(/\|\|(.+?)\|\|/g, '<span class="hs-spoiler">$1</span>')
  return html
}

const _feedEmoteRegexCache = new Map()
// Render one feed emote with the SAME wrapper structure chat uses, so
// right-click block/unblock works (queryEmoteWrappers matches
// .hs-mc-emote-wrapper[data-emote-name], findEmoteTarget reads data-state).
// Bare <img> rendered the emote but left it un-blockable — toast fired, image stayed.
function renderFeedEmote(name, url, source, hash) {
  const dn = escapeHtml(name)
  // Blocked → dashed box (transparent px), never the real image. Matches chat's
  // blocked branch so the block actually hides the emote on re-render.
  if (typeof blockedEmoteNames !== 'undefined' && blockedEmoteNames.has(name)) {
    return `<span class="hs-mc-emote-wrapper hs-state-blocked" data-emote-name="${dn}" data-state="blocked" data-source="heatsync"><img src="${HS_TRANSPARENT_PX}" alt="${dn}" title="${dn}" class="hs-mc-emote hs-emote-blocked" style="width:var(--hs-emote-size,32px);height:var(--hs-emote-size,32px)" data-emote-name="${dn}" data-state="blocked" data-source="heatsync"></span>`
  }
  const sanitizedUrl = escapeHtml(safeUrl(url))
  const src = escapeHtml(source || 'unknown')
  const state = typeof getEmoteState === 'function' ? getEmoteState(name, source) : 'global'
  const hashAttr = hash ? ` data-emote-hash="${escapeHtml(hash)}"` : ''
  return `<span class="hs-mc-emote-wrapper hs-state-${state}" data-emote-name="${dn}" data-emote-url="${sanitizedUrl}" data-state="${state}" data-source="${src}"${hashAttr}><img src="${sanitizedUrl}" alt="${dn}" title="${dn}" class="hs-mc-emote hs-emote-${state}" data-emote-name="${dn}" data-state="${state}" data-source="${src}" loading="lazy" decoding="async"></span>`
}

function renderFeedContent(content, emoteRefs) {
  if (!content) return ''
  // Content is ALREADY HTML-escaped by the server (sanitizeUserInput on store).
  // We do NOT full-escape again — that would double-encode `&` and break the
  // server's `&gt;&gt;id` post-link syntax. But the server is a trust boundary:
  // a MITM or a server-side sanitizer bypass could deliver raw `<img onerror=…>`
  // straight into innerHTML below. Defense in depth: neutralize any LITERAL `<`
  // (legit escaped content has none — it uses `&lt;`), which makes a raw tag
  // impossible to form while leaving entities and `>>id` untouched. No parser,
  // so no mXSS/parser-differential bypass like a DOM sanitizer can have.
  let html = String(content).replace(/</g, '&lt;')
  // Linkify URLs FIRST so text-formatting can't split them on '_' or eat path chars.
  // Single regex pass with alternation: full https:// URLs OR bare domains.
  // (?<![\/\w.]) on the bare-domain branch prevents matching inside an already-linkified URL path.
  if (linksEnabled) {
    html = html.replace(/(https?:\/\/[^\s<"]+|(?<![/\w.])[a-z0-9-]+(?:\.[a-z0-9-]+)+\/[^\s<"]*)/gi, (match) => {
      const url = /^https?:\/\//i.test(match) ? match : 'https://' + match
      const text = escapeHtml(match)
      const href = escapeHtml(url)
      return `<a href="${href}" target="_blank" rel="noopener noreferrer" class="hs-mc-link">${text}</a>`
    })
  }
  // Text formatting (bold, italic, spoilers, etc.) — skip <a>...</a> blocks so URL underscores aren't italicized.
  {
    const parts = html.split(/(<a\s[^>]*>[^<]*<\/a>)/i)
    html = parts.map((part, i) => (i % 2 === 1 ? part : formatText(part))).join('')
  }
  // Parse >>id post-links (like website does)
  html = html.replace(/(?:&gt;&gt;|>>)(\w{1,6})/g, (match, id) => {
    const paddedId = id.padStart(6, '0')
    const displayId = id.replace(/^0+/, '') || '0'
    return `<span class="hs-post-link" data-id="${paddedId}" style="cursor:pointer">&gt;&gt;${displayId}</span>`
  })

  // Parse @mentions — must skip inside HTML tags (already-built anchors, post-links, etc.)
  // Match site's pattern: @username with 1-25 word chars
  {
    const parts = html.split(/(<[^>]+>)/)
    html = parts
      .map((part, i) => {
        if (i % 2 === 1) return part
        return part.replace(/@([\w]{1,25})\b/g, (m, name) => {
          const lower = name.toLowerCase()
          const isSelf = hsCurrentUsername === lower
          const cls = isSelf ? 'hs-mention self' : 'hs-mention'
          return `<a href="https://heatsync.org/user/${encodeURIComponent(name)}" target="_blank" rel="noopener noreferrer" class="${cls}" data-username="${escapeHtml(lower)}">@${escapeHtml(name)}</a>`
        })
      })
      .join('')
  }

  // Parse #hashtags — site pattern: leading letter, 2-30 chars total
  {
    const parts = html.split(/(<[^>]+>)/)
    html = parts
      .map((part, i) => {
        if (i % 2 === 1) return part
        // (?<!&) — part is already escaped; don't tag #x27 inside &#x27; etc.
        return part.replace(/(?<!&)#([a-zA-Z][a-zA-Z0-9_]{1,29})\b/g, (m, tag) => {
          return `<a href="https://heatsync.org/tags/${encodeURIComponent(tag)}" target="_blank" rel="noopener noreferrer" class="hs-hashtag" data-tag="${escapeHtml(tag)}">#${escapeHtml(tag)}</a>`
        })
      })
      .join('')
  }

  // Render emote refs as inline images (AFTER linkification so img tags aren't corrupted)
  // emote_refs can be { name: url } or { name: { url, hash, name, provider } }
  if (emoteRefs && typeof emoteRefs === 'object') {
    for (const [name, val] of Object.entries(emoteRefs)) {
      const url = safeUrl(typeof val === 'string' ? val : val?.url)
      if (!url) continue
      const source = typeof val === 'object' ? val?.provider || 'heatsync' : 'heatsync'
      const hash = typeof val === 'object' ? val?.hash : ''
      const escaped = escapeHtml(name)
      const cacheKey = escaped
      let re = _feedEmoteRegexCache.get(cacheKey)
      if (!re) {
        re = new RegExp(`\\b${escaped.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'g')
        _feedEmoteRegexCache.set(cacheKey, re)
        if (_feedEmoteRegexCache.size > 500) _feedEmoteRegexCache.delete(_feedEmoteRegexCache.keys().next().value)
      }
      html = html.replace(re, renderFeedEmote(name, url, source, hash))
    }
  }

  // Local emote fallback: render 7TV/BTTV/FFZ/channel emotes the server can't
  // resolve (not in emote_refs — site only knows heatsync emotes). The extension
  // augments with the viewer's full local emote set, matching chat-tile rendering.
  if (typeof lookupEmote === 'function') {
    const refNames = emoteRefs && typeof emoteRefs === 'object' ? new Set(Object.keys(emoteRefs)) : null
    const parts = html.split(/(<[^>]+>)/)
    html = parts
      .map((part, i) => {
        if (i % 2 === 1) return part // inside an HTML tag — skip
        return part.replace(/\S+/g, (word) => {
          if (refNames && refNames.has(word)) return word // already rendered above
          // Blocked emote dropped from caches — still box it, don't leak the name.
          if (typeof blockedEmoteNames !== 'undefined' && blockedEmoteNames.has(word)) {
            return renderFeedEmote(word, '', 'heatsync', '')
          }
          const em = lookupEmote(word)
          if (!em || !em.url || !/^https:\/\//.test(em.url)) return word
          return renderFeedEmote(word, em.url, em.source, em.hash)
        })
      })
      .join('')
  }
  return html
}

function formatRelativeTime(isoDate) {
  if (!isoDate) return ''
  return formatRelativeMs(Date.now() - new Date(isoDate).getTime())
}

function formatRelativeMs(diff) {
  if (diff < 0) return 'now'
  const mins = Math.floor(diff / 60000)
  if (mins < 1) return 'now'
  if (mins < 60) return `${mins}m`
  const hours = Math.floor(mins / 60)
  if (hours < 24) return `${hours}h`
  const days = Math.floor(hours / 24)
  return `${days}d`
}

// Chat-row timestamp = wall-clock HH:MM (24h, local). The "timestamps" toggle
// promises "timestamp on each message" — a clock time, not a relative age. A
// past message's clock time never changes, so no periodic refresh is needed.
function formatTimeFromTs(ts) {
  if (!ts) return ''
  const d = new Date(ts)
  if (getSetting('timestampFormat') === '12h') {
    let h = d.getHours() % 12
    if (h === 0) h = 12
    return `${h}:${String(d.getMinutes()).padStart(2, '0')}${d.getHours() >= 12 ? 'pm' : 'am'}`
  }
  return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`
}

// Open thread view — replaces feed with OP + replies + reply input
async function openThread(msgId, highlightId) {
  // Find OP in feed or fetch it
  const op = feedMessages.find((m) => m.base36_id === msgId)
  const thread = { id: msgId, op: op || null, replies: [], loading: true, highlightId: highlightId || null }
  activeThread = thread
  renderFeed()
  _renderFeedReplyChip(thread)
  if (typeof showInputBar === 'function') showInputBar()

  const resp = await apiFetch(`/api/messages/${msgId}/replies`)
  // Bail if the user closed this thread or opened another during the fetch —
  // otherwise the unconditional writes below throw on null (closeThread /
  // remote-delete) or paint thread A's replies under thread B's header.
  if (activeThread !== thread) return
  if (resp.ok) {
    thread.replies = resp.data?.replies || []
  }
  thread.loading = false

  renderFeed()

  // Scroll to and highlight the target post
  if (highlightId) {
    const msgsEl = document.getElementById('hs-mc-messages')
    const target = msgsEl?.querySelector(`[data-msg-id="${highlightId}"]`)
    if (target) {
      target.scrollIntoView({ behavior: 'instant', block: 'center' })
      target.classList.add('hs-post-highlight')
      cleanup.setTimeout(() => target.classList.remove('hs-post-highlight'), 1000)
    }
  }
}

function closeThread() {
  activeThread = null
  _clearFeedReplyChip()
  renderFeed()
}

// Reply-state chip shown above input bar when in thread view.
// [OP] magenta if you are the thread OP, [RE] cyan otherwise.
// Mirrors the [OP]/[RE] tag system from feed posts so click-to-reply
// has the same visual language as the rendered output.
function _renderFeedReplyChip(thread) {
  document.getElementById('hs-mc-feed-reply-chip')?.remove()
  if (!thread || !thread.id) return
  const bar = document.getElementById('hs-mc-inputbar')
  if (!bar) return

  const chip = document.createElement('div')
  chip.id = 'hs-mc-feed-reply-chip'
  chip.className = 'hs-mc-feed-reply-chip'

  const opUser = thread.op?.username?.toLowerCase() || ''
  const isOwnOp = !!(hsCurrentUsername && opUser && hsCurrentUsername.toLowerCase() === opUser)

  const tag = document.createElement('span')
  tag.className = isOwnOp ? 'hs-feed-tag hs-feed-tag-mop' : 'hs-feed-tag hs-feed-tag-re'
  tag.textContent = isOwnOp ? '[OP]' : '[RE]'
  chip.appendChild(tag)

  const ref = document.createElement('span')
  ref.className = 'hs-mc-feed-reply-ref'
  const rawId = thread.op?.base36_id || thread.id || ''
  const displayId = String(rawId).replace(/^0+/, '') || '0'
  ref.textContent = ` replying to >>${displayId}`
  chip.appendChild(ref)

  const cancel = document.createElement('button')
  cancel.className = 'hs-mc-feed-reply-cancel'
  cancel.textContent = '✕'
  cancel.title = 'leave thread'
  cancel.addEventListener('click', (e) => {
    e.preventDefault()
    closeThread()
  })
  chip.appendChild(cancel)

  bar.insertBefore(chip, bar.firstChild)
}

function _clearFeedReplyChip() {
  document.getElementById('hs-mc-feed-reply-chip')?.remove()
}

function toggleThread(msgId, highlightId) {
  if (activeThread && activeThread.id === msgId && !highlightId) {
    closeThread()
  } else {
    openThread(msgId, highlightId)
  }
}

// Render the thread view (OP + replies + back button)
function renderThreadView(msgsEl) {
  const at = activeThread
  isProgrammaticScroll = true
  msgsEl.textContent = ''
  const frag = document.createDocumentFragment()
  let zebraCount = 0

  if (at.op) {
    const opDiv = buildFeedMessageDiv(at.op, at.op?.username)
    opDiv.classList.add('hs-thread-op')
    if (zebraEnabled && ++zebraCount % 2 === 0) opDiv.classList.add('hs-mc-zebra')
    frag.appendChild(opDiv)
  }

  const container = document.createElement('div')
  container.className = 'hs-thread-container'
  container.dataset.thread = at.id

  if (at.loading) {
    const loading = document.createElement('div')
    loading.className = 'hs-mc-empty'
    loading.textContent = 'loading...'
    loading.style.fontSize = '11px'
    container.appendChild(loading)
  } else if (at.replies.length === 0) {
    const empty = document.createElement('div')
    empty.className = 'hs-mc-empty'
    empty.textContent = t('mc_social_no_replies')
    empty.style.fontSize = '11px'
    container.appendChild(empty)
  } else {
    for (const r of at.replies) {
      const replyDiv = buildFeedMessageDiv(r, at.op?.username)
      replyDiv.classList.add('hs-thread-reply')
      if (r.is_thread_op) replyDiv.classList.add('is-thread-op')
      if (zebraEnabled && ++zebraCount % 2 === 0) replyDiv.classList.add('hs-mc-zebra')
      container.appendChild(replyDiv)
    }
  }
  frag.appendChild(container)
  msgsEl.appendChild(frag)

  isProgrammaticScroll = true
  msgsEl.scrollTop = 0
  requestAnimationFrame(() => {
    isProgrammaticScroll = false
  })

  if (typeof resolvePendingFeedEmbeds === 'function') resolvePendingFeedEmbeds(msgsEl)
}

// Plain-text dump of the current thread view (OP + all replies). Used by the
// universal right-click menu's "copy thread" item. Walks rendered DOM so
// emote <img alt> + already-escaped content come out as a user would read them.
function getActiveThreadCopyText() {
  const opDiv = document.querySelector('.hs-thread-op')
  if (!opDiv) return null
  const container = document.querySelector('.hs-thread-container')
  const rows = [opDiv, ...(container ? container.querySelectorAll(':scope > .hs-thread-reply') : [])]
  const lines = []
  for (const div of rows) {
    const tag = div.querySelector('.hs-feed-tag')?.textContent?.trim() || ''
    const userEl = div.querySelector('.hs-feed-user')
    const user = userEl?.textContent?.trim() || 'anonymous'
    const id = div.dataset?.msgId ? ` >>${div.dataset.msgId.replace(/^0+/, '') || '0'}` : ''
    const body = _extractFeedBodyText(div.querySelector('.hs-feed-body'))
    lines.push(`${tag ? tag + ' ' : ''}${user}${id}: ${body}`)
  }
  return lines.join('\n')
}

function _extractFeedBodyText(root) {
  if (!root) return ''
  const parts = []
  const walk = (node) => {
    if (node.nodeType === 3) {
      parts.push(node.textContent)
      return
    }
    if (node.nodeType !== 1) return
    if (node.classList?.contains('hs-feed-edited')) return
    if (node.tagName === 'BR') {
      parts.push('\n')
      return
    }
    if (node.tagName === 'IMG' && node.alt) {
      parts.push(node.alt)
      return
    }
    for (const c of node.childNodes) walk(c)
  }
  for (const c of root.childNodes) walk(c)
  return parts
    .join('')
    .replace(/[ \t]+/g, ' ')
    .replace(/ ?\n ?/g, '\n')
    .trim()
}

async function postFeedMessage(text, { topLevel = false } = {}) {
  const input = document.getElementById('hs-mc-input')
  if (!input) return false

  if (!hsAuthToken) {
    if (wysiwygEnabled) {
      input.dataset.placeholder = t('mc_social_login_first')
    } else {
      input.placeholder = t('mc_social_login_first')
    }
    cleanup.setTimeout(() => updateInputPlaceholder(), 2000)
    return false
  }

  // Extract pasted/uploaded media URL from content. The chat-tile flow
  // inserts /uploads/<file> as text into the input; the home-feed renderer
  // expects media_url as a separate field. Pull the first match out so it
  // renders as inline media on heatsync.org.
  let mediaUrl = null
  let mediaType = null
  const mediaMatch = text.match(
    /(?:https?:\/\/[^\s]*)?\/uploads\/([\w.-]+\.(jpg|jpeg|png|gif|webp|avif|mp4|webm|mov))(?:\?[^\s]*)?/i,
  )
  if (mediaMatch) {
    mediaUrl = mediaMatch[0].startsWith('/') ? mediaMatch[0] : new URL(mediaMatch[0]).pathname
    const ext = mediaMatch[2].toLowerCase()
    mediaType = /^(mp4|webm|mov)$/.test(ext) ? 'video' : 'image'
    text = text.replace(mediaMatch[0], '').replace(/\s+/g, ' ').trim()
  }

  const body = { content: text }
  if (mediaUrl) {
    body.media_url = mediaUrl
    body.media_type = mediaType
  }
  // In thread view, global input posts as a reply to the active thread
  if (activeThread) {
    body.reply_to = activeThread.id
  }

  const resp = await apiFetch('/api/messages', { method: 'POST', auth: true, body })
  if (resp.ok) {
    if (wysiwygEnabled) {
      input.innerHTML = ''
    } else {
      input.value = ''
    }
    pendingMessage = ''
    updateCharCount()
    hideInputBar()
    // Insert own post immediately from response (fetchFeed unreliable — service worker gets killed)
    const posted = resp.data?.message
    if (posted) {
      // OPs only in the following timeline — a reply posted from thread view
      // still lands in its thread (below), but must not leak into the feed.
      if (isOpMsg(posted) && !feedMessages.some((f) => f.base36_id === posted.base36_id)) {
        feedMessages.unshift(posted)
        if (feedMessages.length > 150) feedMessages.pop()
      }
      // If in thread view, append reply to the thread
      if (activeThread && activeThread.id === posted.reply_to) {
        if (!activeThread.replies.some((r) => r.base36_id === posted.base36_id)) {
          activeThread.replies.push(posted)
        }
        // Update OP reply count
        if (activeThread.op) activeThread.op.reply_count = (activeThread.op.reply_count || 0) + 1
        const parent = feedMessages.find((m) => m.base36_id === activeThread.id)
        if (parent) parent.reply_count = (parent.reply_count || 0) + 1
      }
    }
    if (currentTab === 'feed') renderFeed()
    return true
  } else {
    input.style.borderColor = '#f44'
    const errMsg =
      resp.status === 401
        ? t('mc_social_log_in_first')
        : resp.status === 429
          ? t('mc_social_slow_down')
          : resp.status === 409
            ? t('mc_social_duplicate')
            : t('mc_social_failed_post')
    showToast(errMsg, 'error')
    cleanup.setTimeout(() => {
      input.style.borderColor = ''
    }, 1500)
    log('Post failed:', resp.status || resp.error)
    return false
  }
}

// ============================================
// DISCOVER TAB (trending tags + profiles)
// ============================================

let discoverLoaded = false
let discoverLoading = false
let discoverPollTimer = null
function startDiscoverPolling() {
  if (discoverPollTimer) return
  // Auto-refresh while user is viewing the discover tab
  discoverPollTimer = cleanup.setIntervalIfVisible(() => {
    if (currentTab === 'discover' && !discoverLoading) {
      discoverLoaded = false
      fetchDiscover()
    } else if (currentTab !== 'discover') {
      cleanup.clearInterval(discoverPollTimer)
      discoverPollTimer = null
    }
  }, 20000)
}
let discoverTags = []
let discoverProfiles = []
let discoverPosts = []
let discoverPlatformFilter = 'all' // 'all' | 't' | 'k' | 'yt'

function _discoverSetLoading(msgsEl) {
  msgsEl.textContent = ''
  const el = document.createElement('div')
  el.className = 'hs-mc-empty'
  el.textContent = 'loading...'
  msgsEl.appendChild(el)
}

async function fetchDiscover() {
  if (discoverLoading) return
  discoverLoading = true

  const msgsEl = document.getElementById('hs-mc-messages')
  if (msgsEl && currentTab === 'discover') _discoverSetLoading(msgsEl)

  // Snapshot the tab user was on when fetch started — if they switched away and
  // back during the await, the .finally still re-renders correctly. If they
  // switched away and stayed, render is skipped (no clobbering other tab DOM).
  const tabAtFetch = currentTab
  try {
    const [tagsResp, profilesResp, postsResp] = await Promise.all([
      apiFetch('/api/tags/trending'),
      apiFetch('/api/profiles/trending'),
      apiFetch('/api/messages?sort=time&limit=40').catch(() => null),
    ])

    // Server shape: { tags: [...] } and { profiles: [...] }.
    // api_fetch proxy wraps as { ok: true, data: {...} }, so unwrap one more level.
    const tagsData = tagsResp.ok ? tagsResp.data || tagsResp : {}
    const profilesData = profilesResp.ok ? profilesResp.data || profilesResp : {}
    discoverTags = Array.isArray(tagsData) ? tagsData : tagsData.tags || []
    discoverProfiles = Array.isArray(profilesData) ? profilesData : profilesData.profiles || []

    // Posts: pull recent feed, client-sort by heat, take top by heat>0
    const rawPosts = postsResp?.ok ? postsResp.data?.messages || [] : []
    discoverPosts = rawPosts
      .filter((m) => m && m.username && m.username !== 'Anonymous' && (m.heat || 0) > 0)
      .sort((a, b) => (b.heat || 0) - (a.heat || 0))
      .slice(0, 8)

    discoverLoaded = true
  } catch (e) {
    discoverTags = []
    discoverProfiles = []
    discoverPosts = []
    discoverLoaded = true
  } finally {
    discoverLoading = false
    if (currentTab === 'discover') renderDiscoverTab()
    void tabAtFetch
  }
}

// Compact number: 12345 -> "12.3k", 1200000 -> "1.2m"
function formatDiscoverCount(n) {
  if (n >= 1_000_000) return (n / 1_000_000).toFixed(1).replace(/\.0$/, '') + 'm'
  if (n >= 1_000) return (n / 1_000).toFixed(1).replace(/\.0$/, '') + 'k'
  return String(n)
}

// Compact heat tier styling — matches site canonical color tiers from getHeatNumberStyle,
// but with fixed (small) size so discover rows stay dense.
// Tiers: 0 → #444, 1-10 → #888, 10-30 → #888, 30-50 → #cc6600, 50-100 → #ff8700,
//        100-500 → #ffaa33, 500+ → #fff with breathe animation
function discoverHeatStyle(heat) {
  let color = '#444',
    textShadow = '',
    animation = ''
  if (heat > 500) {
    color = '#fff'
    textShadow = '0 0 4px rgba(255,255,255,1),0 0 10px rgba(255,200,100,0.9),0 0 18px rgba(255,135,0,0.6)'
    animation = 'hs-heat-breathe 2s ease-in-out infinite'
  } else if (heat > 100) {
    color = '#ffaa33'
    textShadow = '0 0 4px rgba(255,170,50,0.85),0 0 10px rgba(255,135,0,0.4)'
  } else if (heat > 50) {
    color = '#ff8700'
    textShadow = '0 0 3px rgba(255,135,0,0.55)'
  } else if (heat > 30) {
    color = '#cc6600'
  } else if (heat > 10) {
    color = '#888'
  }
  let style = `color:${color};font-weight:900;font-variant-numeric:tabular-nums;`
  if (textShadow) style += `text-shadow:${textShadow};`
  if (animation) style += `animation:${animation};`
  return style
}

// Apply canonical row-level heat effects (border, bg tint, breathe class)
function applyDiscoverHeatRowEffects(row, heat) {
  const hd = getHeatDisplay(heat)
  if (!hd) return
  row.style.borderLeftColor = hd.border
  row.style.borderLeftWidth = hd.borderWidth + 'px'
  if (hd.bg) row.style.background = hd.bg
  if (hd.breathe) row.classList.add('hs-feed-heat-breathe')
}

// Canonical heat number — formatHeat + ° suffix at ≥ 10 + tier color/glow/breathe inline style.
// The number and degree symbol render in separate sub-spans (.hs-heat-n and
// .hs-heat-deg) so surfaces using a bitmap font can keep the digits crisp
// while letting the ° fall back to a vector font that has a clean glyph.
function heatSpanHtml(heat) {
  const h = Number(heat) || 0
  if (h <= 0) return ''
  const style = discoverHeatStyle(h)
  const suffix = h >= 10 ? '<span class="hs-heat-deg">°</span>' : ''
  return `<span class="hs-heat-num" style="${style}"><span class="hs-heat-n">${formatHeat(h)}</span>${suffix}</span>`
}

// Same, returned as a DOM node for createElement callers.
function heatSpanEl(heat) {
  const h = Number(heat) || 0
  if (h <= 0) return null
  const span = document.createElement('span')
  span.className = 'hs-heat-num'
  span.setAttribute('style', discoverHeatStyle(h))
  const numSpan = document.createElement('span')
  numSpan.className = 'hs-heat-n'
  numSpan.textContent = formatHeat(h)
  span.appendChild(numSpan)
  if (h >= 10) {
    const deg = document.createElement('span')
    deg.className = 'hs-heat-deg'
    deg.textContent = '°'
    span.appendChild(deg)
  }
  return span
}

function renderDiscoverProfileRow(profile, username, rank, maxHeat, showRank = true) {
  const row = document.createElement('a')
  row.className = 'hs-discover-profile-row'
  row.href = `https://heatsync.org/user/${encodeURIComponent(username)}`
  row.target = '_blank'
  row.rel = 'noopener noreferrer'

  const isLive = !!(profile.twitch_is_live || profile.kick_is_live)
  if (isLive) row.classList.add('hs-discover-row-live')

  if (showRank) {
    const rankEl = document.createElement('span')
    rankEl.className = 'hs-discover-rank'
    rankEl.textContent = String(rank).padStart(2, '0')
    row.appendChild(rankEl)
  }

  const dot = document.createElement('span')
  dot.className = isLive ? 'hs-discover-live-dot' : 'hs-discover-live-spacer'
  if (isLive) {
    const v = (profile.twitch_viewer_count || 0) + (profile.kick_viewer_count || 0)
    dot.title = v > 0 ? `live · ${v.toLocaleString()} viewer${v === 1 ? '' : 's'}` : 'live'
  }
  row.appendChild(dot)

  const avatarUrl = safeUrl(
    profile.avatarUrl || profile.avatar_url || profile.twitch_profile_pic || profile.kick_profile_pic || '',
  )
  if (avatarUrl) {
    const img = document.createElement('img')
    img.className = 'hs-discover-avatar'
    img.src = avatarUrl
    img.alt = ''
    img.loading = 'lazy'
    img.onerror = function () {
      this.style.visibility = 'hidden'
    }
    row.appendChild(img)
  } else {
    const ph = document.createElement('span')
    ph.className = 'hs-discover-avatar hs-discover-avatar-empty'
    row.appendChild(ph)
  }

  const nameEl = document.createElement('span')
  nameEl.className = 'hs-discover-profile-name'
  nameEl.style.color = sanitizeColor(profile.userColor || profile.user_color || '#fff')
  nameEl.textContent = profile.displayName || profile.display_name || username
  row.appendChild(nameEl)

  const plats = document.createElement('span')
  plats.className = 'hs-discover-platforms'
  if (profile.twitch_username) {
    const t = document.createElement('a')
    t.className = 'hs-plat hs-plat-t'
    t.textContent = 't'
    t.href = `https://www.twitch.tv/${encodeURIComponent(profile.twitch_username)}`
    t.target = '_blank'
    t.rel = 'noopener noreferrer'
    t.title = `twitch · @${profile.twitch_username}${profile.twitch_is_live ? ' · live' : ''}`
    if (profile.twitch_is_live) t.classList.add('hs-plat-live')
    t.addEventListener('click', (e) => e.stopPropagation())
    plats.appendChild(t)
  }
  if (profile.kick_username) {
    const k = document.createElement('a')
    k.className = 'hs-plat hs-plat-k'
    k.textContent = 'k'
    k.href = `https://kick.com/${encodeURIComponent(profile.kick_username)}`
    k.target = '_blank'
    k.rel = 'noopener noreferrer'
    k.title = `kick · @${profile.kick_username}${profile.kick_is_live ? ' · live' : ''}`
    if (profile.kick_is_live) k.classList.add('hs-plat-live')
    k.addEventListener('click', (e) => e.stopPropagation())
    plats.appendChild(k)
  }
  if (plats.childNodes.length) row.appendChild(plats)

  const heat = Number(profile.stats?.total_heat ?? profile.heat ?? 0)
  const bar = document.createElement('span')
  bar.className = 'hs-discover-bar'
  const fill = document.createElement('i')
  const pct = maxHeat > 0 ? Math.max(2, Math.round((heat / maxHeat) * 100)) : 2
  fill.style.width = pct + '%'
  bar.appendChild(fill)
  row.appendChild(bar)

  // Canonical heat number — matches website / feed posts (formatHeat + ° suffix, tiered glow).
  // Digits and ° are split into sub-spans so bitmap-font surfaces can render digits crisp
  // while keeping the degree symbol on a vector font with a clean glyph.
  const heatEl = document.createElement('span')
  heatEl.className = 'hs-discover-heat'
  heatEl.title = `${heat.toLocaleString()} heat`
  heatEl.setAttribute('style', discoverHeatStyle(heat))
  const numSpan = document.createElement('span')
  numSpan.className = 'hs-heat-n'
  numSpan.textContent = formatHeat(heat)
  heatEl.appendChild(numSpan)
  if (heat >= 10) {
    const deg = document.createElement('span')
    deg.className = 'hs-heat-deg'
    deg.textContent = '°'
    heatEl.appendChild(deg)
  }
  row.appendChild(heatEl)

  // Apply row-level heat tier effects ONLY when not live (live row has red border)
  if (!isLive) applyDiscoverHeatRowEffects(row, heat)

  if (isLive) {
    const v = (profile.twitch_viewer_count || 0) + (profile.kick_viewer_count || 0)
    if (v > 0) {
      const vEl = document.createElement('span')
      vEl.className = 'hs-discover-viewers'
      vEl.textContent = formatDiscoverCount(v)
      vEl.title = `${v.toLocaleString()} viewers`
      row.appendChild(vEl)
    }
  }

  return row
}

// Platform filter bar — click rerenders
function renderDiscoverChipsBar() {
  const bar = document.createElement('div')
  bar.className = 'hs-discover-chips-bar'

  function makeChip(label, value, currentValue, setter, extraClass) {
    const btn = document.createElement('button')
    btn.type = 'button'
    btn.className = 'hs-discover-chip-btn' + (extraClass ? ' ' + extraClass : '')
    if (value === currentValue) btn.classList.add('hs-active')
    btn.textContent = label
    btn.addEventListener('click', (e) => {
      e.stopPropagation()
      setter(value)
      renderDiscoverTab()
    })
    return btn
  }

  function makeLabel(text) {
    const l = document.createElement('span')
    l.className = 'hs-discover-chips-label'
    l.textContent = text
    return l
  }

  bar.appendChild(makeLabel('platform'))
  bar.appendChild(
    makeChip('all', 'all', discoverPlatformFilter, (v) => {
      discoverPlatformFilter = v
    }),
  )
  bar.appendChild(
    makeChip(
      't',
      't',
      discoverPlatformFilter,
      (v) => {
        discoverPlatformFilter = v
      },
      'hs-chip-plat-t',
    ),
  )
  bar.appendChild(
    makeChip(
      'k',
      'k',
      discoverPlatformFilter,
      (v) => {
        discoverPlatformFilter = v
      },
      'hs-chip-plat-k',
    ),
  )
  bar.appendChild(
    makeChip(
      'yt',
      'yt',
      discoverPlatformFilter,
      (v) => {
        discoverPlatformFilter = v
      },
      'hs-chip-plat-yt',
    ),
  )
  return bar
}

function profileMatchesPlatformFilter(p) {
  if (discoverPlatformFilter === 'all') return true
  if (discoverPlatformFilter === 't') return !!p.twitch_username
  if (discoverPlatformFilter === 'k') return !!p.kick_username
  if (discoverPlatformFilter === 'yt') return !!(p.youtube_username || p.youtube_channel_id)
  return true
}

function postMatchesPlatformFilter(m) {
  if (discoverPlatformFilter === 'all') return true
  if (discoverPlatformFilter === 't') return m.platform === 'twitch'
  if (discoverPlatformFilter === 'k') return m.platform === 'kick'
  if (discoverPlatformFilter === 'yt') return m.platform === 'youtube'
  return true
}

function sortProfilesByHeat(a, b) {
  return (b.stats?.total_heat || 0) - (a.stats?.total_heat || 0)
}

function renderDiscoverPostRow(m) {
  const row = document.createElement('a')
  row.className = 'hs-discover-post-row'
  row.href = `https://heatsync.org/m/${encodeURIComponent(m.base36_id)}`
  row.target = '_blank'
  row.rel = 'noopener noreferrer'

  // Meta line: time · plat · user · spacer · heat · replies
  const meta = document.createElement('div')
  meta.className = 'hs-discover-post-meta'

  const time = document.createElement('span')
  time.className = 'hs-discover-post-time'
  time.textContent = formatRelativeTime(m.created_at)
  time.title = new Date(m.created_at).toLocaleString()
  meta.appendChild(time)

  if (m.platform) {
    const plat = document.createElement('span')
    const code = m.platform === 'twitch' ? 't' : m.platform === 'kick' ? 'k' : m.platform === 'youtube' ? 'yt' : 'h'
    plat.className = `hs-plat hs-plat-${code} hs-discover-post-plat`
    plat.textContent = code
    meta.appendChild(plat)
  }

  const user = document.createElement('span')
  user.className = 'hs-discover-post-user'
  user.style.color = sanitizeColor(m.user_color || '#fff')
  user.textContent = m.username
  meta.appendChild(user)

  const spacer = document.createElement('span')
  spacer.className = 'hs-discover-post-spacer'
  meta.appendChild(spacer)

  const heat = Number(m.heat || 0)
  const heatEl = document.createElement('span')
  heatEl.className = 'hs-discover-heat hs-discover-post-heat'
  heatEl.title = `${heat.toLocaleString()} heat`
  heatEl.setAttribute('style', discoverHeatStyle(heat))
  const numSpan = document.createElement('span')
  numSpan.className = 'hs-heat-n'
  numSpan.textContent = formatHeat(heat)
  heatEl.appendChild(numSpan)
  if (heat >= 10) {
    const deg = document.createElement('span')
    deg.className = 'hs-heat-deg'
    deg.textContent = '°'
    heatEl.appendChild(deg)
  }
  meta.appendChild(heatEl)

  if ((m.reply_count || 0) > 0) {
    const rep = document.createElement('span')
    rep.className = 'hs-discover-post-replies'
    rep.title = `${m.reply_count} repl${m.reply_count === 1 ? 'y' : 'ies'}`
    rep.textContent = `${m.reply_count}r`
    meta.appendChild(rep)
  }

  row.appendChild(meta)

  // Content line: post body, full width, max 2 lines via line-clamp
  const txt = document.createElement('div')
  txt.className = 'hs-discover-post-text'
  const snippet = String(m.content || '')
    .replace(/\s+/g, ' ')
    .trim()
  txt.textContent = snippet || '(no text)'
  row.appendChild(txt)

  // Canonical row-level heat tier effects (border tier, bg, breathe at 500+)
  applyDiscoverHeatRowEffects(row, heat)

  return row
}

function makeDiscoverSection(titleText, subtitleText, metaText, extraClass) {
  const section = document.createElement('section')
  section.className = 'hs-discover-section' + (extraClass ? ' ' + extraClass : '')
  const heading = document.createElement('div')
  heading.className = 'hs-discover-heading'

  const titleWrap = document.createElement('span')
  titleWrap.className = 'hs-discover-heading-title'
  titleWrap.textContent = titleText
  heading.appendChild(titleWrap)

  if (metaText) {
    const meta = document.createElement('span')
    meta.className = 'hs-discover-meta'
    meta.textContent = metaText
    heading.appendChild(meta)
  }
  section.appendChild(heading)

  if (subtitleText) {
    const sub = document.createElement('div')
    sub.className = 'hs-discover-subtitle'
    sub.textContent = subtitleText
    section.appendChild(sub)
  }

  const body = document.createElement('div')
  body.className = 'hs-discover-section-body'
  section.appendChild(body)
  return { section, body }
}

function renderDiscoverTab() {
  if (typeof activeProfileCard !== 'undefined' && activeProfileCard) return
  const msgsEl = document.getElementById('hs-mc-messages')
  if (!msgsEl) return

  startDiscoverPolling()

  if (!discoverLoaded && !discoverLoading) {
    fetchDiscover()
    return
  }
  if (discoverLoading) {
    _discoverSetLoading(msgsEl)
    return
  }

  msgsEl.textContent = ''

  // Container query root — gives us responsive layout based on panel width, not viewport
  const root = document.createElement('div')
  root.className = 'hs-discover-root'

  const filteredProfiles = discoverProfiles.filter(profileMatchesPlatformFilter)
  const filteredPosts = discoverPosts.filter(postMatchesPlatformFilter)

  const liveProfiles = filteredProfiles
    .filter((p) => p.twitch_is_live || p.kick_is_live)
    .sort((a, b) => {
      const av = (a.twitch_viewer_count || 0) + (a.kick_viewer_count || 0)
      const bv = (b.twitch_viewer_count || 0) + (b.kick_viewer_count || 0)
      if (av !== bv) return bv - av
      return (b.stats?.total_heat || 0) - (a.stats?.total_heat || 0)
    })
  const restProfiles = filteredProfiles.filter((p) => !p.twitch_is_live && !p.kick_is_live).sort(sortProfilesByHeat)
  const maxHeat = Math.max(...filteredProfiles.map((p) => p.stats?.total_heat ?? p.heat ?? 0), 1)

  // Filter chips
  root.appendChild(renderDiscoverChipsBar())

  // Top row — LIVE NOW + HOT POSTS side by side when wide
  const topRow = document.createElement('div')
  topRow.className = 'hs-discover-row1'

  // ● LIVE NOW
  {
    const { section, body } = makeDiscoverSection(
      'live now',
      null,
      liveProfiles.length > 0 ? `${liveProfiles.length}` : '0',
      'hs-discover-section-live',
    )
    if (liveProfiles.length === 0) {
      const empty = document.createElement('div')
      empty.className = 'hs-discover-section-empty'
      empty.textContent = 'no streams live right now'
      body.appendChild(empty)
      // Contextual nudge — if the user follows few/no people on heatsync, the
      // section will always look empty. Surface twitch import right at the
      // point of pain. safeSendMessage→get_followed_users to gate the prompt.
      try {
        chrome.runtime
          .sendMessage({ type: 'get_followed_users' })
          .then((resp) => {
            if ((resp?.users?.length || 0) >= 5) return
            if (!body.isConnected) return
            const nudge = document.createElement('div')
            nudge.className = 'hs-discover-section-empty hs-discover-import-nudge'
            const a = document.createElement('a')
            a.href = '#'
            a.textContent = 'import follows from twitch'
            a.style.color = '#ff8700'
            a.style.textDecoration = 'none'
            a.addEventListener('click', async (e) => {
              e.preventDefault()
              a.textContent = 'syncing…'
              try {
                const r = await apiFetch('/api/sync-twitch-follows', { method: 'POST', auth: true })
                if (r?.ok && r?.data?.success) {
                  a.textContent = `synced ${r.data.synced} ✓`
                  try {
                    chrome.runtime.sendMessage({ type: 'refresh_followed_users' })
                  } catch {}
                  cleanup.setTimeout(() => renderDiscoverTab(), 1500)
                } else {
                  a.textContent = (r?.error || r?.data?.error || 'failed').slice(0, 30)
                }
              } catch (err) {
                a.textContent = 'failed'
              }
            })
            nudge.appendChild(a)
            body.appendChild(nudge)
          })
          .catch(() => {})
      } catch {}
    } else {
      for (const profile of liveProfiles) {
        const username = profile.username || profile.name || ''
        if (!username) continue
        const row = renderDiscoverProfileRow(profile, username, 0, maxHeat, false)
        if (row) body.appendChild(row)
      }
    }
    topRow.appendChild(section)
  }

  // HOT POSTS
  {
    const { section, body } = makeDiscoverSection('hot posts', null, null, 'hs-discover-section-posts')
    if (filteredPosts.length === 0) {
      const empty = document.createElement('div')
      empty.className = 'hs-discover-section-empty'
      empty.textContent = 'no posts match filter'
      body.appendChild(empty)
    } else {
      for (const m of filteredPosts) {
        const row = renderDiscoverPostRow(m)
        if (row) body.appendChild(row)
      }
    }
    topRow.appendChild(section)
  }

  root.appendChild(topRow)

  // TAGS — always render, above the long leaderboard
  {
    const { section, body } = makeDiscoverSection('tags', null, null, 'hs-discover-section-tags')
    if (discoverTags.length === 0) {
      const empty = document.createElement('div')
      empty.className = 'hs-discover-section-empty'
      empty.textContent = 'none right now'
      body.appendChild(empty)
    } else {
      const chips = document.createElement('div')
      chips.className = 'hs-discover-chips'
      for (const tag of discoverTags) {
        const name = typeof tag === 'string' ? tag : tag.name || tag.tag || ''
        if (!name) continue
        const chip = document.createElement('a')
        chip.className = 'hs-discover-chip'
        chip.href = `https://heatsync.org/tags/${encodeURIComponent(name)}`
        chip.target = '_blank'
        chip.rel = 'noopener noreferrer'
        chip.textContent = name
        const count = typeof tag === 'object' ? tag.count || tag.usage || 0 : 0
        if (count > 0) {
          const c = document.createElement('span')
          c.className = 'hs-discover-chip-count'
          c.textContent = formatDiscoverCount(count)
          chip.appendChild(c)
        }
        chips.appendChild(chip)
      }
      body.appendChild(chips)
    }
    root.appendChild(section)
  }

  // LEADERBOARD — non-live profiles, multi-column when wide
  {
    const { section, body } = makeDiscoverSection('leaderboard', null, null, 'hs-discover-section-trending')
    body.classList.add('hs-discover-leaderboard-body')
    if (restProfiles.length === 0) {
      const empty = document.createElement('div')
      empty.className = 'hs-discover-section-empty'
      empty.textContent = 'no profiles match this filter'
      body.appendChild(empty)
    } else {
      let rank = 1
      for (const profile of restProfiles) {
        const username = profile.username || profile.name || ''
        if (!username) continue
        const row = renderDiscoverProfileRow(profile, username, rank++, maxHeat)
        if (row) body.appendChild(row)
      }
    }
    root.appendChild(section)
  }

  msgsEl.appendChild(root)
}

// Pinned messages tab
let pinnedLoaded = false
let pinnedLoading = false
let pinnedPollTimer = null
function startPinnedPolling() {
  if (pinnedPollTimer) return
  pinnedPollTimer = cleanup.setIntervalIfVisible(() => {
    if (currentTab === 'pinned' && !pinnedLoading) {
      pinnedLoaded = false
      fetchPinned()
    } else if (currentTab !== 'pinned') {
      cleanup.clearInterval(pinnedPollTimer)
      pinnedPollTimer = null
    }
  }, 20000)
}
let pinnedMessages = []

function _pinnedSetLoading(msgsEl) {
  msgsEl.textContent = ''
  const el = document.createElement('div')
  el.className = 'hs-mc-empty'
  el.textContent = 'loading...'
  msgsEl.appendChild(el)
}

async function fetchPinned() {
  if (pinnedLoading) return
  pinnedLoading = true

  const msgsEl = document.getElementById('hs-mc-messages')
  if (msgsEl && currentTab === 'pinned') _pinnedSetLoading(msgsEl)

  try {
    const resp = await apiFetch('/api/messages/pinned')
    // Server returns { messages: [...] }; api_fetch proxy wraps as { ok, data: { messages } }
    const data = resp.ok ? resp.data || resp : {}
    pinnedMessages = Array.isArray(data) ? data : data.messages || []
    pinnedLoaded = true
  } catch (e) {
    pinnedMessages = []
    pinnedLoaded = true
  } finally {
    pinnedLoading = false
    if (currentTab === 'pinned') renderPinnedTab()
  }
}

function renderPinnedTab() {
  if (typeof activeProfileCard !== 'undefined' && activeProfileCard) return
  const msgsEl = document.getElementById('hs-mc-messages')
  if (!msgsEl) return

  // Auto-refresh while viewing — no manual refresh button.
  startPinnedPolling()

  if (!pinnedLoaded && !pinnedLoading) {
    fetchPinned()
    return
  }
  if (pinnedLoading) {
    _pinnedSetLoading(msgsEl)
    return
  }

  msgsEl.textContent = ''
  const frag = document.createDocumentFragment()

  if (pinnedMessages.length === 0) {
    const empty = document.createElement('div')
    empty.className = 'hs-mc-empty'
    empty.textContent = 'no pinned messages'
    frag.appendChild(empty)
    msgsEl.appendChild(frag)
    return
  }

  for (const m of pinnedMessages) {
    const id = m.base36_id || m.id || ''
    const channel = escapeHtml(m.channel || '')
    const user = escapeHtml(m.user || m.username || m.display_name || '')
    const content = escapeHtml(m.content || m.text || '')
    const ts = m.ts || m.created_at || m.timestamp || ''
    const timeStr = ts ? escapeHtml(new Date(ts).toLocaleString()) : ''

    const row = document.createElement('a')
    row.className = 'hs-pinned-row'
    if (id) {
      const url = safeUrl(`https://heatsync.org/m/${encodeURIComponent(id)}`)
      if (url) {
        row.href = url
        row.target = '_blank'
        row.rel = 'noopener noreferrer'
      }
    }

    const meta = document.createElement('div')
    meta.className = 'hs-pinned-meta'
    if (channel) {
      const channelSpan = document.createElement('span')
      channelSpan.className = 'hs-pinned-channel'
      channelSpan.textContent = channel
      meta.appendChild(channelSpan)
    }
    if (user) {
      const userSpan = document.createElement('span')
      userSpan.className = 'hs-pinned-user'
      userSpan.textContent = user
      meta.appendChild(userSpan)
    }
    if (timeStr) {
      const timeSpan = document.createElement('span')
      timeSpan.className = 'hs-pinned-time'
      timeSpan.textContent = timeStr
      meta.appendChild(timeSpan)
    }
    row.appendChild(meta)

    const body = document.createElement('div')
    body.className = 'hs-pinned-body'
    appendTextWithHashtags(body, content)
    row.appendChild(body)

    frag.appendChild(row)
  }

  msgsEl.appendChild(frag)
}

// ============================================
// FEED POST-LINK HOVER PREVIEW
// ============================================

// Lookup a feed message from in-memory stores, then fall back to API.
// Returns the message object or null. Fetches are deduped by id within
// the lifetime of a single hover (callers pass a generation counter).
const _feedMsgFetchCache = new Map() // id -> Promise<msg|null>

function _feedMsgLookupMemory(id) {
  if (!id) return null
  const fromFeed = feedMessages.find((m) => m.base36_id === id)
  if (fromFeed) return fromFeed
  if (activeThread) {
    if (activeThread.op?.base36_id === id) return activeThread.op
    const fromThread = activeThread.replies?.find((r) => r.base36_id === id)
    if (fromThread) return fromThread
  }
  return null
}

async function _feedMsgFetch(id) {
  if (!id) return null
  const mem = _feedMsgLookupMemory(id)
  if (mem) return mem
  if (_feedMsgFetchCache.has(id)) return _feedMsgFetchCache.get(id)
  const p = apiFetch('/api/messages/' + encodeURIComponent(id))
    .then((r) => {
      // API returns the message directly in resp.data (not resp.data.message)
      if (!r.ok) return null
      const msg = r.data || null
      return msg && msg.base36_id ? msg : null
    })
    .catch(() => null)
  _feedMsgFetchCache.set(id, p)
  // Evict after 60s so stale data doesn't accumulate across sessions
  cleanup.setTimeout(() => _feedMsgFetchCache.delete(id), 60000)
  return p
}

async function _feedMsgFetchReplies(id) {
  if (!id) return []
  // Check activeThread first
  if (activeThread && activeThread.id === id && activeThread.replies?.length) {
    return activeThread.replies
  }
  const r = await apiFetch('/api/messages/' + encodeURIComponent(id) + '/replies')
  return r.ok ? r.data?.replies || [] : []
}

// Called once from feed init. Uses event delegation on document.body so it
// works for dynamically-rendered rows without re-wiring on each renderFeed().
function setupFeedPostLinkHover() {
  if (window._hsMcFeedPostLinkHoverSetup) return
  window._hsMcFeedPostLinkHoverSetup = true

  let _linkGen = 0
  let _currentLink = null
  const MAX_DEPTH = 50
  // Both inline >>id refs AND the leading thread-link (left of the OP) get the
  // same hover preview — a >>id is hoverable wherever it appears.
  const LINK_SEL = '.hs-post-link, .hs-feed-thread-link'

  const getOverlay = () => {
    let el = document.getElementById('hs-feed-postlink-preview')
    if (el) return el
    el = document.createElement('div')
    el.id = 'hs-feed-postlink-preview'
    document.body.appendChild(cleanup.trackNode(el))
    // Dismiss when cursor leaves the overlay itself
    el.addEventListener('mouseleave', (ev) => {
      // Only dismiss if not moving back into a post-link
      const to = ev.relatedTarget
      if (to && to.closest && to.closest(LINK_SEL)) return
      _hideOverlay()
    })
    return el
  }

  const _hideOverlay = () => {
    _currentLink = null
    const el = document.getElementById('hs-feed-postlink-preview')
    if (el) {
      el.style.display = 'none'
      el.replaceChildren()
    }
    _linkGen++
  }

  // Dismiss when #hs-mc-messages scrolls (capture phase catches it before msgsEl)
  document.addEventListener(
    'scroll',
    (ev) => {
      if (ev.target && ev.target.id === 'hs-mc-messages') _hideOverlay()
    },
    { passive: true, capture: true, signal: mcSignal },
  )

  document.body.addEventListener(
    'mouseover',
    (ev) => {
      const link = ev.target.closest && ev.target.closest(LINK_SEL)
      if (!link) return
      // Must be inside the feed panel
      if (!link.closest('#hs-mc-messages')) return
      if (link === _currentLink) return
      _currentLink = link

      const linkedId = link.dataset.id
      if (!linkedId) return

      const gen = ++_linkGen

      ;(async () => {
        // Always show on hover — even when the linked post is already on screen.
        // Matches the chat reply-stack and Twitch reply-thread hover (the user's
        // mental model): hovering >>id surfaces the thread context regardless of
        // visibility. (The site skips-if-visible; the cramped panel does not.)

        // Fetch the linked message
        const msg = await _feedMsgFetch(linkedId)
        if (_linkGen !== gen) return
        if (!msg) return

        // Walk ancestor chain (parents, above)
        const chain = [] // will be [oldest, ..., immediate-parent] after unshifts
        const seenUp = new Set([msg.base36_id || linkedId])
        let cur = msg
        while (chain.length < MAX_DEPTH && cur && cur.reply_to) {
          if (seenUp.has(cur.reply_to)) break
          seenUp.add(cur.reply_to)
          const parent = await _feedMsgFetch(cur.reply_to)
          if (_linkGen !== gen) return
          if (!parent) break
          chain.unshift(parent)
          cur = parent
        }

        // Walk first-child descendant chain (below)
        const descChain = []
        const seenDown = new Set([msg.base36_id || linkedId])
        let dCur = msg
        while (descChain.length < MAX_DEPTH) {
          if (_linkGen !== gen) return
          const parentId = dCur.base36_id
          if (!parentId) break
          // Check memory first (feedMessages + activeThread)
          let child = feedMessages.find((m) => m.reply_to === parentId) || null
          if (!child && activeThread?.replies) {
            child = activeThread.replies.find((r) => r.reply_to === parentId) || null
          }
          // Fall back to API replies
          if (!child) {
            const replies = await _feedMsgFetchReplies(parentId)
            if (_linkGen !== gen) return
            child = replies.length ? replies[0] : null
          }
          if (!child) break
          const childId = child.base36_id
          if (!childId || seenDown.has(childId)) break
          seenDown.add(childId)
          descChain.push(child)
          dCur = child
        }

        if (_linkGen !== gen) return

        // Build overlay
        const overlay = getOverlay()
        overlay.replaceChildren()
        overlay.style.display = 'block'

        // Render one row using buildFeedMessageDiv (handles sanitization + emotes)
        const renderRow = (m) => {
          const row = buildFeedMessageDiv(m)
          row.classList.add('hs-feed-postlink-preview-row')
          // Highlight the linked post itself
          if (m.base36_id === linkedId) row.classList.add('hs-feed-postlink-preview-linked')
          overlay.appendChild(row)
        }

        for (const ancestor of chain) renderRow(ancestor)
        renderRow(msg)
        for (const desc of descChain) renderRow(desc)

        // Position: bottom edge snug against link top, always-above, clamp to viewport
        const positionOverlay = () => {
          if (!overlay.parentNode) return
          const linkRect = link.getBoundingClientRect()
          const layoutH = document.documentElement.clientHeight
          const layoutW = document.documentElement.clientWidth

          // Bottom of overlay aligns to top of link
          const bottomFromBase = layoutH - linkRect.top
          overlay.style.bottom = bottomFromBase + 'px'
          overlay.style.top = ''

          // Max height: everything above the link (minus a small margin)
          const availableAbove = Math.max(0, linkRect.top - 4)
          overlay.style.maxHeight = availableAbove + 'px'

          // Horizontal: align left to link, clamp to viewport
          const overlayW = overlay.getBoundingClientRect().width
          let left = linkRect.left
          if (left + overlayW > layoutW - 4) left = layoutW - overlayW - 4
          if (left < 4) left = 4
          overlay.style.left = left + 'px'
        }

        // Wait for images before final positioning (emotes, avatars)
        const images = overlay.querySelectorAll('img')
        if (images.length > 0) {
          let pending = images.length
          const onLoad = () => {
            if (--pending <= 0) requestAnimationFrame(positionOverlay)
          }
          images.forEach((img) => {
            if (img.complete) {
              onLoad()
            } else {
              img.addEventListener('load', onLoad, { once: true })
              img.addEventListener('error', onLoad, { once: true })
            }
          })
          // Fallback: position after 120ms regardless
          cleanup.setTimeout(positionOverlay, 120)
        } else {
          requestAnimationFrame(() => requestAnimationFrame(positionOverlay))
        }
      })()
    },
    { signal: mcSignal },
  )

  document.body.addEventListener(
    'mouseout',
    (ev) => {
      const link = ev.target.closest && ev.target.closest(LINK_SEL)
      if (!link) return
      if (!link.closest('#hs-mc-messages')) return
      const to = ev.relatedTarget
      // Don't hide if moving into the overlay or another post-link
      const overlay = document.getElementById('hs-feed-postlink-preview')
      if (overlay && overlay.contains(to)) return
      if (to && to.closest && to.closest(LINK_SEL)) return
      _hideOverlay()
    },
    { signal: mcSignal },
  )
}


// --- multichat/whispers.js ---
// Whispers — unified chronological timeline of all whispers + DMs

const whisperTimeline = [] // { user, text, color, time, self, platform, key, status?, id? }
const whisperUsers = new Map() // key → { platform, userId, displayName, color }
const WHISPER_USERS_MAX = 200
const WHISPER_TIMELINE_MAX_READ = 500 // hard cap on READ messages
const WHISPER_TIMELINE_MAX_UNREAD = 500 // hard cap on UNREAD messages
// O(1) dedup. Composite key = id when present, else user|time|text-prefix so IRC↔EventSub
// dual delivery still collapses even when one side lacks an ID.
const _whisperSeen = new Set()
const _WHISPER_SEEN_MAX = 2000
// Hash full whisper text (djb2). 64-char-prefix dedup collided on long
// whispers sharing an intro — one of the two silently dropped, no unread
// badge for the dropped one. Full-text hash is stable, 32-bit, fits the key.
function _hashText(s) {
  let h = 5381
  for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) | 0
  return h
}
function _whisperDedupKey(platform, id, user, time, text) {
  if (id) return `${platform}:${id}`
  return `${platform}|${(user || '').toLowerCase()}|${time || 0}|${_hashText(text || '')}`
}
function _whisperMarkSeen(key) {
  if (_whisperSeen.has(key)) return true
  _whisperSeen.add(key)
  if (_whisperSeen.size > _WHISPER_SEEN_MAX) {
    // Drop the oldest insertion (Set preserves insertion order)
    const it = _whisperSeen.values().next()
    if (!it.done) _whisperSeen.delete(it.value)
  }
  return false
}

// Trim oldest READ messages once read-count exceeds cap, and oldest UNREAD
// messages once unread-count exceeds its own cap. Self-sent messages count
// as read (we wrote them).
function trimWhisperTimeline() {
  const lastViewed = seenAt.whispers
  // --- read eviction ---
  let readCount = 0
  for (const m of whisperTimeline) {
    if (m.self || m.time <= lastViewed) readCount++
  }
  let toRemove = readCount - WHISPER_TIMELINE_MAX_READ
  if (toRemove > 0) {
    for (let i = 0; i < whisperTimeline.length && toRemove > 0; ) {
      const m = whisperTimeline[i]
      if (m.self || m.time <= lastViewed) {
        whisperTimeline.splice(i, 1)
        toRemove--
      } else {
        i++
      }
    }
  }
  // --- unread eviction ---
  let unreadCount = 0
  for (const m of whisperTimeline) {
    if (!m.self && m.time > lastViewed) unreadCount++
  }
  let toRemoveUnread = unreadCount - WHISPER_TIMELINE_MAX_UNREAD
  if (toRemoveUnread <= 0) return
  for (let i = 0; i < whisperTimeline.length && toRemoveUnread > 0; ) {
    const m = whisperTimeline[i]
    if (!m.self && m.time > lastViewed) {
      whisperTimeline.splice(i, 1)
      toRemoveUnread--
    } else {
      i++
    }
  }
}
function whisperUsersSet(key, value) {
  whisperUsers.set(key, value)
  if (whisperUsers.size > WHISPER_USERS_MAX) {
    whisperUsers.delete(whisperUsers.keys().next().value)
  }
}
let lastWhisperKey = null // for /r — last person involved in a whisper
let whisperDmsLoaded = false
let selfWhisperColor = null // current user's Twitch color

// Resolve own color from IRC buffers, chat DOM, or Twitch cookie color
function resolveSelfColor() {
  if (selfWhisperColor) return
  const me = (currentUsername || '').toLowerCase()
  if (!me) return
  // Check IRC message buffers for our own messages (they contain our color)
  if (typeof irc !== 'undefined' && irc?.channels) {
    for (const [, buf] of irc.channels) {
      const msgs = buf.getAll ? buf.getAll() : []
      for (let i = msgs.length - 1; i >= 0; i--) {
        if (msgs[i].user?.toLowerCase() === me && msgs[i].color) {
          selfWhisperColor = msgs[i].color
          return
        }
      }
    }
  }
  // Check DOM for our username color
  try {
    const el = document.querySelector(`.chat-author__display-name[data-a-user="${me}"]`)
    if (el) {
      selfWhisperColor = el.style.color || getComputedStyle(el).color
      return
    }
  } catch (e) {
    warn('selfWhisperColor DOM probe failed:', e?.message)
  }
}

let _whisperSaveTimer = null
function whisperSaveDebounced() {
  if (_whisperSaveTimer) cleanup.clearTimeout(_whisperSaveTimer)
  _whisperSaveTimer = cleanup.setTimeout(saveWhispers, 500)
}

function saveWhispers() {
  const users = {}
  for (const [key, u] of whisperUsers) users[key] = u
  try {
    trimWhisperTimeline()
    chrome.storage.local
      .set({
        hs_whispers_v2: {
          timeline: whisperTimeline.slice(),
          users,
          lastKey: lastWhisperKey,
        },
      })
      .catch((e) => warn('whispers save failed:', e?.message))
  } catch (e) {
    warn('whispers save failed:', e?.message)
  }
}

function loadWhispers() {
  try {
    chrome.storage.local
      .get(['hs_whispers_v2', 'hs_whispers'])
      .then((stored) => {
        // Load v2 format (timeline)
        const data = stored.hs_whispers_v2
        if (data) {
          if (Array.isArray(data.timeline)) {
            for (const msg of data.timeline) {
              if (!whisperTimeline.some((m) => m.time === msg.time && m.text === msg.text)) {
                whisperTimeline.push(msg)
              }
            }
          }
          if (data.users) {
            for (const [key, u] of Object.entries(data.users)) {
              if (!whisperUsers.has(key)) whisperUsers.set(key, u)
            }
          }
          if (data.lastKey) lastWhisperKey = data.lastKey
        }

        // Migrate v1 format (per-conversation) into timeline
        const v1 = stored.hs_whispers
        if (v1 && typeof v1 === 'object' && !v1.timeline) {
          for (const [key, conv] of Object.entries(v1)) {
            if (!conv || !conv.msgs) continue
            whisperUsersSet(key, {
              platform: conv.platform || (key.startsWith('hs:') ? 'heatsync' : 'twitch'),
              userId: conv.userId,
              displayName: conv.displayName,
              color: conv.color || '#fff',
            })
            for (const m of conv.msgs) {
              if (whisperTimeline.some((e) => e.time === m.time && e.text === m.text)) continue
              whisperTimeline.push({
                user: m.self ? 'you' : m.user,
                text: m.text,
                color: m.color || '#fff',
                time: m.time,
                self: !!m.self,
                platform: conv.platform || (key.startsWith('hs:') ? 'heatsync' : 'twitch'),
                key,
              })
            }
          }
          whisperTimeline.sort((a, b) => a.time - b.time)
          trimWhisperTimeline()
          // Clean up v1
          try {
            chrome.storage.local.remove('hs_whispers')
          } catch {}
          whisperSaveDebounced()
        }

        // Re-derive latestAt from any unread on disk so red-dot survives boot.
        const newest = whisperTimeline.reduce((mx, m) => (!m.self && m.time > mx ? m.time : mx), 0)
        if (newest > 0) noteSeenEvent('whispers', newest)
        refreshSeenBadges()
      })
      .catch((e) => warn('whispers load (storage.get) failed:', e?.message))
  } catch (e) {
    warn('whispers load failed:', e?.message)
  }
}

function handleIncomingWhisper(msg) {
  // Blocked users can't reach you via Twitch whisper — no timeline entry, no
  // red-dot/badge, no popup. (These arrive straight from Twitch EventSub/IRC,
  // so there's no server-side gate like HeatSync DMs have.) Checked BEFORE the
  // dedup mark so unblocking mid-session lets a later re-delivery surface.
  if (typeof isUserBlocked === 'function' && isUserBlocked(msg.user, 'twitch')) return
  // O(1) dedup that also collapses dual IRC↔EventSub delivery when ID is missing
  if (_whisperMarkSeen(_whisperDedupKey('twitch', msg.id, msg.user, msg.time, msg.text))) return

  const key = `twitch:${msg.user.toLowerCase()}`
  whisperUsersSet(key, {
    platform: 'twitch',
    userId: msg.userId,
    displayName: msg.user,
    color: msg.color,
  })

  whisperTimeline.push({
    user: msg.user,
    text: msg.text,
    color: msg.color,
    time: msg.time,
    self: false,
    platform: 'twitch',
    key,
    id: msg.id || '',
  })
  trimWhisperTimeline()
  lastWhisperKey = key

  noteSeenEvent('whispers', msg.time || Date.now())
  if (currentTab === 'whispers') {
    bumpSeen('whispers')
    renderWhispersTab()
  } else {
    injectInlineNotif('dm', {
      type: 'inline-dm',
      user: msg.user,
      userId: msg.userId,
      text: msg.text,
      color: msg.color,
      time: msg.time,
      platform: 'twitch',
    })
  }
  whisperSaveDebounced()
}

function handleIncomingDm(data) {
  const time = data.created_at ? new Date(data.created_at).getTime() : Date.now()
  if (_whisperMarkSeen(_whisperDedupKey('heatsync', data.id, data.from_display_name, time, data.content))) return
  const key = `hs:${data.from_user_id}`
  whisperUsersSet(key, {
    platform: 'heatsync',
    userId: data.from_user_id,
    displayName: data.from_display_name,
    color: data.from_color || '#ff8700',
  })

  whisperTimeline.push({
    user: data.from_display_name,
    text: data.content,
    color: data.from_color || '#ff8700',
    time,
    self: false,
    platform: 'heatsync',
    key,
    id: data.id || '',
  })
  trimWhisperTimeline()
  lastWhisperKey = key

  noteSeenEvent('whispers', time)
  if (currentTab === 'whispers') {
    bumpSeen('whispers')
    renderWhispersTab()
  } else {
    injectInlineNotif('dm', {
      type: 'inline-dm',
      user: data.from_display_name,
      text: data.content,
      color: data.from_color || '#ff8700',
      time,
      platform: 'heatsync',
    })
  }
  whisperSaveDebounced()
}

// Direct whisper using the page's twitch.tv session. Sends from whichever
// Twitch acct is logged in on twitch.tv, independent of any HS JWT.
//
// Must ride Twitch's OWN Apollo client (MAIN-world apolloMutate). A direct
// gql.twitch.tv POST — even with a freshly-minted Client-Integrity JWT — gets
// rejected as "failed integrity check"; the token only validates when attached
// via Apollo's link chain (fingerprint + session correlation). The SendWhisper
// Document is loaded from Twitch's webpack by searchTerm. Mirrors _followMutation.
async function sendTwitchWhisperDirect(toUserId, message) {
  const { token } = await getTwitchAuthTokenAsync()
  if (!token) return { ok: false, noToken: true }
  const nonce = crypto?.randomUUID?.() || `${Date.now()}_${Math.random().toString(36).slice(2, 12)}`
  const variables = { input: { recipientUserID: String(toUserId), message: String(message), nonce } }
  const result = await apolloMutate({ searchTerm: 'SendWhisper', variables, resultField: 'sendWhisper' })
  if (result?.ok) return { ok: true }
  const errMsg = String(result?.error || 'whisper failed')
  return { ok: false, error: errMsg, integrity: /integrity/i.test(errMsg) }
}

// Whisper send: heatsync server proxy (Helix /helix/whispers with the user's
// stored Twitch OAuth + user:manage:whispers scope) is the primary path —
// ToS-clean and works from any origin since it doesn't need Client-Integrity.
//
// Direct GQL fallback only runs on twitch.tv pages where the MAIN-world proxy
// can mint a Client-Integrity JWT. Off twitch.tv (kick.com, youtube.com) the
// integrity service rejects mutations as "failed integrity check" no matter
// what, so the fallback is structurally dead and we short-circuit it to
// surface the real proxy error (usually "log in to heatsync" / "link twitch")
// instead of a misleading integrity message.
//
// On-twitch fallback still covers: (1) heatsync server unreachable, (2) the
// user's heatsync-linked Twitch account differs from the active twitch.tv
// session and they want to whisper-from the active session.
async function sendTwitchWhisper(toUserId, message) {
  const onTwitch = _isOnTwitchPage()

  let serverResp = null
  let serverThrew = false
  try {
    serverResp = await apiFetch('/api/twitch/whisper', {
      method: 'POST',
      body: { toUserId, message },
    })
    if (serverResp?.ok) return { ok: true }
  } catch (e) {
    serverThrew = true
  }

  const respStatus = Number(serverResp?.status) || 0
  const respError = String(serverResp?.error || '')
  const isAuthFail = respStatus === 401 && /no twitch token|not authenticated|re-login/i.test(respError)

  // Off twitch.tv: direct GQL can't get integrity, so don't pretend to retry.
  // Surface the real proxy error — actionable for the user.
  if (!onTwitch) {
    if (isAuthFail) {
      showToast(t('mc_whisper_login'), 'error')
      return { ok: false, error: 'log in to heatsync.org to send whispers', errorKind: 'auth' }
    }
    if (serverThrew || respStatus >= 500 || !serverResp) {
      const msg = 'heatsync server unreachable'
      showToast('whisper failed: ' + msg, 'error')
      return { ok: false, error: msg, errorKind: 'server' }
    }
    const errText = respError || `twitch error ${respStatus}`
    showToast('whisper failed: ' + errText, 'error')
    return { ok: false, error: errText }
  }

  // On twitch.tv: direct GQL fallback. Integrity mintable here.
  try {
    const direct = await sendTwitchWhisperDirect(toUserId, message)
    if (direct.ok) return { ok: true }
    if (direct.noToken) {
      showToast(t('mc_whisper_login'), 'error')
      return { ok: false, error: 'no twitch session', errorKind: 'auth' }
    }
    showToast('whisper failed: ' + (direct.error || 'unknown'), 'error')
    return { ok: false, error: direct.error || 'unknown' }
  } catch (e) {
    showToast('whisper failed: ' + e.message, 'error')
    return { ok: false, error: e.message }
  }
}

async function sendWhisperMessage(key, text) {
  const userInfo = whisperUsers.get(key)
  if (!userInfo) {
    showToast('unknown user — whisper someone first', 'error')
    return
  }

  // Optimistic: show message with pending status. Reference kept so we can
  // flip status to 'sent' or 'failed' once the network resolves.
  const sendId = `out_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`
  const msg = {
    user: 'you',
    text,
    color: '#808080',
    time: Date.now(),
    self: true,
    platform: userInfo.platform,
    key,
    status: 'pending',
    sendId,
  }
  whisperTimeline.push(msg)
  trimWhisperTimeline()
  lastWhisperKey = key

  if (currentTab === 'whispers') renderWhispersTab()
  whisperSaveDebounced()

  let ok = false
  let errMsg = ''
  let errorKind = ''
  try {
    if (key.startsWith('twitch:')) {
      const resp = await sendTwitchWhisper(userInfo.userId, text)
      ok = !!resp.ok
      errMsg = resp.error || ''
      errorKind = resp.errorKind || ''
    } else if (key.startsWith('hs:')) {
      const toUserId = key.slice(3)
      const resp = await apiFetch('/api/dm', { method: 'POST', body: { toUserId, content: text } })
      ok = !!resp.ok
      errMsg = resp.error || (ok ? '' : 'unknown error')
      if (!ok && resp?.status === 401) errorKind = 'auth'
    }
  } catch (e) {
    ok = false
    errMsg = e.message
  }

  // Mutate the original push (still referenced by sendId) so re-renders pick up state.
  msg.status = ok ? 'sent' : 'failed'
  if (!ok) {
    msg.error = errMsg
    if (errorKind) msg.errorKind = errorKind
  }
  if (currentTab === 'whispers') renderWhispersTab()
  whisperSaveDebounced()
}

// Auto-retry queued auth-failed whispers when auth comes back online.
// Bound to storage.onChanged on first call; safe to call repeatedly.
function retryAuthFailedWhispers() {
  const failed = whisperTimeline.filter((m) => m.status === 'failed' && m.errorKind === 'auth' && m.sendId)
  if (!failed.length) return
  log(`[whispers] auth restored — retrying ${failed.length} queued send(s)`)
  // Stagger retries so we don't burst the helix endpoint.
  failed.forEach((m, i) => {
    cleanup.setTimeout(() => retryWhisperSend(m.sendId), i * 250)
  })
}

async function retryWhisperSend(sendId) {
  const idx = whisperTimeline.findIndex((m) => m.sendId === sendId)
  if (idx < 0) return
  const old = whisperTimeline[idx]
  if (old.status !== 'failed') return
  // Remove the failed entry — sendWhisperMessage will push a fresh pending one.
  whisperTimeline.splice(idx, 1)
  await sendWhisperMessage(old.key, old.text)
}

function renderWhispersTab() {
  if (typeof activeProfileCard !== 'undefined' && activeProfileCard) return
  const msgsEl = document.getElementById('hs-mc-messages')
  if (!msgsEl) return
  resolveSelfColor()

  // Fetch HS DMs on first render to backfill timeline
  if (!whisperDmsLoaded && hsAuthToken) {
    whisperDmsLoaded = true
    apiFetch('/api/dm')
      .then((resp) => {
        if (!resp.ok || !Array.isArray(resp.data)) return
        for (const dm of resp.data) {
          const key = `hs:${dm.other_user_id}`
          whisperUsersSet(key, {
            platform: 'heatsync',
            userId: dm.other_user_id,
            displayName: dm.other_display_name,
            color: dm.other_color || '#ff8700',
          })
          // Fetch recent messages for each conversation
          apiFetch(`/api/dm/${dm.other_user_id}`)
            .then((resp2) => {
              if (!resp2.ok || !Array.isArray(resp2.data)) return
              let added = false
              for (const m of resp2.data) {
                const t = new Date(m.created_at).getTime()
                if (_whisperMarkSeen(_whisperDedupKey('heatsync', m.id, m.from_display_name, t, m.content))) continue
                const isSelf = m.from_user_id !== dm.other_user_id
                whisperTimeline.push({
                  user: isSelf ? 'you' : dm.other_display_name,
                  text: m.content,
                  color: isSelf ? '#808080' : dm.other_color || '#ff8700',
                  time: t,
                  self: isSelf,
                  platform: 'heatsync',
                  key,
                  id: m.id || '',
                })
                added = true
              }
              if (added) {
                whisperTimeline.sort((a, b) => a.time - b.time)
                trimWhisperTimeline()
                if (currentTab === 'whispers') renderWhispersTab()
                whisperSaveDebounced()
              }
            })
            .catch((e) => log('[whispers] dm history fetch failed:', e?.message || e))
        }
      })
      .catch((e) => {
        whisperDmsLoaded = false
        log('[whispers] dm list fetch failed:', e?.message || e)
      })
  }

  // Mark as read — server-backed, fans out to other clients via WS.
  bumpSeen('whispers')
  whisperSaveDebounced()

  if (whisperTimeline.length === 0) {
    msgsEl.replaceChildren()
    const emptyDiv = document.createElement('div')
    emptyDiv.className = 'hs-mc-empty'
    // Skeleton while the DM history fetch is in flight — prevents the empty
    // hint from flashing for a beat before the actual conversations render.
    // Only relevant on first whispers-tab open with auth + no cached timeline.
    if (whisperDmsLoaded && hsAuthToken) {
      emptyDiv.textContent = t('common_loading') || 'loading…'
    } else {
      emptyDiv.textContent = t('mc_whisper_hint')
    }
    msgsEl.appendChild(emptyDiv)
    return
  }

  msgsEl.replaceChildren()
  const frag = document.createDocumentFragment()
  const toRender = whisperTimeline.slice(-150)
  let zebraCount = 0

  for (const m of toRender) {
    const div = document.createElement('div')
    let cls = m.self ? 'hs-mc-msg hs-whisper-self' : 'hs-mc-msg'
    if (m.status === 'pending') cls += ' hs-whisper-pending'
    else if (m.status === 'failed') cls += ' hs-whisper-failed'
    div.className = cls
    if (m.sendId) div.dataset.sendId = m.sendId
    if (zebraEnabled && ++zebraCount % 2 === 0) div.classList.add('hs-mc-zebra')

    const ts = formatTimeFromTs(m.time)
    const tsHtml = ts ? `<span class="hs-mc-ts">${ts}</span>` : ''
    const platColor = m.platform === 'twitch' ? '#9146ff' : '#ff8700'
    const platTag = m.platform === 'twitch' ? 'T' : 'HS'
    const arrow = m.self ? '\u2192' : '\u2190'

    // Show sender -> recipient for both directions
    const target = whisperUsers.get(m.key)
    const me = currentUsername || 'you'
    const myColor = sanitizeColor(selfWhisperColor || '#fff')
    const them = target?.displayName || m.user || m.key
    const theirColor = target ? sanitizeColor(target.color) : sanitizeColor(m.color)
    const theirUsername = (target?.displayName || m.user || '').toLowerCase()

    // Build username links with hs-mc-user class for tooltip + click.
    // Paint the name with the user's 7TV cosmetic when known (Twitch only —
    // heatsync ids aren't 7TV-keyed); falls back to their plain color.
    function userLink(name, color, username, uid) {
      const safe = escapeHtml(name)
      const lower = username.toLowerCase()
      const safeUser = escapeHtml(lower)
      const href =
        m.platform === 'heatsync'
          ? `https://heatsync.org/user/${encodeURIComponent(username)}`
          : `https://heatsync.org/twitch/${encodeURIComponent(username)}`
      const paint = m.platform === 'heatsync' ? '' : userPaintStyle(uid, lower)
      const style = paint || `color:${color};font-weight:600`
      return `<a href="${href}" target="_blank" rel="noopener noreferrer" class="hs-mc-user" data-username="${safeUser}" style="${style}">${safe}</a>`
    }

    const themUid = target?.userId || ''
    const senderLink = m.self ? userLink(me, myColor, me, '') : userLink(them, theirColor, theirUsername, themUid)
    const recipientLink = m.self ? userLink(them, theirColor, theirUsername, themUid) : userLink(me, myColor, me, '')

    let statusHtml = ''
    if (m.status === 'pending') {
      statusHtml = ` <span class="hs-whisper-status" title="sending">…</span>`
    } else if (m.status === 'failed') {
      const errSafe = escapeHtml(m.error || 'failed')
      const idSafe = escapeHtml(m.sendId || '')
      if (m.errorKind === 'auth') {
        statusHtml = ` <a href="https://heatsync.org/api/auth/login?return_to=%2Fhome%2Fhot" target="_blank" rel="noopener noreferrer" class="hs-whisper-status hs-whisper-relogin" title="${errSafe} — click to log in on heatsync">⚠ log in on heatsync to send</a>`
      } else {
        statusHtml = ` <span class="hs-whisper-status hs-whisper-retry" title="click to retry" data-retry="${idSafe}">⚠ ${errSafe} — retry</span>`
      }
    }

    // All dynamic values pass through escapeHtml/sanitizeColor — safe innerHTML (all values escaped above)
    div.innerHTML = `${tsHtml}<span style="color:${platColor};font-size:13px;font-weight:700">[${platTag}]</span> ${senderLink} <span style="color:#808080">-&gt;</span> ${recipientLink}: ${highlightHashtagsInHtml(processEmotes(escapeHtml(m.text), null))}${statusHtml}`
    frag.appendChild(div)
  }

  msgsEl.appendChild(frag)
  msgsEl.scrollTop = msgsEl.scrollHeight

  msgsEl.querySelectorAll('.hs-whisper-retry').forEach((el) => {
    el.addEventListener('click', (e) => {
      e.preventDefault()
      e.stopPropagation()
      const id = el.getAttribute('data-retry')
      if (id) retryWhisperSend(id)
    })
  })
}


// --- multichat/eventsub-whispers.js ---
// EventSub WebSocket — Twitch whisper reception.
// IRC WHISPER delivery is deprecated/silently dropped since Feb 2023;
// the only documented path is EventSub user.whisper.message.

const ESW_URL = 'wss://eventsub.wss.twitch.tv/ws'
const ESW_HELIX_SUBS = 'https://api.twitch.tv/helix/eventsub/subscriptions'
const ESW_HELIX_USERS = 'https://api.twitch.tv/helix/users'
const ESW_CLIENT_ID = 'kimne78kx3ncx6brgo4mv6wki5h1ko'

const eswState = {
  ws: null,
  sessionId: null,
  selfUserId: null,
  destroyed: false,
  connecting: false,
  subscribed: false,
  subscribing: false, // a subscribe POST is in flight — block a reconnect-welcome from firing a duplicate
  reconnectTimer: null,
  reconnectDelay: 1000,
  keepaliveTimer: null,
  keepaliveTimeoutMs: 30000,
  lastMessageTime: 0,
  seenIds: new Set(),
  seenIdOrder: [],
}
const ESW_SEEN_MAX = 200

function eswMarkSeen(id) {
  if (!id) return false
  if (eswState.seenIds.has(id)) return true
  eswState.seenIds.add(id)
  eswState.seenIdOrder.push(id)
  if (eswState.seenIdOrder.length > ESW_SEEN_MAX) {
    const old = eswState.seenIdOrder.shift()
    eswState.seenIds.delete(old)
  }
  return false
}

async function eswFetchSelfUserId(token) {
  if (eswState.selfUserId) return eswState.selfUserId
  try {
    const resp = await fetch(ESW_HELIX_USERS, {
      headers: { 'Client-Id': ESW_CLIENT_ID, Authorization: 'Bearer ' + token },
      signal: AbortSignal.timeout(8000),
    })
    if (!resp.ok) {
      log('EventSub: /helix/users failed', resp.status)
      return null
    }
    const data = await resp.json()
    const id = data?.data?.[0]?.id
    if (id) eswState.selfUserId = id
    return id || null
  } catch (e) {
    log('EventSub: self id fetch failed:', e.message)
    return null
  }
}

async function eswSubscribeWhispers(token) {
  if (!eswState.sessionId || !eswState.selfUserId) return false
  if (eswState.subscribing) return false // POST already in flight — don't double-subscribe
  eswState.subscribing = true
  try {
    const resp = await fetch(ESW_HELIX_SUBS, {
      method: 'POST',
      headers: {
        'Client-Id': ESW_CLIENT_ID,
        Authorization: 'Bearer ' + token,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        type: 'user.whisper.message',
        version: '1',
        condition: { user_id: eswState.selfUserId },
        transport: { method: 'websocket', session_id: eswState.sessionId },
      }),
      signal: AbortSignal.timeout(8000),
    })
    if (resp.status === 202) {
      eswState.subscribed = true
      log('EventSub: subscribed user.whisper.message')
      return true
    }
    const txt = await resp.text().catch(() => '')
    log('EventSub: subscribe failed', resp.status, txt.slice(0, 200))
    if (resp.status === 401 || resp.status === 403) {
      // Token lacks user:read:whispers — give up (don't reconnect-loop)
      eswState.destroyed = true
      eswCleanup(true)
    }
    return false
  } catch (e) {
    log('EventSub: subscribe error', e.message)
    return false
  } finally {
    eswState.subscribing = false
  }
}

function eswCleanup(destroy = false) {
  if (destroy) eswState.destroyed = true
  if (eswState.keepaliveTimer) {
    cleanup.clearInterval(eswState.keepaliveTimer)
    eswState.keepaliveTimer = null
  }
  if (eswState.reconnectTimer) {
    cleanup.clearTimeout(eswState.reconnectTimer)
    eswState.reconnectTimer = null
  }
  if (eswState.oldWsCloseTimer) {
    cleanup.clearTimeout(eswState.oldWsCloseTimer)
    eswState.oldWsCloseTimer = null
  }
  if (eswState.oldWs) {
    try {
      eswState.oldWs.close()
    } catch {}
    eswState.oldWs = null
  }
  if (eswState.ws) {
    eswState.ws.onopen = null
    eswState.ws.onclose = null
    eswState.ws.onerror = null
    eswState.ws.onmessage = null
    try {
      eswState.ws.close()
    } catch {}
  }
  eswState.ws = null
  eswState.sessionId = null
  eswState.subscribed = false
  eswState.connecting = false
}

function eswScheduleReconnect(token) {
  if (eswState.destroyed) return
  if (eswState.reconnectTimer) return
  const delay = eswState.reconnectDelay
  eswState.reconnectDelay = Math.min(delay * 2, 30000)
  const jitteredDelay = delay + Math.random() * delay * 0.5
  log(`EventSub reconnect in ${delay}ms`)
  eswState.reconnectTimer = cleanup.setTimeout(() => {
    eswState.reconnectTimer = null
    if (eswState.destroyed) return
    if (eswState.ws?.readyState === WebSocket.OPEN) return
    eswConnect(token)
  }, jitteredDelay)
}

// Pull a known color for a userId from anywhere we've seen them (whisper history, IRC buffers).
function eswResolveUserColor(userId) {
  if (typeof whisperUsers !== 'undefined') {
    for (const [, u] of whisperUsers) {
      if (u?.userId === userId && u?.color) return u.color
    }
  }
  return null
}

function eswHandleNotification(msg) {
  if (msg.metadata?.subscription_type !== 'user.whisper.message') return
  const event = msg.payload?.event
  if (!event) return

  const msgId = msg.metadata?.message_id
  if (eswMarkSeen(msgId)) return

  const text = event.whisper?.text || ''
  if (!text) return

  // Shape matches handleIncomingWhisper (whispers.js:128)
  handleIncomingWhisper({
    user: event.from_user_name || event.from_user_login || 'unknown',
    userId: event.from_user_id,
    text,
    color: eswResolveUserColor(event.from_user_id) || '#fff',
    time: msg.metadata?.message_timestamp ? new Date(msg.metadata.message_timestamp).getTime() : Date.now(),
    id: event.whisper_id || msgId || '',
  })
}

function eswHandleMessage(token) {
  return (event) => {
    eswState.lastMessageTime = Date.now()
    let msg
    try {
      msg = JSON.parse(event.data)
    } catch {
      return
    }
    const type = msg.metadata?.message_type
    if (!type) return

    if (type === 'session_welcome') {
      eswState.sessionId = msg.payload?.session?.id
      const kt = msg.payload?.session?.keepalive_timeout_seconds
      if (typeof kt === 'number') eswState.keepaliveTimeoutMs = (kt + 5) * 1000
      log('EventSub session welcome:', eswState.sessionId)
      // Reconnect-flow welcome carries existing subs over — only subscribe on
      // first connect, and never while a prior POST is still in flight (a fast
      // server reconnect mid-POST would otherwise create a duplicate sub).
      if (!eswState.subscribed && !eswState.subscribing) eswSubscribeWhispers(token)
      if (eswState.keepaliveTimer) cleanup.clearInterval(eswState.keepaliveTimer)
      eswState.keepaliveTimer = cleanup.setInterval(() => {
        if (Date.now() - eswState.lastMessageTime > eswState.keepaliveTimeoutMs) {
          log('EventSub: keepalive timeout — reconnecting')
          eswCleanup()
          eswScheduleReconnect(token)
        }
      }, 5000)
      eswState.reconnectDelay = 1000
      return
    }
    if (type === 'session_keepalive') return
    if (type === 'notification') {
      eswHandleNotification(msg)
      return
    }
    if (type === 'session_reconnect') {
      const newUrl = msg.payload?.session?.reconnect_url
      if (newUrl) {
        log('EventSub: server requested reconnect')
        eswConnect(token, newUrl)
      }
      return
    }
    if (type === 'revocation') {
      log('EventSub: subscription revoked', msg.payload?.subscription?.status)
      eswState.subscribed = false
      eswCleanup()
      eswScheduleReconnect(token)
      return
    }
  }
}

async function eswConnect(token, urlOverride) {
  if (eswState.connecting) return false
  if (!token) return false
  if (!eswState.selfUserId) {
    const id = await eswFetchSelfUserId(token)
    if (!id) {
      log('EventSub: no self user id, abort')
      return false
    }
  }
  eswState.connecting = true
  eswState.destroyed = false

  // Reconnect-URL flow: keep old socket open until new one welcomes,
  // but stop the old keepalive timer so it can't fire against the stale lastMessageTime.
  const oldWs = urlOverride ? eswState.ws : null
  if (urlOverride) {
    if (eswState.keepaliveTimer) {
      cleanup.clearInterval(eswState.keepaliveTimer)
      eswState.keepaliveTimer = null
    }
  } else {
    eswCleanup()
  }

  try {
    const ws = new WebSocket(urlOverride || ESW_URL)
    eswState.ws = ws
    ws.onopen = () => {
      eswState.lastMessageTime = Date.now()
    }
    ws.onmessage = eswHandleMessage(token)
    ws.onclose = () => {
      log('EventSub: socket closed')
      if (eswState.destroyed) return
      eswScheduleReconnect(token)
    }
    ws.onerror = () => {}
    if (oldWs) {
      eswState.oldWs = oldWs
      eswState.oldWsCloseTimer = cleanup.setTimeout(() => {
        eswState.oldWsCloseTimer = null
        if (eswState.oldWs === oldWs) eswState.oldWs = null
        try {
          oldWs.onmessage = null
          oldWs.onclose = null
          oldWs.onerror = null
          oldWs.close()
        } catch {}
      }, 5000)
    }
    eswState.connecting = false
    return true
  } catch (e) {
    log('EventSub: connect failed', e.message)
    eswState.connecting = false
    eswScheduleReconnect(token)
    return false
  }
}

async function startEventSubWhispers() {
  // Async fetch reaches twitch cookies even on Kick/YouTube tabs (via background.js)
  const { token } = await getTwitchAuthTokenAsync()
  if (!token) {
    log('EventSub: no Twitch token, skipping whispers')
    return
  }
  await eswConnect(token)
}

async function reconnectEventSubIfDead() {
  if (eswState.destroyed) return
  if (eswState.ws?.readyState === WebSocket.OPEN) return
  if (eswState.connecting) return
  const { token } = await getTwitchAuthTokenAsync()
  if (!token) return
  log('EventSub: reconnecting (visibility/wake)')
  eswConnect(token)
}


// --- multichat/cross-follow.js ---
// Cross-platform follow propagation
//
// When the user follows another user on heatsync, also follow them on Twitch
// and Kick if they have linked accounts there. Twitch's public follow REST
// API was killed Aug 2023; we use the same private GraphQL mutation
// (FollowButton_FollowUser) that Twitch's own UI fires, through the existing
// integrity/relay plumbing in twitch-api.js. Kick has no public follow
// endpoint at all; we POST /api/v2/channels/{slug}/follow with the user's
// own session cookie + XSRF token (same surface as our chat-send relay).
//
// YouTube is intentionally NOT propagated — the Innertube subscribe path
// requires SAPISIDHASH minting in a youtube.com tab, has the highest ToS
// risk of the three, and youtube tabs are rare for HeatSync's user base.
//
// Failure handling: heatsync follow is the source of truth. Platform follows
// are best-effort. If we can't reach a platform right now (no twitch.tv tab
// open + integrity unavailable, kick not logged in, etc.), the action is
// queued to chrome.storage.local.hs_pending_follows and drained on next
// platform tab navigation. The queue collapses follow/unfollow pairs (last
// write wins), caps at 100 entries, and drops items older than 7 days.

const HS_PENDING_KEY = 'hs_pending_follows'
const HS_PENDING_MAX = 100
const HS_PENDING_MAX_AGE_MS = 7 * 24 * 60 * 60 * 1000

// Per-platform user preference. Defaults all on. Read from ui_settings on
// each call so toggling in settings UI applies without a reload.
async function _crossFollowSettings() {
  try {
    // ui_settings is the SYNC blob (settings-schema scope:'sync' → it; every
    // ui_settings write in main.js targets storage.sync). Reading it from
    // storage.local returned {} every time, so crossFollowKick was pinned to
    // its default (true) and the toggle did nothing. Read from sync to match.
    // api.storage.sync.get returns a Promise directly — don't wrap in a
    // callback shim (it's promise-based; a callback never fires).
    const stored = await api.storage.sync.get(['ui_settings'])
    const ui = stored?.ui_settings || {}
    return {
      twitch: ui.crossFollowTwitch !== false,
      kick: ui.crossFollowKick !== false,
      twitchNotifyTarget: ui.crossFollowTwitchNotify !== false,
    }
  } catch {
    return { twitch: true, kick: true, twitchNotifyTarget: true }
  }
}

// ─── Queue helpers ──────────────────────────────────────────────────────────

async function _readQueue() {
  try {
    const stored = await api.storage.local.get([HS_PENDING_KEY])
    const arr = Array.isArray(stored?.[HS_PENDING_KEY]) ? stored[HS_PENDING_KEY] : []
    const cutoff = Date.now() - HS_PENDING_MAX_AGE_MS
    const fresh = arr.filter((x) => x && typeof x.ts === 'number' && x.ts >= cutoff)
    return fresh.slice(-HS_PENDING_MAX)
  } catch {
    return []
  }
}

async function _writeQueue(arr) {
  try {
    await api.storage.local.set({ [HS_PENDING_KEY]: arr })
  } catch {}
}

// Insert / replace. If a previous entry for the same {platform, target}
// exists, the newer one supersedes it — last write wins, so follow/unfollow
// rapid toggles collapse rather than queueing both.
async function _enqueue(item) {
  if (!item?.platform || !item?.target) return
  const q = await _readQueue()
  const filtered = q.filter((x) => !(x.platform === item.platform && x.target === item.target))
  filtered.push({ ...item, ts: Date.now() })
  await _writeQueue(filtered.slice(-HS_PENDING_MAX))
}

async function _dequeueMatching(platform, target) {
  const q = await _readQueue()
  const filtered = q.filter((x) => !(x.platform === platform && x.target === target))
  if (filtered.length !== q.length) await _writeQueue(filtered)
}

// Drain all pending items for a platform. Called from background SW after it
// detects the user navigated to twitch.com / kick.com (or by hand via a
// debug command). Each item gets one retry; if it fails again, stays queued.
async function drainPendingFollows(platform) {
  if (!platform) return { ok: false, drained: 0 }
  const q = await _readQueue()
  const mine = q.filter((x) => x.platform === platform)
  if (!mine.length) return { ok: true, drained: 0 }
  let drained = 0
  const drainedItems = []
  for (const item of mine) {
    let result = { error: 'unknown platform' }
    if (platform === 'twitch') {
      // Use _twitchFollow (full chain incl. DOM-click) when slug available,
      // otherwise fall back to id-only path which only attempts the GQL routes.
      if (item.username) {
        result = await _twitchFollow(item.target, item.action === 'follow', item.disableNotifications, item.username)
      } else {
        result = await (typeof followTwitchUserById === 'function'
          ? followTwitchUserById(item.target, item.action === 'follow', item.disableNotifications)
          : { error: 'no helper' })
      }
    } else if (platform === 'kick') {
      result = await _kickFollow(item.target, item.action === 'follow')
    }
    if (result?.ok) {
      drained++
      drainedItems.push(item)
      await _dequeueMatching(platform, item.target)
    }
  }
  // Log drain attempt outcome — useful to see in console why a pending follow
  // didn't sync (e.g. apollo path failed silently). One line per drain cycle.
  try {
    if (mine.length) console.warn('[heatsync] drained', platform, drained, 'of', mine.length, 'pending')
  } catch {}
  // Soft success toast so the user knows their queued follows just synced.
  if (drained > 0 && typeof showToast === 'function') {
    const sample = drainedItems[0]?.username || drainedItems[0]?.target || ''
    const verb = drainedItems[0]?.action === 'unfollow' ? 'unfollowed' : 'followed'
    if (drained === 1 && sample) {
      showToast(`${verb} ${sample} on ${platform}`, 'success')
    } else {
      showToast(`synced ${drained} pending ${platform} follow(s)`, 'success')
    }
  }
  return { ok: true, drained }
}

// Expose for background SW: a content-script listener that drains on demand.
if (typeof api !== 'undefined' && api?.runtime?.onMessage) {
  api.runtime.onMessage.addListener((msg, _sender, sendResponse) => {
    if (msg?.type === 'cross_follow_drain' && typeof msg.platform === 'string') {
      drainPendingFollows(msg.platform)
        .then(sendResponse)
        .catch((e) => sendResponse({ ok: false, error: e?.message }))
      return true
    }
    return false
  })
}

// ─── Kick follow ────────────────────────────────────────────────────────────
//
// SW direct fetch with credentials:include + XSRF cookie. No relay needed
// since the extension has host_permissions for kick.com/* and the user's
// own session cookie travels naturally. If XSRF missing → kick not logged
// in → queue.

async function _kickFollow(slug, follow) {
  if (!slug) return { error: 'no slug' }
  const safeSlug = String(slug)
    .toLowerCase()
    .replace(/[^a-z0-9_-]/g, '')
    .slice(0, 64)
  if (!safeSlug) return { error: 'invalid slug' }
  try {
    const resp = await safeSendMessage({
      type: 'kick_follow',
      slug: safeSlug,
      follow: !!follow,
    })
    if (resp?.ok) return { ok: true, idempotent: !!resp.idempotent }
    if (resp?.error === 'kick_not_logged_in') return { error: 'kick_not_logged_in', queueable: true }
    return { error: resp?.error || 'kick follow failed', queueable: true }
  } catch (e) {
    return { error: e?.message || 'kick follow throw', queueable: true }
  }
}

// ─── Twitch follow ──────────────────────────────────────────────────────────
//
// Twitch's public follow REST API was killed Aug 2023. Only programmatic path
// left is the FollowButton_FollowUser GQL mutation — but only when fired
// through Twitch's OWN Apollo client (so the link chain attaches the strong
// per-mutation integrity tokens Twitch's anti-bot demands). Direct gql.twitch.tv
// fetches with even a freshly-minted /integrity token get rejected as
// "failed integrity check" — the strong tokens only validate when added by
// Apollo's link middleware. Verified 2026-05-26.
//
// _followMutation (twitch-api.js) handles all the routing:
//   - on twitch.tv: apolloMutate via MAIN-world finder (Document + fragment deps
//     resolved via recursive webpack require — see early-inject-main.js)
//   - off twitch.tv: relay through any open twitch.tv tab (background SW
//     picks the tab + executes the script there)
//   - no twitch.tv tab open: queueable — drained next time user visits twitch.tv
async function _twitchFollow(targetID, follow, disableNotifications, _targetSlug) {
  if (!targetID) return { error: 'no target id' }
  if (typeof followTwitchUserById !== 'function') return { error: 'follow helper missing' }
  return followTwitchUserById(targetID, follow, disableNotifications)
}

// ─── Main entry: called from pcToggleFollow + pcToggleBlock ─────────────────
//
// target shape: { twitch_id, twitch_username, kick_username, youtube_channel_id, youtube_username }
// follow=true → propagate follow; follow=false → propagate unfollow.
// Returns: { twitch: {...}, kick: {...} } — caller can surface diagnostics
// in dev mode but the default UX is silent best-effort.
async function propagateFollow(follow, target) {
  if (!target) return { kick: { skipped: 'no target' } }
  const settings = await _crossFollowSettings()
  const out = { twitch: { skipped: 'no twitch id' }, kick: { skipped: 'no kick username' } }

  if (settings.twitch && target.twitch_id) {
    const verb = follow ? 'follow' : 'unfollow'
    const r = await _twitchFollow(target.twitch_id, follow, false, target.twitch_username)
    if (r?.ok) {
      out.twitch = { ok: true, idempotent: !!r.idempotent }
      await _dequeueMatching('twitch', String(target.twitch_id))
    } else {
      out.twitch = { error: r?.error || 'twitch follow failed' }
      if (r?.queueable) {
        await _enqueue({
          platform: 'twitch',
          target: String(target.twitch_id),
          username: target.twitch_username ? String(target.twitch_username).toLowerCase() : undefined,
          action: follow ? 'follow' : 'unfollow',
          disableNotifications: false,
        })
      }
      // Surface 2fa requirement — user has to satisfy it on twitch.tv
      if (r?.error === '2fa_required' && typeof showToast === 'function') {
        showToast(`twitch ${verb} blocked: 2FA required — complete on twitch.tv`, 'info')
      }
    }
  }

  if (settings.kick && target.kick_username) {
    const verb = follow ? 'follow' : 'unfollow'
    const r = await _kickFollow(target.kick_username, follow)
    if (r?.ok) {
      out.kick = { ok: true, idempotent: !!r.idempotent }
      await _dequeueMatching('kick', String(target.kick_username).toLowerCase())
    } else {
      out.kick = { error: r?.error || 'kick follow failed' }
      if (r?.queueable) {
        await _enqueue({
          platform: 'kick',
          target: String(target.kick_username).toLowerCase(),
          action: follow ? 'follow' : 'unfollow',
        })
      }
      // Surface only login-needed; treat other transient kick errors as silent
      // (heatsync follow already toasted; we don't want noise on each follow).
      if (r?.error === 'kick_not_logged_in' && typeof showToast === 'function') {
        showToast(`kick ${verb} queued — will sync when you log in to kick.com`, 'info')
      }
    }
  }
  return out
}


// --- multichat/input.js ---
// Input - chat input, autocomplete, send message, reply state

// Message history — up/down arrow recalls previously sent messages
const mcMessageHistory = []
const MC_HISTORY_MAX = 50
let mcHistoryIndex = -1
let mcHistoryDraft = ''

// Broken-image recovery for input-area emote imgs. Browser negatively caches
// failed image responses (proxy hiccup, CDN blip); without this hook the typed
// word renders forever as a broken-image placeholder in the composer.
// Strategy: retry once with a cache-bust to defeat the negative cache, then
// fall back to the alt text so the message still ships as plain text.
function attachInputEmoteErrorRecovery(img) {
  img.addEventListener('error', () => {
    if (img.dataset.hsRetried) {
      const t = document.createTextNode(img.alt || '')
      img.replaceWith(t)
      return
    }
    img.dataset.hsRetried = '1'
    img.src = img.src + (img.src.includes('?') ? '&' : '?') + 'r=' + Date.now()
  })
}

// Brief red flash on input to indicate message can't be sent from this tab
function flashInputError(input) {
  if (!input) return
  input.style.background = '#400000'
  input.style.borderColor = '#ff0000'
  setTimeout(() => {
    input.style.background = ''
    input.style.borderColor = ''
  }, 600)
}

// Per-emote operation lock to prevent race conditions from rapid clicking
const pendingEmoteOps = new Set()

// Cache own badge string from IRC messages for optimistic display.
// Per-channel: sub badge tier differs by streamer, so a single global ref
// stamped the wrong channel's sub badge onto synthetic celebrations.
let _ownBadges = ''
const _ownBadgesByChannel = new Map() // channelLower -> badges string
function ownBadgesFor(channel) {
  if (!channel) return _ownBadges
  return _ownBadgesByChannel.get(String(channel).toLowerCase()) || _ownBadges
}

// Echo dedup — suppress own message echoes from IRC/KickChat relay
// Uses a Set of {text, time} to handle rapid sends without overwriting
let _recentSentMessages = []
const SENT_DEDUP_WINDOW = 10000 // 10s — used by isSentEcho to suppress dual-send duplicates only
const SENT_HOST_WINDOW = 24 * 60 * 60 * 1000 // 24h — peekSentHost needs longer so badge survives refresh
const RECENT_SENT_KEY = 'hs_recent_sent'

function _pruneRecent(arr) {
  // Prune to the LONGER window so peekSentHost can attribute badges across
  // refreshes. isSentEcho applies its own tighter cutoff at lookup time.
  const cutoff = Date.now() - SENT_HOST_WINDOW
  return arr.filter((e) => e && e.time >= cutoff)
}

function trackSentMessage(text, hostOverride, synthId, echoes) {
  _recentSentMessages.push({ text, time: Date.now(), host: hostOverride || hostPlatform, synthId, echoes: echoes || 1 })
  _recentSentMessages = _pruneRecent(_recentSentMessages)
  // Cross-tab sync: kick.com tab and twitch.tv tab live in different
  // content-script contexts, so they each have their own array. Storage
  // mirrors the entry to every tab via onChanged so peekSentHost on the
  // OTHER host tagged the IRC echo with the correct origin host. ~50ms
  // sync latency easily wins the race against the ~100-300ms platform
  // chat round-trip.
  try {
    chrome.storage.local.set({ [RECENT_SENT_KEY]: _recentSentMessages })
  } catch (_) {}
}

// Hydrate from storage on load + listen for cross-tab updates.
// Listener is tracked via cleanup so SPA reinit doesn't stack copies.
// recentSentHydrated Promise lets BG-history loaders await this before
// stamping platform badges — otherwise the storage-hydration race lets the
// echo render as the IRC echo's actual origin (twitch) instead of the
// sending host (kick).
let _recentSentHydrated = null
{
  let _hydrateResolve = null
  _recentSentHydrated = new Promise((r) => {
    _hydrateResolve = r
  })
  try {
    chrome.storage.local
      .get(RECENT_SENT_KEY)
      .then((data) => {
        const incoming = data?.[RECENT_SENT_KEY]
        if (Array.isArray(incoming)) _recentSentMessages = _pruneRecent(incoming)
      })
      .catch(() => {})
      .finally(() => {
        try {
          _hydrateResolve()
        } catch {}
      })
  } catch (_) {
    _hydrateResolve()
  }
}
try {
  if (!window._hsMcInputStorageListener) {
    const _inputStorageHandler = (changes, area) => {
      if (area !== 'local' || !changes[RECENT_SENT_KEY]) return
      const incoming = changes[RECENT_SENT_KEY].newValue
      if (!Array.isArray(incoming)) return
      // Merge our local writes with the incoming snapshot — last-write-wins
      // by (text, second-bucketed time). Survives the rare two-tab-send race.
      const merged = new Map()
      for (const e of [..._recentSentMessages, ...incoming]) {
        if (!e || !e.text) continue
        const k = `${e.text}:${Math.floor((e.time || 0) / 1000)}`
        const existing = merged.get(k)
        if (!existing || (existing.time || 0) < (e.time || 0)) merged.set(k, e)
      }
      _recentSentMessages = _pruneRecent([...merged.values()].sort((a, b) => a.time - b.time))
    }
    cleanup.addListener(chrome.storage.onChanged, _inputStorageHandler)
    window._hsMcInputStorageListener = true
  }
} catch (_) {}

function isSentEcho(msgText, _msgPlatform) {
  const cutoff = Date.now() - SENT_DEDUP_WINDOW
  for (let i = _recentSentMessages.length - 1; i >= 0; i--) {
    const entry = _recentSentMessages[i]
    // continue (not break): a cross-tab merge can briefly leave the array out
    // of time order, so an old entry early doesn't mean all earlier are old.
    if (entry.time < cutoff) continue
    if (entry.text === msgText) {
      // First echo displays; second (dual-send duplicate) is suppressed.
      // Host-platform badge attribution happens separately via peekSentHost,
      // so we don't suppress on host mismatch — that would drop the only
      // echo when sending from one platform to a single-platform channel
      // on a different host (e.g. kick.com → twitch-only mellen).
      entry.suppressed = (entry.suppressed || 0) + 1
      if (entry.suppressed >= 2) {
        // Suppress every echo after the first. Remove the entry only once all
        // expected echoes have arrived (one per target platform) — a triple
        // send (twitch+kick+youtube) produces 3 echoes; removing after the 2nd
        // let the 3rd render as a duplicate of the user's own message.
        if (entry.suppressed >= (entry.echoes || 2)) _recentSentMessages.splice(i, 1)
        return true
      }
      return false
    }
  }
  return false
}

// Peek a recent-sent entry by text WITHOUT consuming it. Used by the IRC/kick
// handlers to attribute the badge platform on the displayed echo. Returns the
// host platform string ('twitch' | 'kick' | 'yt') or null if no tracked send
// matches — letting echoes from elsewhere (e.g. heatsync.org website sends)
// keep whatever platform tag the server attached.
function peekSentHost(msgText) {
  // Use the longer SENT_HOST_WINDOW (24h) — badge attribution must survive
  // page refresh, BG buffer replay, and channel-switch hydration. The dedup
  // path (isSentEcho) uses the tighter 10s window separately.
  const cutoff = Date.now() - SENT_HOST_WINDOW
  for (let i = _recentSentMessages.length - 1; i >= 0; i--) {
    const entry = _recentSentMessages[i]
    // continue (not break): cross-tab storage merges can leave entries out of
    // time order, so a stale entry early in the reverse scan must not abort the
    // search before a valid newer match (mirrors isSentEcho). Array is capped.
    if (entry.time < cutoff) continue
    if (entry.text === msgText) return entry.host || null
  }
  return null
}

// ============================================
// PENDING-SEND TRACKER — round-trip confirmation
// ============================================
// Every send registers an entry keyed by synthId with a per-platform awaiting
// set. Echo arrival via the IRC/Kick read socket calls confirmPending(id,
// platform) which removes that platform from awaiting; the entry is only
// dismissed when the set drains. If the 7s timeout fires with anything still
// awaiting, the user sees a persistent notif with a one-click [retry].
//
// Per-platform tracking matters for dual-send: if twitch echoes but kick
// silently drops (or vice versa), the legacy "any echo = all good" logic
// would mask the dropped platform and the user would never know. The
// tracker exists precisely to catch silent drops — shadow-mute, integrity
// fails, mid-rejoin races leave no NOTICE, no error, just gone — and that
// guarantee only holds if we wait for every platform we sent to.
const pendingSends = new Map()
// 20s: 12s was firing false positives when SW briefly suspended/restarted
// during the echo window. Real BG-restart cycles can take 5-15s before the
// anon socket rejoins and starts receiving PRIVMSGs again. 20s catches those
// while still flagging genuine silent drops (shadow-mute, AutoMod). Worst-
// case the user sees the toast 8s later than before — but doesn't see false
// alarms when their message actually went through.
const PENDING_ECHO_TIMEOUT_MS = 20000
// Expose for devtools
try {
  globalThis.__hsPendingSends = pendingSends
} catch (_) {}

function makeSynthId() {
  return `hs-pend-${Date.now().toString(36)}-${Math.floor(Math.random() * 1e9).toString(36)}`
}

// Twitch/Kick chat commands the platform executes and acks via a NOTICE — they
// never echo back as a PRIVMSG, so the round-trip tracker must not await one or
// it fires a false "did not confirm" 20s after the command actually ran. These
// fall through handleSlashCommand (unwired) and get sent raw; the NOTICE is the
// real ack (success or rejection, surfaced by auth-irc). /me is NOT here — it
// echoes as a CTCP ACTION.
const NON_ECHOING_CHAT_COMMANDS = new Set([
  'followers', 'followersoff',
  'emoteonly', 'emoteonlyoff',
  'subscribers', 'subscribersoff',
  'slow', 'slowoff',
  'uniquechat', 'uniquechatoff', 'r9kbeta', 'r9kbetaoff',
  'clear', 'color',
  'mod', 'unmod', 'vip', 'unvip',
  'untimeout', 'unban',
  'raid', 'unraid', 'commercial', 'marker',
  'announce', 'announceblue', 'announcegreen', 'announceorange', 'announcepurple',
])
function isNonEchoingCommand(text) {
  if (typeof text !== 'string' || text[0] !== '/') return false
  const m = text.match(/^\/(\w+)/)
  return !!m && NON_ECHOING_CHAT_COMMANDS.has(m[1].toLowerCase())
}

function registerPendingSend({ text, channel, platforms, replyParentId, noEcho }) {
  const synthId = makeSynthId()
  const entry = {
    synthId,
    text,
    channel,
    platforms,
    // Per-platform confirmation gate. Drains as echoes arrive; entry is only
    // dismissed when empty. Catches dual-send silent-drop of one platform.
    awaiting: new Set(platforms),
    replyParentId,
    sentAt: Date.now(),
    state: 'pending',
    noEcho: !!noEcho,
    timer: null,
  }
  entry.timer = cleanup.setTimeout(() => {
    const e = pendingSends.get(synthId)
    if (e?.state !== 'pending') return
    // Non-echoing platform commands get no PRIVMSG echo — the write already
    // succeeded, so retire silently rather than firing a false no_echo. Genuine
    // write failures still surface via the explicit markPendingFailed calls in
    // the send paths (auth_failed/send_failed).
    if (e.noEcho) { pendingSends.delete(synthId); return }
    markPendingFailed(synthId, 'no_echo')
  }, PENDING_ECHO_TIMEOUT_MS)
  pendingSends.set(synthId, entry)
  if (MC_DEBUG)
    try {
      console.log(
        '[heatsync-ext] pending registered:',
        JSON.stringify({
          text,
          channel,
          platforms,
          len: text.length,
          codes: [...text].slice(0, 30).map((c) => c.charCodeAt(0)),
        }),
      )
    } catch (_) {}
  return synthId
}

function confirmPending(synthId, platform) {
  const entry = pendingSends.get(synthId)
  if (!entry) return false
  if (platform) entry.awaiting.delete(platform)
  // Only dismiss once every awaited platform has echoed. Calls without a
  // platform arg (legacy/manual confirm paths) collapse the gate immediately.
  if (platform && entry.awaiting.size > 0) return true
  if (entry.timer) cleanup.clearTimeout(entry.timer)
  pendingSends.delete(synthId)
  try {
    HsNotifs.dismissByKey('send-pending', synthId)
  } catch (_) {}
  return true
}

// Find a pending entry matching this echo text. Called from main.js's
// own-echo handlers. Tries exact match first; falls back to whitespace-
// normalized match (collapses NBSP/tabs/runs of spaces) which catches cases
// where the input serializer added/stripped a space the echo didn't, e.g.
// wysiwyg-chip + trailing text-node combinations.
function findPendingByEchoText(text) {
  if (!text || !pendingSends.size) return null
  for (const [id, entry] of pendingSends) {
    if (entry.state !== 'pending') continue
    if (entry.text === text) return id
  }
  const norm = (s) =>
    String(s)
      .replace(/[ \s]+/g, ' ')
      .trim()
  const wantN = norm(text)
  if (!wantN) return null
  for (const [id, entry] of pendingSends) {
    if (entry.state !== 'pending') continue
    if (norm(entry.text) === wantN) return id
  }
  if (MC_DEBUG)
    try {
      const dump = []
      for (const [, entry] of pendingSends) {
        if (entry.state !== 'pending') continue
        dump.push({
          pendingText: entry.text,
          pendingLen: entry.text.length,
          pendingCodes: [...entry.text].slice(0, 30).map((c) => c.charCodeAt(0)),
          pendingChannel: entry.channel,
        })
      }
      console.log(
        '[heatsync-ext] echo text-miss:',
        JSON.stringify({
          echoText: text,
          echoLen: text.length,
          echoCodes: [...text].slice(0, 30).map((c) => c.charCodeAt(0)),
          pending: dump,
        }),
      )
    } catch (_) {}
  return null
}

// Channel+username fallback. Called when text-match misses. Drains the
// oldest pending send for the given channel — Twitch echoes own PRIVMSGs
// back via the BG anon socket as broadcast-to-all, so a PRIVMSG with our
// own display-name arriving for a channel we have pending sends to means
// SOMETHING posted. Resolves the dominant false-positive class where text
// shape diverged between registration and echo (NBSP/serializer ordering).
function findPendingByChannelFifo(channel) {
  if (!channel || !pendingSends.size) return null
  const target = String(channel).toLowerCase().replace(/^#/, '')
  let bestId = null
  let bestSentAt = Infinity
  for (const [id, entry] of pendingSends) {
    if (entry.state !== 'pending') continue
    if (String(entry.channel).toLowerCase() !== target) continue
    if (entry.sentAt < bestSentAt) {
      bestId = id
      bestSentAt = entry.sentAt
    }
  }
  return bestId
}
try {
  globalThis.__hsFindPendingByChannelFifo = findPendingByChannelFifo
} catch (_) {}

function markPendingFailed(synthId, reason) {
  const entry = pendingSends.get(synthId)
  if (!entry) return
  if (entry.timer) cleanup.clearTimeout(entry.timer)
  entry.state = 'failed'
  entry.reason = reason
  if (reason === 'no_echo' && MC_DEBUG) {
    console.warn('[heatsync-ext] send no_echo:', {
      text: entry.text,
      channel: entry.channel,
      awaiting: [...entry.awaiting],
      elapsed: Date.now() - entry.sentAt,
    })
  }
  // Surface the persistent retry notif. dedupeKey=synthId so retry-then-fail-
  // again replaces in place rather than stacking.
  try {
    HsNotifs.emit('send-pending', {
      synthId,
      text: entry.text,
      channel: entry.channel,
      reason,
    })
  } catch (_) {}
}

// Clear pending sends to a channel WITHOUT firing the no_echo toast — used
// when auth-irc's NOTICE handler already showed a specific rejection toast
// (followers-only/slow-mode/banned/etc). Without this, the user got two toasts
// for the same failure: the specific reason immediately, then "no echo from
// platform" 12-20s later. Now the rejection toast is the only signal.
function clearPendingByChannel(channel) {
  if (!channel) return 0
  const target = String(channel).toLowerCase().replace(/^#/, '')
  let cleared = 0
  for (const [id, entry] of pendingSends) {
    if (entry.state !== 'pending') continue
    if (String(entry.channel).toLowerCase() === target) {
      if (entry.timer) cleanup.clearTimeout(entry.timer)
      pendingSends.delete(id)
      try {
        HsNotifs.dismissByKey('send-pending', id)
      } catch (_) {}
      cleared++
    }
  }
  return cleared
}
try {
  globalThis.__hsClearPendingByChannel = clearPendingByChannel
} catch (_) {}

function retryPendingSend(synthId) {
  const entry = pendingSends.get(synthId)
  if (!entry) return
  // Drop the failed entry; sendMessage will register a fresh one.
  pendingSends.delete(synthId)
  try {
    HsNotifs.dismissByKey('send-pending', synthId)
  } catch (_) {}
  const input = document.getElementById('hs-mc-input')
  if (!input) return
  // Restore text into input. wysiwygEnabled is the same flag sendMessage uses.
  if (wysiwygEnabled) restoreWysiwygText(input, entry.text)
  else input.value = entry.text
  // Restore reply state if the original was a reply
  if (entry.replyParentId) {
    try {
      replyState = { msgId: entry.replyParentId }
    } catch (_) {}
  }
  sendMessage()
}

// Expose for the notif action handler
try {
  globalThis.__hsRetryPendingSend = retryPendingSend
} catch (_) {}

// Autocomplete state (Tab-only cycling, no dropdown)
const acState = {
  matches: [],
  index: 0,
  active: false, // true when cycling through matches
  wordStart: 0, // Position where the completion word starts
  afterText: '', // Text after the completion
  search: '', // search term that produced these matches (remote-fetch guard)
  remoteDone: false, // 7tv fallback already merged for this search
  remotePending: false, // a lazy remote fetch is in flight for this search
}

// Emotes surfaced via remote (7TV/BTTV/FFZ) Tab-search this session: name → {url,
// source}. On send, any of these present in the outgoing message that aren't yet
// in the viewer's set get auto-added — so a remote emote you searched and sent
// becomes yours and renders next time. Bounded; explicit tracking beats sniffing
// chips so it works in plain-text mode too.
const recentRemoteCompletions = new Map()
const REMOTE_COMPLETION_CAP = 300

// Register a Tab-completed emote for auto-add-on-send. Covers the LOCAL-match
// path that fetchRemoteEmoteMatches misses: an aliased channel/global 7TV/BTTV/FFZ
// emote tab-completes as a local hit, never enters the registry, and so renders
// live (channel context) but vanishes after refresh because it was never added
// to the viewer's heatsync set. Gated to third-party providers with a URL —
// owned/blocked/pending are filtered later in autoAddInputEmotes.
function trackCompletionForAutoAdd(match) {
  if (!match || match.type !== 'emote' || !match.name || !match.url) return
  const src = match.source
  if (src !== '7tv' && src !== 'bttv' && src !== 'ffz') return
  recentRemoteCompletions.delete(match.name)
  // Carry zeroWidth so optimistic viewerPersonalEmotes.set and the server add
  // both inherit the overlay flag — without it, a tab-completed 7TV overlay
  // emote (CarrotTime, wavE) renders as a standalone base after auto-add.
  recentRemoteCompletions.set(match.name, { url: match.url, source: src, zeroWidth: !!match.zeroWidth })
  while (recentRemoteCompletions.size > REMOTE_COMPLETION_CAP) {
    recentRemoteCompletions.delete(recentRemoteCompletions.keys().next().value)
  }
}

// Infinite Tab-cycle: once local matches run out, pull more from the cross-provider
// search APIs and append. Aborts stale fetches so rapid re-triggering never
// merges results from an old search term.
//
// Provider quality for prefix expansion (verified empirically on 'sad'):
//  - FFZ: prefix-relevance search, sorted by usage_count. Best signal.
//  - BTTV: prefix-relevance, ordered by internal popularity. Solid.
//  - 7TV: exact-text-match flood — `query:"sad"` returns 150 emotes literally
//    named "sad" from different creators. Useless for prefix expansion of
//    common stems; kept for unique uploads on less common terms.
// Quality order at merge: FFZ → BTTV → 7TV.
// Prefix-only on purpose: catalog substring hits (NotSad, KekSadge) are noise.
// Local substring matches still surface via findEmoteMatches.
let _acRemoteAbort = null
let _acRemoteToken = 0
async function fetchRemoteEmoteMatches(search) {
  // Emote-only: skip @user, :emoji, modifier tokens, and short fragments.
  if (!search || search.length < 2) return
  if (search.startsWith('@') || search.startsWith(':')) return
  if (hsModClassify(search, { allowPrefix: false }).kind === 'modifier') return
  const token = ++_acRemoteToken
  acState.remotePending = true
  if (_acRemoteAbort) {
    try {
      _acRemoteAbort.abort()
    } catch (_) {}
  }
  const ac = new AbortController()
  _acRemoteAbort = ac
  const calls = []
  if (typeof mcSearchFfzApi === 'function') calls.push(mcSearchFfzApi(search, ac.signal))
  else calls.push(Promise.resolve([]))
  if (typeof mcSearchBttvApi === 'function') calls.push(mcSearchBttvApi(search, ac.signal))
  else calls.push(Promise.resolve([]))
  if (typeof mcSearch7tvApi === 'function') calls.push(mcSearch7tvApi(search, ac.signal, { perPage: 60 }))
  else calls.push(Promise.resolve([]))
  const settled = await Promise.allSettled(calls)
  // Clear the in-flight flag on every exit path so a bailed fetch can't leave
  // "searching 7tv…" stuck on — but only if a newer fetch hasn't taken over
  // (token bumped), in which case that fetch now owns the flag.
  if (token === _acRemoteToken) acState.remotePending = false
  if (ac.signal.aborted || token !== _acRemoteToken) return
  // Cycling must still be on the same search the fetch was issued for.
  if (!acState.active || acState.search !== search) return
  acState.remoteDone = true
  const rf = settled[0]?.status === 'fulfilled' && Array.isArray(settled[0].value) ? settled[0].value : []
  const rb = settled[1]?.status === 'fulfilled' && Array.isArray(settled[1].value) ? settled[1].value : []
  const r7 = settled[2]?.status === 'fulfilled' && Array.isArray(settled[2].value) ? settled[2].value : []
  // FFZ's `uses` is real popularity — sort descending so the merged stream
  // leads with highest-use FFZ emotes first.
  rf.sort((a, b) => (b.uses || 0) - (a.uses || 0))
  const items = [...rf, ...rb, ...r7]
  // Lowercase dedupe (collapses 10x "Sadge" uploads to one — emote names are
  // case-insensitive in practice; first-seen wins so FFZ's top result holds).
  // Also dedupes against existing locals (already lowercased below).
  const have = new Set(acState.matches.map((m) => (m.name || '').toLowerCase()))
  const searchLower = search.toLowerCase()
  const add = []
  for (const it of items) {
    if (!it.name) continue
    const lower = it.name.toLowerCase()
    if (have.has(lower)) continue
    // Prefix-only: catalog substring matches are noise.
    if (!lower.startsWith(searchLower)) continue
    have.add(lower)
    const src = it.provider || '7tv'
    add.push({
      name: it.name,
      url: it.url,
      source: src,
      priority: 0,
      type: 'emote',
      remote: true,
      zeroWidth: !!it.zeroWidth,
      _ai: add.length,
    })
    // Remember for auto-add-on-send (only matters if the user actually sends it).
    recentRemoteCompletions.delete(it.name)
    recentRemoteCompletions.set(it.name, { url: it.url, source: src, zeroWidth: !!it.zeroWidth })
    while (recentRemoteCompletions.size > REMOTE_COMPLETION_CAP) {
      recentRemoteCompletions.delete(recentRemoteCompletions.keys().next().value)
    }
  }
  if (!add.length) return
  const wasEmpty = acState.matches.length === 0
  const prev = acState.matches[acState.index]
  acState.matches.push(...add.slice(0, 80))
  // Merged sort. Remote items keep their pre-merge order via `_ai`
  // (FFZ-by-uses → BTTV → 7TV), so cycling through remotes hits the highest
  // quality first regardless of provider.
  // Order:
  //   1. local > remote                       (channel / own set / globals beat catalog)
  //   2. local tier (channel > own > global)
  //   3. exact full-name match                (within tier)
  //   4. prefix > substring
  //   5. sub > non-sub
  //   6. MRU recent > never-used
  //   7. remote: _ai order (FFZ-by-uses → BTTV → 7TV)
  //   8. shorter prefix-match wins
  //   9. alpha
  // Tier outranks exact-match (user call) — a channel emote beats a coincidental
  // exact-cased global ("hug" → peepoHug, not "HuG"). Exact still wins within a tier.
  const _recentList = typeof loadRecentEmotes === 'function' ? loadRecentEmotes() : []
  const _recentRank = new Map()
  for (let i = 0; i < _recentList.length; i++) _recentRank.set(_recentList[i], i)
  acState.matches.sort((a, b) => {
    const al = a.remote ? 1 : 0,
      bl = b.remote ? 1 : 0
    if (al !== bl) return al - bl
    if (!a.remote && !b.remote) {
      const at = a.tier ?? 9,
        bt = b.tier ?? 9
      if (at !== bt) return at - bt
    }
    const ae = a.name.toLowerCase() === searchLower ? 0 : 1
    const be = b.name.toLowerCase() === searchLower ? 0 : 1
    if (ae !== be) return ae - be
    if (a.priority !== b.priority) return a.priority - b.priority
    if (!!a.sub !== !!b.sub) return a.sub ? -1 : 1
    const ar = _recentRank.get(a.name) ?? Infinity
    const br = _recentRank.get(b.name) ?? Infinity
    if (ar !== br) return ar - br
    if (a.remote && b.remote) return (a._ai || 0) - (b._ai || 0)
    if (a.priority === 0 && a.name.length !== b.name.length) return a.name.length - b.name.length
    return (a.name || '').localeCompare(b.name || '')
  })
  // Two cases land here:
  //   • wasEmpty — no local match existed when Tab was pressed, so this remote
  //     fetch fired immediately; insert the first remote hit now.
  //   • lazy — local matches existed and the user cycled to the end, triggering
  //     this fetch; keep their committed chip pinned and only re-point the index.
  //     Never async-swap a chip the user already cycled to (see
  //     heatsync_tabcomplete_exact_locality: async re-insert sent the wrong emote).
  if (wasEmpty && acState.matches.length > 0) {
    acState.index = 0
    insertCompletionKeepOpen(acState.matches[0])
  } else if (prev) {
    const ni = acState.matches.indexOf(prev)
    if (ni >= 0) acState.index = ni
  }
  showCycleTooltip() // refresh the N/M denominator
}

