          pp.style.setProperty('left', '0', 'important')
          pp.style.removeProperty('bottom')
          pp.style.removeProperty('right')
          pp.style.removeProperty('max-height')
          pp.style.removeProperty('height')
          pp.style.removeProperty('width')
